DO $seed$ DECLARE c jsonb; BEGIN
 FOR c IN SELECT value FROM jsonb_array_elements($corpus$[{"body":{"id":"physiographic-divisions","subject":"geography","unit":"India Physical","tags":["himalayas","northern-plains","peninsular-plateau","thar","coasts","islands","aravalli","western-ghats"],"title":"Physiographic Divisions of India","summary":"The six physical regions that make up India — and the geological story behind each.","focus":"India has six physiographic divisions, each born of a different geological process: collision-built mountains, alluvium-built plains, ancient stable plateau, sand desert, sediment-built coasts, and offshore islands of coral and volcano.","view":{"center":[22.5,80],"zoom":5},"basemap":"physical","layers":[{"id":"northern-mountains","name":"1. Northern & NE Mountains","description":"Himalayas + Purvanchal. Young fold mountains formed by India–Eurasia collision.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"himalayas","name":"Himalayan Mountains","sub":"Greater + Lesser + Shiwaliks, Indus to Brahmaputra"},"geometry":{"type":"Polygon","coordinates":[[[74,32.5],[78,30.5],[81,30],[85,28],[88.5,27],[92,27.5],[95.5,28.5],[97,29.5],[95,30],[89,29.5],[82,31],[76,33.5],[74,32.5]]]}},{"type":"Feature","properties":{"id":"purvanchal","name":"Purvanchal (NE Hills)","sub":"Patkai, Naga, Manipur, Mizo & Tripura Hills"},"geometry":{"type":"Polygon","coordinates":[[[93,27],[97,27.5],[97.5,24],[94.5,22],[92.5,22],[91.5,24],[92,26],[93,27]]]}}]},"defaultOn":true,"labelKey":"name","style":{"color":"#5e4a8a","fillColor":"#9b8ac4","fillOpacity":0.5,"weight":2,"shadow":true}},{"id":"northern-plains","name":"2. Northern Plains","description":"Indo-Gangetic-Brahmaputra plains. Alluvium from Indus, Ganga, Brahmaputra.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"northern-plains","name":"Northern Plains (Indo-Gangetic-Brahmaputra)","sub":"Formed by alluvium from Indus, Ganga, Brahmaputra. ~2400 km long, 240–320 km wide."},"geometry":{"type":"Polygon","coordinates":[[[74,31],[78.5,30],[83,28.5],[87,27],[89.5,26.5],[92.5,26.5],[92.5,24.5],[88,24],[84,24.5],[78,25.5],[74.5,27.5],[74,31]]]}}]},"defaultOn":true,"labelKey":"name","style":{"color":"#7a8a3a","fillColor":"#c5d086","fillOpacity":0.55,"weight":2}},{"id":"peninsular-plateau","name":"3. Peninsular Plateau","description":"India’s oldest landmass. Part of ancient Gondwana. Triangular.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"peninsular-plateau","name":"Peninsular Plateau","sub":"Oldest landmass of India — part of ancient Gondwana. Triangular, Deccan + Central Highlands."},"geometry":{"type":"Polygon","coordinates":[[[72.5,22],[78,24],[85,24],[87,22],[86.5,18],[85,14],[80,11],[77.5,8.5],[75,12],[73,16],[72.5,19],[72.5,22]]]}}]},"defaultOn":true,"labelKey":"name","style":{"color":"#8a5a3a","fillColor":"#c9a47a","fillOpacity":0.45,"weight":2,"pattern":"dots"}},{"id":"indian-desert","name":"4. Indian Desert (Thar)","description":"Arid sand plain in western Rajasthan. India’s only true desert.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"thar-desert","name":"Thar Desert","sub":"Arid sandy plain. Mostly in western Rajasthan. <250 mm rainfall."},"geometry":{"type":"Polygon","coordinates":[[[69.5,24.5],[73.5,24],[75,26.5],[74.5,29],[72,29.5],[70,28.5],[69.5,24.5]]]}}]},"defaultOn":true,"labelKey":"name","style":{"color":"#c46a3d","fillColor":"#e8c590","fillOpacity":0.6,"weight":2}},{"id":"coastal-plains","name":"5. Coastal Plains","description":"Eastern and Western coastal plains — narrow strips along the Peninsula.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"western-coastal-plain","name":"Western Coastal Plain","sub":"Narrow (50–100 km). Konkan + Kanara + Malabar. Faces Arabian Sea."},"geometry":{"type":"Polygon","coordinates":[[[72.5,20.5],[73.5,20],[74.5,16],[75.5,12],[76.5,8.5],[75.5,8.5],[74,11.5],[73,15.5],[72.5,19.5],[72.5,20.5]]]}},{"type":"Feature","properties":{"id":"eastern-coastal-plain","name":"Eastern Coastal Plain","sub":"Wider (100–130 km). Northern Circars + Coromandel. Faces Bay of Bengal. Major deltas."},"geometry":{"type":"Polygon","coordinates":[[[85.5,20.5],[87.5,21],[87.5,19.5],[85,16],[82,13],[80.5,10.5],[79.5,8.5],[78.5,9.5],[80.5,13],[83,16.5],[85.5,20.5]]]}}]},"defaultOn":true,"labelKey":"name","style":{"color":"#3a7a8a","fillColor":"#86c1d0","fillOpacity":0.55,"weight":2}},{"id":"islands","name":"6. Islands","description":"Andaman & Nicobar (volcanic) + Lakshadweep (coral).","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"andaman-nicobar","name":"Andaman & Nicobar Islands","sub":"Volcanic / tectonic origin. Bay of Bengal. Southward extension of the Arakan Yoma."},"geometry":{"type":"Polygon","coordinates":[[[92.2,13.7],[93.2,13.7],[94.3,9],[93.8,6.7],[92.5,6.7],[92.2,9],[92.2,13.7]]]}},{"type":"Feature","properties":{"id":"lakshadweep","name":"Lakshadweep Islands","sub":"Coral atolls. Arabian Sea. Formed over Reunion Hotspot volcanism."},"geometry":{"type":"Polygon","coordinates":[[[71.5,12.4],[74.1,12.4],[74.1,8],[71.5,8],[71.5,12.4]]]}}]},"defaultOn":true,"labelKey":"name","style":{"color":"#3a8a5a","fillColor":"#86d0a8","fillOpacity":0.6,"weight":2}},{"id":"himalayan-ranges","name":"Himalayan Ranges (3 parallel)","description":"Shiwaliks (Outer), Himachal (Lesser), Himadri (Greater) — three roughly parallel arcs.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"shiwaliks","name":"Shiwaliks (Outer Himalayas)","range":"shiwalik"},"geometry":{"type":"LineString","coordinates":[[74.5,32.4],[77.5,30.7],[81,29.8],[85,27.8],[88.5,26.9],[92,27.3]]}},{"type":"Feature","properties":{"id":"himachal","name":"Himachal (Lesser Himalayas)","range":"himachal"},"geometry":{"type":"LineString","coordinates":[[74.2,32.9],[77.5,31.3],[81,30.4],[85,28.4],[88.5,27.5],[92.5,28]]}},{"type":"Feature","properties":{"id":"himadri","name":"Himadri (Greater Himalayas) — contains Mt. Everest","range":"himadri"},"geometry":{"type":"LineString","coordinates":[[74,33.5],[77.5,32],[81,31],[85,29],[88,28],[92.5,29],[95.5,29]]}}]},"defaultOn":false,"labelKey":"name","style":{"color":"#5e4a8a","weight":2.5}},{"id":"plains-subdivisions","name":"Plains Subdivisions","description":"Bhabar (pebble), Tarai (marshy), then Bhangar (older alluvium) and Khadar (newer alluvium).","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"bhabar","name":"Bhabar","desc":"Pebble belt at foot of Shiwaliks. Rivers disappear underground. Not cultivable."},"geometry":{"type":"LineString","coordinates":[[74.5,31],[78,29.7],[81.5,28.9],[85,27],[88.5,26.4],[92,26.4]]}},{"type":"Feature","properties":{"id":"tarai","name":"Tarai","desc":"Marshy belt south of Bhabar. Rivers re-emerge. Very fertile. Jim Corbett, Kaziranga lie here."},"geometry":{"type":"LineString","coordinates":[[74.5,30.5],[78,29.2],[81.5,28.4],[85,26.5],[88.5,25.9],[92,25.9]]}}]},"defaultOn":false,"labelKey":"name","style":{"color":"#7a8a3a","weight":2.5,"dashArray":"5 4"}},{"id":"key-peaks","name":"Key Peaks & Landmarks","description":"Highest points of each region — the ones UPSC asks about.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"everest","name":"Mt. Everest (8848 m) — Nepal/China, on Himadri"},"geometry":{"type":"Point","coordinates":[86.925,27.9881]}},{"type":"Feature","properties":{"id":"k2","name":"K2 (8611 m) — PoK, Karakoram"},"geometry":{"type":"Point","coordinates":[76.5133,35.8825]}},{"type":"Feature","properties":{"id":"kanchenjunga","name":"Kanchenjunga (8586 m) — highest peak in India (Sikkim)"},"geometry":{"type":"Point","coordinates":[88.1475,27.7025]}},{"type":"Feature","properties":{"id":"nanda-devi","name":"Nanda Devi (7816 m) — Uttarakhand"},"geometry":{"type":"Point","coordinates":[79.9707,30.376]}},{"type":"Feature","properties":{"id":"anaimudi","name":"Anaimudi (2695 m) — highest peak in Peninsular India (Kerala)"},"geometry":{"type":"Point","coordinates":[77.06,10.17]}},{"type":"Feature","properties":{"id":"phawngpui","name":"Phawngpui / Blue Mountain (2157 m) — highest peak in Mizoram"},"geometry":{"type":"Point","coordinates":[92.8333,23.1667]}},{"type":"Feature","properties":{"id":"guru-shikhar","name":"Guru Shikhar (1722 m) — highest in Aravallis (Rajasthan)"},"geometry":{"type":"Point","coordinates":[72.71,24.66]}},{"type":"Feature","properties":{"id":"saddle-peak","name":"Saddle Peak (737 m) — highest in Andamans"},"geometry":{"type":"Point","coordinates":[93.0167,13.15]}},{"type":"Feature","properties":{"id":"barren-island","name":"Barren Island — India’s only active volcano"},"geometry":{"type":"Point","coordinates":[93.8597,12.2778]}}]},"defaultOn":true,"labelKey":"name"}],"facts":[{"id":"f1","text":"India has six physiographic divisions: Northern & NE Mountains, Northern Plains, Peninsular Plateau, Indian Desert, Coastal Plains, and Islands. The Peninsular Plateau is the oldest; the Himalayas and the Northern Plains are the youngest."},{"id":"f2","text":"The Himalayas are young fold mountains, formed by the ongoing collision of the Indo-Australian plate with the Eurasian plate (started about 50 million years ago). They stretch ~2,400 km from the Indus in the west to the Brahmaputra in the east.","linkedLayerId":"northern-mountains"},{"id":"f3","text":"The Himalayas have three parallel ranges, from south to north: Shiwaliks (Outer, 900–1,100 m), Himachal/Lesser (3,500–4,500 m), and Himadri/Greater (>6,000 m, with peaks above 8,000 m). The Trans-Himalayas lie further north and include the Karakoram, Ladakh, and Zaskar ranges.","linkedLayerId":"himalayan-ranges"},{"id":"f4","text":"The Purvanchal (Eastern Hills) are a southward continuation of the Himalayas after the Dihang gorge. They include the Patkai, Naga, Manipur, and Mizo (Lushai) Hills — the entire chain runs largely north–south.","linkedLayerId":"northern-mountains","linkedFeatureId":"purvanchal"},{"id":"f5","text":"Mizoram lies almost entirely within the Mizo Hills, part of the Patkai–Arakan Yoma system. Phawngpui (Blue Mountain), 2,157 m, is the highest peak in Mizoram. About 90% of the state is hilly terrain.","linkedFeatureId":"phawngpui"},{"id":"f6","text":"The Northern Plains were formed by alluvial deposits from the Indus, Ganga, and Brahmaputra systems filling a depression between the rising Himalayas and the old Peninsular block. The plain is ~2,400 km long and 240–320 km wide.","linkedLayerId":"northern-plains"},{"id":"f7","text":"The Northern Plains are divided into four sub-belts from north to south: Bhabar (8–16 km pebble belt at Shiwalik foot — rivers go underground), Tarai (marshy, very fertile — Corbett & Kaziranga are here), Bhangar (older alluvium with calcareous \"kankar\" nodules), and Khadar (newer alluvium, flooded yearly, most fertile).","linkedLayerId":"plains-subdivisions"},{"id":"f8","text":"The Peninsular Plateau is India’s oldest landmass — part of the ancient Gondwana supercontinent. It is geologically stable, rich in minerals, and triangular in shape, bounded by the Aravallis (NW), Vindhya-Satpura (N), Western Ghats (W), and Eastern Ghats (E).","linkedLayerId":"peninsular-plateau"},{"id":"f9","text":"The Peninsular Plateau has two major sub-regions: the Central Highlands (north of the Narmada — Malwa, Bundelkhand, Chotanagpur plateaus) and the Deccan Plateau (south of the Narmada, the larger half).","linkedLayerId":"peninsular-plateau"},{"id":"f10","text":"The Thar Desert (Indian Desert) lies west of the Aravallis, mostly in western Rajasthan. It receives less than 250 mm of rain a year, has shifting sand dunes (barchans), and an underground stream system fed by the now-vanished Ghaggar-Hakra (ancient Saraswati) river.","linkedLayerId":"indian-desert"},{"id":"f11","text":"The Western Coastal Plain is narrow (50–100 km), faces the Arabian Sea, and is divided into Konkan (north), Kanara (middle), and Malabar (south). The Western Ghats rise sharply behind it.","linkedLayerId":"coastal-plains","linkedFeatureId":"western-coastal-plain"},{"id":"f12","text":"The Eastern Coastal Plain is wider (100–130 km), faces the Bay of Bengal, and is divided into Northern Circars (north) and Coromandel (south). All major peninsular rivers — Mahanadi, Godavari, Krishna, Kaveri — form deltas here.","linkedLayerId":"coastal-plains","linkedFeatureId":"eastern-coastal-plain"},{"id":"f13","text":"The Andaman & Nicobar Islands (Bay of Bengal) are of volcanic/tectonic origin — a southward continuation of the Arakan Yoma. They are separated from each other by the 10° Channel. Saddle Peak (737 m) in North Andaman is their highest point. Barren Island is the only active volcano in India.","linkedLayerId":"islands","linkedFeatureId":"andaman-nicobar"},{"id":"f14","text":"The Lakshadweep Islands (Arabian Sea) are coral atolls formed over volcanic seamounts of the Reunion Hotspot. They include around 36 islands; Kavaratti is the capital. They are flat and low-lying — highly vulnerable to sea-level rise.","linkedLayerId":"islands","linkedFeatureId":"lakshadweep"},{"id":"f15","text":"Highest peaks to remember: Kanchenjunga (8,586 m) is the highest peak entirely within India (Sikkim). Anaimudi (2,695 m) is the highest in Peninsular India (Kerala). Guru Shikhar (1,722 m) is the highest in the Aravallis. Phawngpui (2,157 m) is the highest in Mizoram. K2 (8,611 m) lies in PoK — administered by Pakistan, claimed by India.","linkedLayerId":"key-peaks"}],"quiz":[{"id":"q1","type":"mcq","question":"Which of the six physiographic divisions of India is the geologically oldest?","options":["The Himalayan Mountains","The Northern Plains","The Peninsular Plateau","The Coastal Plains"],"answerIndex":2,"explanation":"The Peninsular Plateau is part of the ancient Gondwana supercontinent — it is India’s oldest and most stable landmass. The Himalayas and the Northern Plains are the youngest."},{"id":"q2","type":"map_click","question":"Click the location of Phawngpui (Blue Mountain), the highest peak in Mizoram.","answer":{"lat":22.6333,"lng":93.0167,"toleranceKm":150},"explanation":"Phawngpui (2,157 m) lies in southeastern Mizoram, near the Myanmar border. It is part of the Mizo Hills, which belong to the Patkai–Arakan Yoma system of the Purvanchal Range."},{"id":"q3","type":"mcq","question":"Which sub-belt of the Northern Plains is characterized by pebble beds where rivers descending from the Himalayas disappear underground?","options":["Bhangar","Khadar","Tarai","Bhabar"],"answerIndex":3,"explanation":"Bhabar is the 8–16 km wide pebble belt at the foot of the Shiwaliks. The pebble beds are so porous that streams sink and flow underground. They re-emerge in the Tarai belt just to the south."},{"id":"q4","type":"mcq","question":"The Andaman & Nicobar Islands are best described as:","options":["Coral atolls formed over volcanic seamounts","A southward extension of the Arakan Yoma mountains, of volcanic/tectonic origin","A continental shelf detached from the Peninsular Plateau","Sediment islands built up by the Brahmaputra delta"],"answerIndex":1,"explanation":"The Andaman & Nicobar Islands are a southward continuation of the Arakan Yoma (which in turn extends from the Purvanchal). They are of volcanic/tectonic origin. Barren Island is India’s only active volcano. Lakshadweep — the other island group — is the coral one."},{"id":"q5","type":"map_click","question":"Click anywhere in the Thar Desert.","answer":{"lat":27,"lng":71.5,"toleranceKm":280},"explanation":"The Thar Desert lies in western Rajasthan, west of the Aravalli range. It receives less than 250 mm of rainfall a year and is the only true desert in India."},{"id":"q6","type":"mcq","question":"Which is the highest peak entirely within Indian territory?","options":["Mt. Everest","K2","Kanchenjunga","Nanda Devi"],"answerIndex":2,"explanation":"Kanchenjunga (8,586 m) in Sikkim. Everest is in Nepal/China. K2 (8,611 m) is in Pakistan-administered Kashmir — claimed by India but not under Indian administration. Nanda Devi (7,816 m) is the highest peak entirely within India’s undisputed territory in the mainland but Kanchenjunga is taller."},{"id":"q7","type":"map_click","question":"Click the location of Kanchenjunga, the highest peak entirely in India.","answer":{"lat":27.7025,"lng":88.1475,"toleranceKm":150},"explanation":"Kanchenjunga lies on the Sikkim–Nepal border in the Greater Himalayas (Himadri). At 8,586 m it is the third-highest mountain in the world."},{"id":"q8","type":"mcq","question":"The Western Coastal Plain differs from the Eastern Coastal Plain in that:","options":["The Western is wider and has major river deltas","The Eastern is narrower and faces the Arabian Sea","The Western is narrower (50–100 km) and has fewer deltas; the Eastern is wider (100–130 km) with major deltas of the Mahanadi, Godavari, Krishna and Kaveri","They are identical in width and drainage"],"answerIndex":2,"explanation":"The Western Coastal Plain is narrow and steep (Western Ghats rise sharply behind it); rivers cross it quickly into the Arabian Sea without forming large deltas. The Eastern Coastal Plain is wider and gentler, allowing the Mahanadi, Godavari, Krishna, and Kaveri to all build large deltas before reaching the Bay of Bengal."}]},"position":0,"hash":"5a0b2022f3320215dbd7266a09d748e293b14b50a207218715216e1004458562"},{"body":{"id":"mountains-and-passes","subject":"geography","unit":"India Physical","tags":["himalayas","aravalli","western-ghats","purvanchal","khyber","passes","mizo-hills","peninsular-plateau"],"title":"Mountains & Passes of India","summary":"The young Himalayas, the ancient Peninsular ranges, and the strategic passes that connect India to the world.","focus":"India has two kinds of mountains: the young, still-rising Himalayas (and the Purvanchal’s curve into Mizoram) and the ancient, eroded Peninsular ranges. Where these mountains have notches — the passes — trade, pilgrimage, war, and modern strategy converge.","view":{"center":[25,82],"zoom":5},"basemap":"physical","layers":[{"id":"himalayan-ranges","name":"Himalayan Ranges (4 parallel zones)","description":"Trans-Himalayas (north) — Himadri — Himachal — Shiwaliks (south). Young fold mountains, still rising.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"trans-himalaya","name":"Trans-Himalayas (Karakoram, Ladakh, Zaskar, Kailash)"},"geometry":{"type":"LineString","coordinates":[[76,35.5],[78,35],[80.5,34.5],[82,32.5]]}},{"type":"Feature","properties":{"id":"himadri","name":"Himadri / Greater Himalayas (highest, >6000 m)"},"geometry":{"type":"LineString","coordinates":[[74,33.5],[77.5,32],[81,31],[85,29],[88,28],[92.5,29],[95.5,29]]}},{"type":"Feature","properties":{"id":"himachal","name":"Himachal / Lesser Himalayas (3500–4500 m)"},"geometry":{"type":"LineString","coordinates":[[74.2,32.9],[77.5,31.3],[81,30.4],[85,28.4],[88.5,27.5],[92.5,28]]}},{"type":"Feature","properties":{"id":"shiwaliks","name":"Shiwaliks / Outer Himalayas (900–1100 m)"},"geometry":{"type":"LineString","coordinates":[[74.5,32.4],[77.5,30.7],[81,29.8],[85,27.8],[88.5,26.9],[92,27.3]]}}]},"defaultOn":true,"labelKey":"name","style":{"color":"#5e4a8a","weight":3}},{"id":"peninsular-ranges","name":"Peninsular Ranges","description":"Western Ghats, Eastern Ghats, Aravalli, Vindhya, Satpura, Purvanchal. Ancient, weathered, lower.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"wghats","name":"Western Ghats / Sahyadri (UNESCO WHS)"},"geometry":{"type":"LineString","coordinates":[[73,21],[73.5,19],[74.5,16],[75.5,12],[77,8.5]]}},{"type":"Feature","properties":{"id":"eghats","name":"Eastern Ghats (broken hill ranges)"},"geometry":{"type":"LineString","coordinates":[[86,21.5],[84.5,19.5],[83,18],[81.5,15.5],[80,13.5],[78.5,11.5]]}},{"type":"Feature","properties":{"id":"aravalli","name":"Aravalli Range (one of the world’s oldest, ~1.7 bn yrs)"},"geometry":{"type":"LineString","coordinates":[[72.7,24.6],[73.8,25.5],[75.5,26.5],[77,28],[77.2,28.7]]}},{"type":"Feature","properties":{"id":"vindhya","name":"Vindhya Range (divides N and S India)"},"geometry":{"type":"LineString","coordinates":[[73.5,22.5],[76,23.5],[79,24],[82.5,24.5],[85,24]]}},{"type":"Feature","properties":{"id":"satpura","name":"Satpura Range (south of Vindhyas, between Narmada & Tapi)"},"geometry":{"type":"LineString","coordinates":[[73.5,21.5],[76.5,22],[79,22.3],[81.5,22.5],[83.5,22.5]]}},{"type":"Feature","properties":{"id":"purvanchal-r","name":"Purvanchal (Patkai–Naga–Manipur–Mizo–Tripura Hills)"},"geometry":{"type":"LineString","coordinates":[[95.5,28],[95,26.5],[94.5,25],[93.5,23.5],[92.8,22.5],[91.5,23.5]]}}]},"defaultOn":true,"labelKey":"name","style":{"color":"#8a5a3a","weight":2.5}},{"id":"key-peaks","name":"Key Peaks (memorize these)","description":"Highest peaks by region — frequently tested.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"k2","name":"K2 / Godwin Austen (8611 m) — PoK, Karakoram"},"geometry":{"type":"Point","coordinates":[76.5133,35.8825]}},{"type":"Feature","properties":{"id":"kanchenjunga","name":"Kanchenjunga (8586 m) — highest peak entirely in India, Sikkim"},"geometry":{"type":"Point","coordinates":[88.1475,27.7025]}},{"type":"Feature","properties":{"id":"nanda-devi","name":"Nanda Devi (7816 m) — Uttarakhand"},"geometry":{"type":"Point","coordinates":[79.9707,30.376]}},{"type":"Feature","properties":{"id":"kamet","name":"Kamet (7756 m) — Uttarakhand"},"geometry":{"type":"Point","coordinates":[79.5933,30.92]}},{"type":"Feature","properties":{"id":"anaimudi","name":"Anaimudi (2695 m) — highest in Peninsular India, Kerala"},"geometry":{"type":"Point","coordinates":[77.06,10.17]}},{"type":"Feature","properties":{"id":"doddabetta","name":"Doddabetta (2637 m) — Nilgiris, Tamil Nadu"},"geometry":{"type":"Point","coordinates":[76.74,11.4]}},{"type":"Feature","properties":{"id":"mahendragiri","name":"Mahendragiri (1501 m) — Eastern Ghats, Odisha"},"geometry":{"type":"Point","coordinates":[84.3833,18.9667]}},{"type":"Feature","properties":{"id":"guru-shikhar","name":"Guru Shikhar (1722 m) — highest in Aravallis, Rajasthan"},"geometry":{"type":"Point","coordinates":[72.71,24.66]}},{"type":"Feature","properties":{"id":"phawngpui","name":"Phawngpui / Blue Mountain (2157 m) — highest in Mizoram"},"geometry":{"type":"Point","coordinates":[92.8333,23.1667]}},{"type":"Feature","properties":{"id":"dhupgarh","name":"Dhupgarh (1350 m) — highest in Satpura, MP"},"geometry":{"type":"Point","coordinates":[78.43,22.47]}}]},"defaultOn":true,"labelKey":"name"},{"id":"himalayan-passes","name":"Himalayan Passes","description":"Strategic crossings: trade routes, pilgrimage, military.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"karakoram-pass","name":"Karakoram Pass (5540 m, Ladakh) — India–China, ancient Silk Route"},"geometry":{"type":"Point","coordinates":[77.8167,35.5167]}},{"type":"Feature","properties":{"id":"khardung-la","name":"Khardung La (5359 m, Ladakh) — gateway to Nubra Valley"},"geometry":{"type":"Point","coordinates":[77.6047,34.2778]}},{"type":"Feature","properties":{"id":"zoji-la","name":"Zoji La (3580 m) — Srinagar to Leh (NH-1D); closed in winter"},"geometry":{"type":"Point","coordinates":[75.4719,34.2789]}},{"type":"Feature","properties":{"id":"banihal","name":"Banihal Pass (2832 m) — Jammu to Kashmir Valley; Jawahar Tunnel"},"geometry":{"type":"Point","coordinates":[75.1953,33.4928]}},{"type":"Feature","properties":{"id":"rohtang","name":"Rohtang Pass (3978 m, HP) — Manali to Lahaul-Spiti; Atal Tunnel beneath"},"geometry":{"type":"Point","coordinates":[77.2461,32.3725]}},{"type":"Feature","properties":{"id":"shipki-la","name":"Shipki La (3930 m, HP) — India–Tibet, Satluj enters here"},"geometry":{"type":"Point","coordinates":[78.75,31.8167]}},{"type":"Feature","properties":{"id":"baralacha","name":"Baralacha La (4890 m) — junction for Lahaul, Spiti, Zanskar, Ladakh"},"geometry":{"type":"Point","coordinates":[77.4422,32.7567]}},{"type":"Feature","properties":{"id":"lipulekh","name":"Lipulekh Pass (5334 m, Uttarakhand) — Kailash Mansarovar route"},"geometry":{"type":"Point","coordinates":[81.0167,30.2333]}},{"type":"Feature","properties":{"id":"mana","name":"Mana Pass (5610 m, Uttarakhand) — India–Tibet"},"geometry":{"type":"Point","coordinates":[79.45,31.0833]}},{"type":"Feature","properties":{"id":"niti","name":"Niti Pass (5070 m, Uttarakhand) — ancient Tibet trade route"},"geometry":{"type":"Point","coordinates":[79.8833,30.7833]}},{"type":"Feature","properties":{"id":"nathu-la","name":"Nathu La (4310 m, Sikkim) — India–China trade reopened 2006"},"geometry":{"type":"Point","coordinates":[88.8333,27.3833]}},{"type":"Feature","properties":{"id":"jelep-la","name":"Jelep La (4267 m, Sikkim) — India–Tibet"},"geometry":{"type":"Point","coordinates":[88.7333,27.3667]}},{"type":"Feature","properties":{"id":"bomdi-la","name":"Bomdi La (2217 m, Arunachal) — to Tawang and Lhasa"},"geometry":{"type":"Point","coordinates":[92.4167,27.2667]}},{"type":"Feature","properties":{"id":"bum-la","name":"Bum La Pass (4633 m, Arunachal) — Tawang to Tibet"},"geometry":{"type":"Point","coordinates":[91.7333,27.75]}},{"type":"Feature","properties":{"id":"diphu","name":"Diphu Pass (4587 m, Arunachal) — India–China–Myanmar tripoint"},"geometry":{"type":"Point","coordinates":[97.1833,28.15]}},{"type":"Feature","properties":{"id":"umling-la","name":"Umling La (5882 m, Ladakh) — highest motorable pass in the world"},"geometry":{"type":"Point","coordinates":[78.6167,32.6167]}}]},"defaultOn":false,"labelKey":"name"},{"id":"ghat-passes","name":"Western/Eastern Ghats Passes","description":"Gaps in the Peninsular ranges — small but economically vital.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"palghat","name":"Palakkad Gap (~140 km wide) — main breach in Western Ghats; Kerala–TN"},"geometry":{"type":"Point","coordinates":[76.65,10.77]}},{"type":"Feature","properties":{"id":"thal-ghat","name":"Thal Ghat — Mumbai to Nashik (Maharashtra)"},"geometry":{"type":"Point","coordinates":[73.55,19.7]}},{"type":"Feature","properties":{"id":"bhor-ghat","name":"Bhor Ghat — Mumbai to Pune"},"geometry":{"type":"Point","coordinates":[73.35,18.75]}},{"type":"Feature","properties":{"id":"shenkottai","name":"Shenkottai Pass — Tamil Nadu to Kerala"},"geometry":{"type":"Point","coordinates":[77.27,8.97]}}]},"defaultOn":false,"labelKey":"name"}],"facts":[{"id":"f1","text":"India’s mountains divide into two families: the young fold Himalayas in the north (still rising due to ongoing India-Eurasia collision) and the ancient block-mountain ranges of the Peninsula (worn down over hundreds of millions of years)."},{"id":"f2","text":"The Himalayas have four parallel zones north-to-south: (1) Trans-Himalayas — Karakoram, Ladakh, Zaskar (cold desert, K2 is here); (2) Himadri / Greater Himalayas — highest range, >6,000 m, contains Everest, Kanchenjunga, Nanda Devi; (3) Himachal / Lesser Himalayas — 3,500–4,500 m, hill stations; (4) Shiwaliks / Outer Himalayas — youngest, 900–1,100 m, formed from river sediments.","linkedLayerId":"himalayan-ranges"},{"id":"f3","text":"The Himalayas run ~2,400 km from the Indus gorge in the west to the Brahmaputra gorge in the east. They are wider in the west (~400 km in Kashmir) and narrower in the east (~150 km in Arunachal). Beyond the Dihang/Brahmaputra gorge, they curve south as the Purvanchal Ranges.","linkedLayerId":"himalayan-ranges"},{"id":"f4","text":"The Purvanchal is the southward curve of the Himalayan system after the Dihang gorge — Patkai, Naga, Manipur, Mizo (Lushai), Tripura Hills. They run north–south (unlike the Himalayas which run east–west). The Mizo Hills, in which all of Mizoram lies, are part of this system.","linkedLayerId":"peninsular-ranges","linkedFeatureId":"purvanchal-r"},{"id":"f5","text":"Peninsular ranges (oldest first): The Aravalli (~1.7 billion years old, one of the oldest mountain ranges on Earth) runs NE-SW through Rajasthan; Guru Shikhar (1722 m) is the highest point. The Vindhya and Satpura ranges divide North from South India and frame the Narmada rift valley between them.","linkedLayerId":"peninsular-ranges"},{"id":"f6","text":"The Western Ghats (Sahyadri) run ~1,600 km along the west coast, with the Arabian Sea on one side and the Deccan Plateau on the other. They are a UNESCO World Heritage Site and one of the world’s eight \"hottest\" biodiversity hotspots. Highest peak: Anaimudi (2,695 m) in Kerala — the highest in Peninsular India.","linkedLayerId":"peninsular-ranges","linkedFeatureId":"wghats"},{"id":"f7","text":"The Eastern Ghats are NOT continuous — they are broken into discontinuous hill groups by the great east-flowing rivers (Mahanadi, Godavari, Krishna, Kaveri). They are lower, older, and more eroded than the Western Ghats. Highest peak: Mahendragiri (1,501 m) in Odisha.","linkedLayerId":"peninsular-ranges","linkedFeatureId":"eghats"},{"id":"f8","text":"Highest peak quick reference: K2 (8,611 m) — PoK, claimed by India. Kanchenjunga (8,586 m) — highest peak ENTIRELY within India. Nanda Devi (7,816 m) — second-highest entirely in India’s undisputed territory. Anaimudi (2,695 m) — highest in Peninsular India. Phawngpui (2,157 m) — highest in Mizoram and the entire Purvanchal.","linkedLayerId":"key-peaks"},{"id":"f9","text":"Karakoram Pass (5,540 m, Ladakh) connects India to China’s Xinjiang — part of the ancient Silk Route. Zoji La (3,580 m) is the strategic pass on the Srinagar–Leh highway, closed by snow in winter — a Zoji La tunnel is under construction for all-weather access.","linkedLayerId":"himalayan-passes"},{"id":"f10","text":"Rohtang Pass (3,978 m, Himachal Pradesh) connected Manali to Lahaul-Spiti seasonally. Today, the Atal Tunnel (opened 2020, 9.02 km) runs beneath it — once the world’s longest highway tunnel above 10,000 ft — giving all-weather access to Leh.","linkedLayerId":"himalayan-passes","linkedFeatureId":"rohtang"},{"id":"f11","text":"Nathu La (4,310 m, Sikkim) was reopened for limited India–China border trade in 2006 after being closed since the 1962 war. Jelep La (next to Nathu La) was the historic route to Lhasa used by the British. Bomdi La and Bum La (Arunachal) lead to Tawang and Tibet.","linkedLayerId":"himalayan-passes","linkedFeatureId":"nathu-la"},{"id":"f12","text":"Lipulekh Pass (5,334 m, Uttarakhand) is the traditional pilgrim route to Kailash-Mansarovar; the recent road extension to the pass triggered a 2020 border dispute with Nepal. Mana and Niti passes (also Uttarakhand) are old Tibet trade routes.","linkedLayerId":"himalayan-passes"},{"id":"f13","text":"Umling La (5,882 m, Ladakh) is the highest motorable pass in the world — constructed by the Border Roads Organisation. Khardung La (5,359 m) leads from Leh to the Nubra Valley and Siachen.","linkedLayerId":"himalayan-passes"},{"id":"f14","text":"Western Ghats passes: the Palakkad Gap is the largest breach (~140 km wide) and the main route between Kerala and Tamil Nadu — it shapes monsoon patterns by letting moist air through. Thal Ghat (Mumbai–Nashik) and Bhor Ghat (Mumbai–Pune) carry Maharashtra’s busiest road and rail traffic.","linkedLayerId":"ghat-passes"},{"id":"f15","text":"Mizoram-specific: the Mizo Hills run north–south through the state and continue south into Myanmar’s Chin State as the Arakan Yoma. Phawngpui (Blue Mountain) at 2,157 m is the highest. Several smaller hill ranges — Tlawng Hill, Lurh Tlang, and others — give Mizoram its distinctive ridge-and-valley topography."}],"quiz":[{"id":"q1","type":"mcq","question":"Arrange the Himalayan ranges from NORTH to SOUTH:","options":["Shiwaliks → Himachal → Himadri → Trans-Himalayas","Trans-Himalayas → Himadri → Himachal → Shiwaliks","Himachal → Trans-Himalayas → Himadri → Shiwaliks","Himadri → Shiwaliks → Himachal → Trans-Himalayas"],"answerIndex":1,"explanation":"From north to south: Trans-Himalayas (Karakoram, etc.) → Himadri / Greater Himalayas (highest) → Himachal / Lesser Himalayas (hill stations) → Shiwaliks / Outer Himalayas (youngest, lowest). The Shiwaliks are closest to the plains."},{"id":"q2","type":"mcq","question":"Why are the Eastern Ghats NOT continuous, unlike the Western Ghats?","options":["They are blocked by deserts","They are broken into segments by the great east-flowing rivers (Mahanadi, Godavari, Krishna, Kaveri)","They were destroyed by ancient volcanoes","They never formed continuously"],"answerIndex":1,"explanation":"The east-flowing peninsular rivers cut through the Eastern Ghats on their way to the Bay of Bengal, breaking the range into discontinuous hill groups. The Western Ghats remain unbroken because most west-flowing rivers (except Narmada and Tapi) are short coastal streams."},{"id":"q3","type":"map_click","question":"Click the location of Phawngpui (Blue Mountain) — highest peak in Mizoram and the Purvanchal range.","answer":{"lat":22.6333,"lng":92.8333,"toleranceKm":150},"explanation":"Phawngpui (2,157 m) is in southeastern Mizoram, near the Myanmar border. It is the highest point in the entire Purvanchal range that stretches from Arunachal Pradesh down through Nagaland, Manipur, Mizoram, and Tripura."},{"id":"q4","type":"mcq","question":"Which pass connects Srinagar to Leh and is closed by snow most of winter?","options":["Rohtang Pass","Zoji La","Nathu La","Karakoram Pass"],"answerIndex":1,"explanation":"Zoji La (3,580 m) is on the Srinagar–Leh highway. It is among the most strategically important passes for India, and the Zoji La Tunnel (under construction) will make access all-weather."},{"id":"q5","type":"map_click","question":"Click the location of the Palakkad Gap — the main breach in the Western Ghats.","answer":{"lat":10.77,"lng":76.65,"toleranceKm":120},"explanation":"The Palakkad Gap (~140 km wide) is the largest break in the Western Ghats. It is the main route between Kerala and Tamil Nadu, and the gap also influences the monsoon — it lets moist air through to Tamil Nadu’s western interior."},{"id":"q6","type":"mcq","question":"Which Aravalli peak is the highest, located in Rajasthan?","options":["Anaimudi","Doddabetta","Guru Shikhar","Mahendragiri"],"answerIndex":2,"explanation":"Guru Shikhar (1,722 m) on Mount Abu is the highest peak in the Aravallis. Anaimudi is the highest in Peninsular India (Kerala). Doddabetta is in the Nilgiris. Mahendragiri is the highest in the Eastern Ghats."},{"id":"q7","type":"mcq","question":"Which pass, reopened in 2006 for limited India–China border trade, was previously closed after the 1962 war?","options":["Nathu La","Bomdi La","Karakoram Pass","Bum La"],"answerIndex":0,"explanation":"Nathu La (4,310 m) in Sikkim was reopened to limited bilateral trade in July 2006 after a 44-year closure following the 1962 Indo-China war. It remains one of the highest border-trading posts in the world."},{"id":"q8","type":"mcq","question":"The Atal Tunnel, opened in 2020, runs beneath which pass?","options":["Zoji La","Rohtang Pass","Banihal Pass","Khardung La"],"answerIndex":1,"explanation":"The Atal Tunnel (9.02 km) runs beneath Rohtang Pass in Himachal Pradesh — giving Manali and Lahaul-Spiti all-weather connectivity that the snow-prone pass itself never had."},{"id":"q9","type":"map_click","question":"Click the approximate location of Kanchenjunga — the highest peak entirely within India.","answer":{"lat":27.7,"lng":88.15,"toleranceKm":150},"explanation":"Kanchenjunga (8,586 m) lies on the Sikkim–Nepal border in the Greater Himalayas. It is the third-highest mountain in the world and the highest peak entirely within India’s undisputed territory."}]},"position":1,"hash":"787b780401b22bfa1e202380bbd060ea3d6e0882b7c13d03dc7e7ce430b27255"},{"body":{"id":"rivers-of-india","subject":"geography","unit":"India Physical","tags":["ganga","indus","jhelum","chenab","ravi","beas","sutlej","brahmaputra","godavari","krishna","kaveri","hooghly","tlawng","kaladan","northern-plains"],"title":"Rivers of India","summary":"The two great river families of India — and how their origin shapes their character.","focus":"Where a river is born decides what it is. Himalayan rivers (snow-fed, perennial, fertile floodplains) and Peninsular rivers (rain-fed, seasonal, mature stable courses) define almost every geography question about Indian water.","view":{"center":[22.5,80],"zoom":5},"basemap":"physical","layers":[{"id":"indus-system","name":"Indus System (5 tributaries)","description":"Indus + Jhelum, Chenab, Ravi, Beas, Satluj. Indus Waters Treaty: India gets eastern three (Ravi, Beas, Satluj); Pakistan gets western three (Indus, Jhelum, Chenab).","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"indus","name":"Indus (origin: Mansarovar, Tibet)"},"geometry":{"type":"LineString","coordinates":[[81.45,30.65],[79.5,32.5],[77.5,33.8],[75.8,34.5],[74,34],[72,33],[70.5,30],[68.5,27],[67.5,24],[67.3,23.5]]}},{"type":"Feature","properties":{"id":"jhelum","name":"Jhelum"},"geometry":{"type":"LineString","coordinates":[[75.2,33.7],[74.4,33.5],[73.3,32.7],[72,31.3]]}},{"type":"Feature","properties":{"id":"chenab","name":"Chenab"},"geometry":{"type":"LineString","coordinates":[[77.2,32.7],[75.6,33],[74,32.3],[72.4,30.5]]}},{"type":"Feature","properties":{"id":"ravi","name":"Ravi"},"geometry":{"type":"LineString","coordinates":[[77,32.4],[75.7,32.4],[74.9,31.7],[73.5,30.2]]}},{"type":"Feature","properties":{"id":"beas","name":"Beas"},"geometry":{"type":"LineString","coordinates":[[77.5,32.4],[76.5,31.8],[75.8,31],[74.9,30.7]]}},{"type":"Feature","properties":{"id":"satluj","name":"Satluj"},"geometry":{"type":"LineString","coordinates":[[81.4,30.7],[79,31],[76.8,31],[75.5,30.7],[74,30.5]]}}]},"defaultOn":true,"labelKey":"name","style":{"color":"#3a6a9a","weight":2.5,"flow":true}},{"id":"ganga-system","name":"Ganga System","description":"Ganga, Yamuna, and tributaries. Largest river basin in India.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"ganga","name":"Ganga (origin: Gangotri Glacier)"},"geometry":{"type":"LineString","coordinates":[[78.94,30.99],[78.4,30],[78,29.5],[78.2,28.5],[79.5,27.5],[81,26.5],[83,25.5],[85,25.4],[86.5,25.3],[87.5,24.6],[88,24],[88.4,23],[88.6,22],[89,21.6]]}},{"type":"Feature","properties":{"id":"yamuna","name":"Yamuna (origin: Yamunotri Glacier)"},"geometry":{"type":"LineString","coordinates":[[78.44,30.99],[78,30.5],[77.5,29.5],[77.3,28.5],[77.4,27.5],[78.5,26.5],[80,26],[81,25.7],[81.85,25.43]]}},{"type":"Feature","properties":{"id":"chambal","name":"Chambal (rises in Vindhyas, joins Yamuna)"},"geometry":{"type":"LineString","coordinates":[[75.3,22.4],[76,24],[76.8,25],[78,26.5],[79,26.5]]}},{"type":"Feature","properties":{"id":"son","name":"Son (rises in Amarkantak, joins Ganga)"},"geometry":{"type":"LineString","coordinates":[[81.75,22.65],[82,24],[83.5,25],[84.9,25.5]]}},{"type":"Feature","properties":{"id":"ghaghara","name":"Ghaghara"},"geometry":{"type":"LineString","coordinates":[[81,30.2],[81.5,29],[82,27.5],[83.5,26],[84.6,25.7]]}},{"type":"Feature","properties":{"id":"gandak","name":"Gandak"},"geometry":{"type":"LineString","coordinates":[[83.7,28.7],[84,27.5],[84.5,26.5],[85,25.6]]}},{"type":"Feature","properties":{"id":"kosi","name":"Kosi (Bihar’s Sorrow)"},"geometry":{"type":"LineString","coordinates":[[86.6,28],[86.7,27],[86.9,26],[87.2,25.4]]}}]},"defaultOn":true,"labelKey":"name","style":{"color":"#1d4f7a","weight":3,"flow":true}},{"id":"brahmaputra-system","name":"Brahmaputra System","description":"Brahmaputra and major NE tributaries including Subansiri, Manas, Teesta, Barak.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"brahmaputra","name":"Brahmaputra (Tibet: Tsangpo; Arunachal: Dihang)"},"geometry":{"type":"LineString","coordinates":[[82,30.7],[87,29.3],[91,29.5],[94.5,29.5],[95.5,28.5],[95,27.7],[94,27.5],[92.5,27],[90.5,26.5],[88.5,26],[86.5,25.5],[90,24],[90.5,23.5],[91,22.8]]}},{"type":"Feature","properties":{"id":"subansiri","name":"Subansiri (largest Brahmaputra tributary)"},"geometry":{"type":"LineString","coordinates":[[93.5,28.8],[94,28],[94.4,27.5]]}},{"type":"Feature","properties":{"id":"manas","name":"Manas"},"geometry":{"type":"LineString","coordinates":[[91,27.5],[90.8,26.8],[90.7,26.2]]}},{"type":"Feature","properties":{"id":"teesta","name":"Teesta"},"geometry":{"type":"LineString","coordinates":[[88.6,28],[88.5,27],[88.6,26.3],[89.5,25.8]]}},{"type":"Feature","properties":{"id":"barak","name":"Barak (drains NE hills, joins Meghna in Bangladesh)"},"geometry":{"type":"LineString","coordinates":[[93.5,24.5],[92.8,24.8],[92,24.8],[91.5,24.5],[91,24]]}}]},"defaultOn":true,"labelKey":"name","style":{"color":"#2a8a8a","weight":3,"flow":true}},{"id":"east-peninsular","name":"East-flowing Peninsular Rivers","description":"Mahanadi, Godavari, Krishna, Kaveri — all drain into the Bay of Bengal forming deltas.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"mahanadi","name":"Mahanadi (rises in Chhattisgarh)"},"geometry":{"type":"LineString","coordinates":[[81.3,20.1],[82,20.5],[83,21],[84.5,20.7],[86,20.5],[86.7,20.3]]}},{"type":"Feature","properties":{"id":"godavari","name":"Godavari — longest peninsular river (\"Dakshin Ganga\")"},"geometry":{"type":"LineString","coordinates":[[73.55,19.96],[74.5,20],[76,19.5],[77.5,19],[79,18.7],[80.5,18.3],[82,17.7],[82.3,16.9]]}},{"type":"Feature","properties":{"id":"krishna","name":"Krishna (rises at Mahabaleshwar)"},"geometry":{"type":"LineString","coordinates":[[73.65,17.92],[75,17.5],[76.5,16.8],[78,16.5],[79.5,16.5],[80.8,16],[81,15.8]]}},{"type":"Feature","properties":{"id":"kaveri","name":"Kaveri / Cauvery (rises in Talakaveri, Kodagu)"},"geometry":{"type":"LineString","coordinates":[[75.5,12.4],[76.5,12.5],[77.5,12],[78.5,11.5],[79.5,11.2],[79.8,11]]}},{"type":"Feature","properties":{"id":"tungabhadra","name":"Tungabhadra (Krishna tributary)"},"geometry":{"type":"LineString","coordinates":[[75.2,13.5],[75.8,14.5],[76.5,15.3],[77.5,16]]}}]},"defaultOn":true,"labelKey":"name","style":{"color":"#8a5a3a","weight":2.5,"flow":true}},{"id":"west-peninsular","name":"West-flowing Peninsular Rivers","description":"Only Narmada and Tapi flow west, through rift valleys, into the Arabian Sea. No deltas — estuaries.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"narmada","name":"Narmada (origin: Amarkantak) — flows in a rift valley"},"geometry":{"type":"LineString","coordinates":[[81.76,22.67],[80.5,22.5],[78.5,22.5],[76.5,22.3],[74.5,22],[73,21.8],[72.6,21.7]]}},{"type":"Feature","properties":{"id":"tapi","name":"Tapi / Tapti (origin: Multai, MP)"},"geometry":{"type":"LineString","coordinates":[[78.25,21.77],[77,21.5],[75,21.3],[73.5,21.2],[72.8,21.3]]}}]},"defaultOn":true,"labelKey":"name","style":{"color":"#c46a3d","weight":2.5,"dashArray":"6 4","flow":true}},{"id":"mizoram-rivers","name":"Mizoram Rivers","description":"Northward rivers join Barak → Brahmaputra. Southward rivers join Kolodyne → Bay of Bengal via Myanmar.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"tlawng","name":"Tlawng (Dhaleshwari) — longest river in Mizoram, ~185 km. Flows N to Barak."},"geometry":{"type":"LineString","coordinates":[[92.85,22.95],[92.7,23.4],[92.65,23.9],[92.7,24.3],[92.8,24.7]]}},{"type":"Feature","properties":{"id":"tuirial","name":"Tuirial (Sonai) — hydropower; flows N to Barak."},"geometry":{"type":"LineString","coordinates":[[92.95,23.3],[92.9,23.8],[92.85,24.2],[92.8,24.5]]}},{"type":"Feature","properties":{"id":"tuivawl","name":"Tuivawl — NE-flowing; tributary of Barak."},"geometry":{"type":"LineString","coordinates":[[93.1,23.5],[93,24],[92.95,24.3]]}},{"type":"Feature","properties":{"id":"chhimtuipui","name":"Chhimtuipui / Kolodyne / Kaladan — biggest river in Mizoram. Originates Myanmar, returns to Myanmar."},"geometry":{"type":"LineString","coordinates":[[93.5,23.3],[93.2,22.7],[92.9,22.4],[92.8,22.2],[93,22],[93.3,21.8]]}}]},"defaultOn":false,"labelKey":"name","style":{"color":"#5a7a3a","weight":2.5,"flow":true}},{"id":"origins","name":"Origins & Key Confluences","description":"Glacier sources, peninsular springs, and famous river confluences.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"mansarovar","name":"Mansarovar Lake — origin of Indus, Satluj, Brahmaputra (region)"},"geometry":{"type":"Point","coordinates":[81.45,30.65]}},{"type":"Feature","properties":{"id":"gangotri","name":"Gangotri Glacier — origin of Ganga (Bhagirathi)"},"geometry":{"type":"Point","coordinates":[78.9398,30.9947]}},{"type":"Feature","properties":{"id":"yamunotri","name":"Yamunotri Glacier — origin of Yamuna"},"geometry":{"type":"Point","coordinates":[78.4434,30.9939]}},{"type":"Feature","properties":{"id":"amarkantak","name":"Amarkantak — origin of Narmada and Son"},"geometry":{"type":"Point","coordinates":[81.7616,22.6707]}},{"type":"Feature","properties":{"id":"multai","name":"Multai (MP) — origin of Tapi"},"geometry":{"type":"Point","coordinates":[78.25,21.77]}},{"type":"Feature","properties":{"id":"mahabaleshwar","name":"Mahabaleshwar — origin of Krishna"},"geometry":{"type":"Point","coordinates":[73.65,17.92]}},{"type":"Feature","properties":{"id":"trimbak","name":"Trimbakeshwar — origin of Godavari"},"geometry":{"type":"Point","coordinates":[73.55,19.96]}},{"type":"Feature","properties":{"id":"talakaveri","name":"Talakaveri — origin of Kaveri"},"geometry":{"type":"Point","coordinates":[75.5,12.4]}},{"type":"Feature","properties":{"id":"sihawa","name":"Sihawa (Chhattisgarh) — origin of Mahanadi"},"geometry":{"type":"Point","coordinates":[81.3,20.1]}},{"type":"Feature","properties":{"id":"prayagraj","name":"Prayagraj — confluence of Ganga & Yamuna"},"geometry":{"type":"Point","coordinates":[81.8463,25.4358]}},{"type":"Feature","properties":{"id":"devprayag","name":"Devprayag — Bhagirathi + Alaknanda = Ganga"},"geometry":{"type":"Point","coordinates":[78.6,30.15]}}]},"defaultOn":true,"labelKey":"name"}],"facts":[{"id":"f1","text":"Indian rivers fall into two great families: Himalayan rivers (snow + glacier fed, perennial, long, with wide fertile floodplains) and Peninsular rivers (rain-fed, mostly seasonal, mature, stable courses cut into hard rock). India has 12 major river basins (catchment > 20,000 km²)."},{"id":"f2","text":"The Indus rises near Lake Mansarovar in Tibet, enters India in Ladakh, then flows into Pakistan to the Arabian Sea. Its five main tributaries — Jhelum, Chenab, Ravi, Beas, Satluj — give the Punjab (\"Land of Five Rivers\") its name.","linkedLayerId":"indus-system"},{"id":"f3","text":"The Indus Waters Treaty (1960), brokered by the World Bank, gives the three eastern rivers (Ravi, Beas, Satluj) to India and the three western rivers (Indus, Jhelum, Chenab) primarily to Pakistan. India retains limited rights on the western rivers (run-of-river hydropower, navigation).","linkedLayerId":"indus-system"},{"id":"f4","text":"The Ganga begins as the Bhagirathi from the Gangotri Glacier. At Devprayag (Uttarakhand) it joins the Alaknanda and becomes the Ganga. The Ganga basin is the most densely populated river basin on Earth, supporting over 500 million people.","linkedLayerId":"ganga-system","linkedFeatureId":"devprayag"},{"id":"f5","text":"The Yamuna originates from the Yamunotri Glacier, flows parallel to the Ganga, and joins it at Prayagraj (Allahabad) — the Sangam. Its right-bank tributaries (Chambal, Sind, Betwa, Ken) all rise in the Peninsular Plateau, making the Yamuna unusual: a Himalayan river fed largely by Peninsular tributaries.","linkedLayerId":"ganga-system","linkedFeatureId":"prayagraj"},{"id":"f6","text":"The Brahmaputra is known as the Tsangpo in Tibet, the Siang/Dihang where it enters India in Arunachal, and the Brahmaputra in Assam. It takes a sharp U-turn around Namcha Barwa to enter India. Largest tributary: Subansiri. The Brahmaputra causes annual flooding in Assam because its Tibetan catchment receives snowmelt and monsoon rain simultaneously.","linkedLayerId":"brahmaputra-system"},{"id":"f7","text":"The Barak River drains the Northeast hill states and is the second-largest river system of NE India. It joins the Meghna in Bangladesh, which in turn meets the Brahmaputra-Ganga delta. Almost all of Mizoram’s north-flowing rivers (Tlawng, Tuirial, Tuivawl) eventually reach the Brahmaputra system via the Barak.","linkedLayerId":"brahmaputra-system","linkedFeatureId":"barak"},{"id":"f8","text":"Mizoram’s longest river is the Tlawng (Dhaleshwari) — ~185 km, flows northward, joins the Barak in Assam. It was historically the main transport route used by the British when they arrived in 1890. The Tuirial is harnessed for hydropower.","linkedLayerId":"mizoram-rivers","linkedFeatureId":"tlawng"},{"id":"f9","text":"Mizoram’s biggest river is the Chhimtuipui (also Kolodyne or Kaladan). It originates in Chin state, Myanmar, enters Mizoram’s southern districts (Saiha, Lawngtlai), and returns to Myanmar where it reaches the Bay of Bengal at Sittwe. India’s Kaladan Multi-Modal Transit Transport Project uses this river to connect Mizoram to a deep-sea port in Myanmar.","linkedLayerId":"mizoram-rivers","linkedFeatureId":"chhimtuipui"},{"id":"f10","text":"The Peninsular rivers are older than the Himalayan rivers and have reached \"mature\" stage — broad valleys, low gradients, stable courses. They mostly flow east into the Bay of Bengal, where they form large deltas: Mahanadi, Godavari, Krishna, and Kaveri.","linkedLayerId":"east-peninsular"},{"id":"f11","text":"The Godavari is the longest river in Peninsular India (~1,465 km) — called \"Dakshin Ganga\" (Ganga of the South). It rises at Trimbakeshwar near Nashik and drains parts of Maharashtra, Telangana, Andhra Pradesh. Major tributaries: Pravara, Manjira, Indravati, Pranhita.","linkedLayerId":"east-peninsular","linkedFeatureId":"godavari"},{"id":"f12","text":"The Krishna rises at Mahabaleshwar in the Western Ghats and flows ~1,400 km through Maharashtra, Karnataka, Telangana, and Andhra Pradesh. Largest tributary: the Tungabhadra (which itself was the river around which Vijayanagara empire grew).","linkedLayerId":"east-peninsular","linkedFeatureId":"krishna"},{"id":"f13","text":"The Kaveri / Cauvery rises at Talakaveri in Kodagu (Karnataka), flows through Karnataka and Tamil Nadu, and forms a delta near Thanjavur. Inter-state water sharing between Karnataka and Tamil Nadu has been one of India’s longest-running river disputes.","linkedLayerId":"east-peninsular","linkedFeatureId":"kaveri"},{"id":"f14","text":"Only two major Peninsular rivers flow WEST: the Narmada and the Tapi. Both flow through rift valleys (grabens) between Vindhya-Satpura ranges and drain into the Arabian Sea via estuaries, not deltas. The Narmada rises at Amarkantak (MP); the Tapi at Multai (MP).","linkedLayerId":"west-peninsular"},{"id":"f15","text":"The Narmada traditionally divides North India from South India and runs through a rift valley between the Vindhya range (north) and the Satpura range (south). At ~1,312 km it is the largest west-flowing Peninsular river. Tapi flows almost parallel, just south of Satpura.","linkedLayerId":"west-peninsular","linkedFeatureId":"narmada"},{"id":"f16","text":"Why no west-flowing river deltas? The west-flowing Peninsular rivers fall into rift valleys with hard-rock margins and short distance to the sea — they don’t spread sediment laterally. The Narmada and Tapi form estuaries instead of deltas.","linkedLayerId":"west-peninsular"},{"id":"f17","text":"Inland drainage: a few rivers don’t reach the sea at all. The Luni in Rajasthan flows into the Rann of Kachchh. Streams from the Aravallis and the Sambhar Salt Lake area drain into inland basins. This is characteristic of the arid west."}],"quiz":[{"id":"q1","type":"mcq","question":"What is the fundamental difference between Himalayan and Peninsular rivers?","options":["Length — Himalayan rivers are always shorter","Source — Himalayan rivers are snow/glacier-fed and perennial; Peninsular rivers are rain-fed and mostly seasonal","Direction — Himalayan rivers flow only south; Peninsular rivers flow only east","Width — Peninsular rivers are wider than Himalayan rivers"],"answerIndex":1,"explanation":"Source determines everything else. Himalayan rivers (Indus, Ganga, Brahmaputra) are fed by snowmelt and glaciers so they flow year-round; Peninsular rivers (Godavari, Krishna, Kaveri, Narmada, Tapi, Mahanadi) depend on monsoon rainfall and shrink dramatically in dry seasons."},{"id":"q2","type":"map_click","question":"Click the location of Amarkantak — origin of the Narmada and the Son rivers.","answer":{"lat":22.67,"lng":81.76,"toleranceKm":120},"explanation":"Amarkantak (eastern Madhya Pradesh) is the rare twin-origin: the Narmada flows west from here to the Arabian Sea, while the Son flows east-then-north to join the Ganga."},{"id":"q3","type":"mcq","question":"Which two major peninsular rivers flow westward into the Arabian Sea?","options":["Krishna and Kaveri","Godavari and Mahanadi","Narmada and Tapi","Indus and Yamuna"],"answerIndex":2,"explanation":"Almost all Peninsular rivers flow east into the Bay of Bengal. The two exceptions are the Narmada and Tapi, which flow west through rift valleys between the Vindhyas and Satpuras into the Arabian Sea — and they form estuaries, not deltas."},{"id":"q4","type":"map_click","question":"Click the location of Prayagraj (the Sangam), where the Ganga meets the Yamuna.","answer":{"lat":25.4358,"lng":81.8463,"toleranceKm":100},"explanation":"Prayagraj (formerly Allahabad) sits at the confluence of the Ganga and Yamuna, sacred to Hindu tradition. The Saraswati is traditionally said to join here invisibly as the third river of the Triveni Sangam."},{"id":"q5","type":"mcq","question":"Under the Indus Waters Treaty (1960), which three rivers are primarily allocated to Pakistan?","options":["Ravi, Beas, Satluj","Indus, Jhelum, Chenab","Ganga, Yamuna, Sutlej","Brahmaputra, Teesta, Barak"],"answerIndex":1,"explanation":"The treaty gives India the three eastern rivers (Ravi, Beas, Satluj) and Pakistan the three western rivers (Indus, Jhelum, Chenab). India retains limited rights for run-of-river hydropower on the western rivers. The treaty has survived multiple wars and remains active."},{"id":"q6","type":"mcq","question":"What is the longest river in Mizoram?","options":["Chhimtuipui (Kolodyne)","Tuirial","Tlawng (Dhaleshwari)","Barak"],"answerIndex":2,"explanation":"The Tlawng (~185 km) is the longest river *within* Mizoram and flows north to join the Barak in Assam. The Chhimtuipui (Kolodyne) is the *biggest* river but originates in Myanmar and only passes through southern Mizoram before returning to Myanmar."},{"id":"q7","type":"map_click","question":"Click anywhere along the course of the Brahmaputra in Assam.","answer":{"lat":26.5,"lng":92.5,"toleranceKm":200},"explanation":"The Brahmaputra enters India through Arunachal Pradesh (as the Siang/Dihang) after taking a U-turn around Namcha Barwa, then flows west across Assam before turning south into Bangladesh. Its annual floods are a defining feature of Assamese geography."},{"id":"q8","type":"mcq","question":"Why do most Peninsular rivers form deltas on the eastern coast but not on the western coast?","options":["The western coast has no rivers reaching it","East-flowing rivers (Mahanadi, Godavari, Krishna, Kaveri) cross broad gentle plains and deposit sediment; west-flowing rivers (Narmada, Tapi) drop into rift valleys with short hard-rock margins to the sea, forming estuaries instead","The Bay of Bengal has stronger currents that build deltas","Eastern coastal rivers are shorter than western ones"],"answerIndex":1,"explanation":"Geology + gradient. East-flowing rivers traverse the wide Eastern Coastal Plain at low gradient, allowing sediment to fan out and build large deltas. West-flowing rivers run through fault-bounded rift valleys (the Narmada and Tapi grabens) and reach the Arabian Sea quickly through narrow estuaries."},{"id":"q9","type":"map_click","question":"Click the origin of the Godavari — longest river of Peninsular India.","answer":{"lat":19.96,"lng":73.55,"toleranceKm":100},"explanation":"The Godavari rises at Trimbakeshwar, near Nashik in the Western Ghats of Maharashtra. From there it flows southeast across the Deccan for ~1,465 km before meeting the Bay of Bengal in Andhra Pradesh — earning its nickname \"Dakshin Ganga\"."}]},"position":2,"hash":"2f325b1e5986aacff64998e7594fa9fa80b660f2ca986bc6ee74c32f76cadf23"},{"body":{"id":"climate-monsoon","subject":"geography","unit":"India Physical","tags":["monsoon","el-nino","himalayas","western-ghats","tropic-of-cancer","trade-winds"],"title":"Climate & Monsoon","summary":"India’s climate zones, the southwest and northeast monsoons, and the key cities shaped by them.","view":{"center":[22.5,80],"zoom":5},"basemap":"physical","focus":"India’s climate is the monsoon. Two seasonal winds reverse over the Indian Ocean, and that reversal shapes agriculture, settlement, and history.","layers":[{"id":"climate-zones","name":"Climate Zones (Köppen)","description":"Broad climate classification across India.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"tropical-wet","name":"Tropical Wet (Aw/Am)","color":"#2d6a4f"},"geometry":{"type":"Polygon","coordinates":[[[73,8.5],[77.5,8],[78,12.5],[76.5,15.5],[73.5,16.5],[72.8,13],[73,8.5]]]}},{"type":"Feature","properties":{"id":"tropical-dry","name":"Tropical Dry (BSh)","color":"#c46a3d"},"geometry":{"type":"Polygon","coordinates":[[[70.5,22],[76,22.5],[78,26],[75,28.5],[70,28],[68.5,25],[70.5,22]]]}},{"type":"Feature","properties":{"id":"humid-subtropical","name":"Humid Subtropical (Cwa)","color":"#52796f"},"geometry":{"type":"Polygon","coordinates":[[[78,25],[88,25.5],[90,27.5],[85,28.5],[78.5,28],[78,25]]]}},{"type":"Feature","properties":{"id":"mountain","name":"Mountain Climate (H)","color":"#6c757d"},"geometry":{"type":"Polygon","coordinates":[[[74,32],[80,30.5],[88,27.5],[95,28],[97,29.5],[89,30],[78,33.5],[74,32]]]}}]},"defaultOn":true,"labelKey":"name","style":{"color":"#3a7a7a","weight":1.5,"fillOpacity":0.45,"shadow":true}},{"id":"sw-monsoon","name":"Southwest Monsoon","description":"June–September. The main rain-bearing wind system.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"arabian-sea-branch","name":"Arabian Sea Branch","phase":"sw"},"geometry":{"type":"LineString","coordinates":[[68,5],[72,10],[73.5,15],[73,19],[72.5,23]]}},{"type":"Feature","properties":{"id":"bay-of-bengal-branch","name":"Bay of Bengal Branch","phase":"sw"},"geometry":{"type":"LineString","coordinates":[[90,6],[88,13],[88.5,20],[85,25],[80,27],[75,28.5]]}},{"type":"Feature","properties":{"id":"sw-deflected","name":"Deflected Branch (Ganga Plain)","phase":"sw"},"geometry":{"type":"LineString","coordinates":[[88.5,24],[83,25.5],[78,26.5],[74,27]]}}]},"defaultOn":true,"style":{"color":"#1d4f7a","weight":3.5}},{"id":"ne-monsoon","name":"Northeast Monsoon","description":"October–December. Brings rain mainly to Tamil Nadu.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"ne-monsoon-main","name":"Northeast Monsoon","phase":"ne"},"geometry":{"type":"LineString","coordinates":[[85,27],[82,22],[80,17],[80,12],[78,9]]}}]},"defaultOn":false,"style":{"color":"#c46a3d","weight":3.5,"dashArray":"6 4"}},{"id":"cities","name":"Reference Cities","description":"Spatial anchors for monsoon and climate.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"mumbai","name":"Mumbai"},"geometry":{"type":"Point","coordinates":[72.8777,19.076]}},{"type":"Feature","properties":{"id":"chennai","name":"Chennai"},"geometry":{"type":"Point","coordinates":[80.2707,13.0827]}},{"type":"Feature","properties":{"id":"kolkata","name":"Kolkata"},"geometry":{"type":"Point","coordinates":[88.3639,22.5726]}},{"type":"Feature","properties":{"id":"delhi","name":"Delhi"},"geometry":{"type":"Point","coordinates":[77.1025,28.7041]}},{"type":"Feature","properties":{"id":"jaisalmer","name":"Jaisalmer"},"geometry":{"type":"Point","coordinates":[70.9083,26.9157]}},{"type":"Feature","properties":{"id":"cherrapunji","name":"Cherrapunji"},"geometry":{"type":"Point","coordinates":[91.7195,25.2702]}},{"type":"Feature","properties":{"id":"thiruvananthapuram","name":"Thiruvananthapuram"},"geometry":{"type":"Point","coordinates":[76.9366,8.5241]}}]},"defaultOn":true,"labelKey":"name"}],"facts":[{"id":"f1","text":"India experiences a tropical monsoon climate, dominated by the seasonal reversal of winds over the Indian Ocean."},{"id":"f2","text":"The southwest monsoon (June–September) accounts for about 75% of India’s annual rainfall.","linkedLayerId":"sw-monsoon"},{"id":"f3","text":"The Arabian Sea branch strikes the Western Ghats first, producing heavy rain on the windward side and a rain-shadow on the leeward side (the Deccan Plateau).","linkedLayerId":"sw-monsoon"},{"id":"f4","text":"The Bay of Bengal branch advances along the Ganga plain and is deflected by the Himalayas, watering northern and eastern India.","linkedLayerId":"sw-monsoon"},{"id":"f5","text":"The northeast monsoon (October–December) brings most of Tamil Nadu’s rainfall, since the state lies in the rain-shadow of the Western Ghats during the southwest monsoon.","linkedLayerId":"ne-monsoon"},{"id":"f6","text":"Mawsynram and Cherrapunji in Meghalaya are among the wettest places on Earth, due to orographic lift from the Bay of Bengal branch hitting the Khasi Hills.","linkedFeatureId":"cherrapunji"},{"id":"f7","text":"Jaisalmer in the Thar Desert receives less than 200 mm of rainfall annually — a tropical dry climate.","linkedFeatureId":"jaisalmer"}],"quiz":[{"id":"q1","type":"map_click","question":"Click the location that receives some of the highest rainfall in the world.","answer":{"lat":25.27,"lng":91.72,"toleranceKm":150},"explanation":"Cherrapunji (and nearby Mawsynram) in Meghalaya — the Khasi Hills force the Bay of Bengal branch upward, producing extreme orographic rainfall."},{"id":"q2","type":"mcq","question":"Which branch of the southwest monsoon first strikes the Western Ghats?","options":["Bay of Bengal branch","Arabian Sea branch","Northeast monsoon","Western disturbance"],"answerIndex":1,"explanation":"The Arabian Sea branch hits the Western Ghats, producing heavy windward rainfall and a rain-shadow over the Deccan."},{"id":"q3","type":"map_click","question":"Click the city that receives most of its annual rainfall from the northeast monsoon.","answer":{"lat":13.08,"lng":80.27,"toleranceKm":120},"explanation":"Chennai — Tamil Nadu lies in the rain-shadow of the Western Ghats during the SW monsoon, so it depends on the retreating NE monsoon (Oct–Dec)."},{"id":"q4","type":"mcq","question":"What percentage of India’s annual rainfall is delivered by the southwest monsoon?","options":["About 25%","About 50%","About 75%","About 95%"],"answerIndex":2,"explanation":"Roughly 75% — the SW monsoon is the single most important climatic event of the Indian year."},{"id":"q5","type":"map_click","question":"Click an area with a Tropical Dry (BSh) climate.","answer":{"lat":27,"lng":71.5,"toleranceKm":250},"explanation":"The Thar Desert region in Rajasthan — hot, arid, less than 250 mm rainfall a year."}]},"position":3,"hash":"182cc8f90ededd8aa87055b200a518d16c214ab8ba7b8dbd49a2c325795998c2"},{"body":{"id":"soils-of-india","subject":"geography","unit":"India Physical","tags":["northern-plains","peninsular-plateau","deccan","thar","western-ghats"],"title":"Soils of India","summary":"The eight major soil types of India and the geology, climate, and crops they dictate.","focus":"Soil is parent rock plus climate plus time. India’s 8 ICAR soil types match almost perfectly onto geology and rainfall — and they decide what grows where.","view":{"center":[22.5,80],"zoom":5},"basemap":"physical","layers":[{"id":"alluvial","name":"Alluvial Soil (~43% of India)","description":"Largest soil type. River deposits in IGP + deltas. K-rich, N-poor. Rice, wheat, sugarcane.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"alluvial-igp","name":"Alluvial — Indo-Gangetic-Brahmaputra Plains"},"geometry":{"type":"Polygon","coordinates":[[[74,31.5],[78,30],[83,28.5],[87,27],[89,26.5],[92,26.5],[92,24.5],[88,24],[84,24.5],[78,25.5],[74.5,27.5],[74,31.5]]]}},{"type":"Feature","properties":{"id":"alluvial-east-delta","name":"Alluvial — Eastern Coastal Deltas"},"geometry":{"type":"Polygon","coordinates":[[[85.5,21],[87,20.5],[86.5,18],[83,16.5],[80.5,14],[79.5,11],[78.5,9.5],[79.8,11],[81,13],[83.5,16.5],[85.5,21]]]}}]},"defaultOn":true,"labelKey":"name","style":{"color":"#7a8a3a","fillColor":"#c5d086","fillOpacity":0.55,"weight":1.5}},{"id":"black","name":"Black (Regur) Soil","description":"From weathered Deccan basalt. Montmorillonite clay. Self-ploughing. Ideal for cotton.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"black-deccan","name":"Black Cotton Soil (Regur) — Deccan basalt zone"},"geometry":{"type":"Polygon","coordinates":[[[72.5,22.5],[76,22.5],[79.5,22],[82,20.5],[80,18],[77,16.5],[74,17],[73,19],[72.5,22.5]]]}}]},"defaultOn":true,"labelKey":"name","style":{"color":"#222","fillColor":"#3a3a3a","fillOpacity":0.55,"weight":1.5}},{"id":"red","name":"Red & Yellow Soil","description":"From crystalline igneous rock. Iron oxide gives the colour. Millets, groundnut, pulses.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"red-east","name":"Red & Yellow Soil — Eastern Peninsula"},"geometry":{"type":"Polygon","coordinates":[[[82,22],[86.5,23],[87,20.5],[85.5,17.5],[82.5,16],[80,17],[81,19.5],[82,22]]]}},{"type":"Feature","properties":{"id":"red-south","name":"Red Soil — Tamil Nadu, Karnataka, AP interior"},"geometry":{"type":"Polygon","coordinates":[[[76.5,15.5],[80,15],[80.5,12.5],[79.5,10],[77.5,9],[76.5,11],[76.5,15.5]]]}}]},"defaultOn":true,"labelKey":"name","style":{"color":"#8a3a3a","fillColor":"#c47a5a","fillOpacity":0.5,"weight":1.5}},{"id":"laterite","name":"Laterite Soil","description":"High temperature + heavy rain + leaching. Tea, coffee, cashew, rubber.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"laterite-wghats","name":"Laterite — Western Ghats summit/slopes"},"geometry":{"type":"Polygon","coordinates":[[[74,16],[75,15.5],[76.5,12],[77,8.5],[76,8.5],[75,11.5],[73.5,15.5],[74,16]]]}},{"type":"Feature","properties":{"id":"laterite-eghats","name":"Laterite — Eastern Ghats & Odisha"},"geometry":{"type":"Polygon","coordinates":[[[83.5,20.5],[85.5,20.5],[85.5,18.5],[83.5,18.5],[83.5,20.5]]]}},{"type":"Feature","properties":{"id":"laterite-ne","name":"Laterite — NE Hills (incl. Mizoram, Meghalaya)"},"geometry":{"type":"Polygon","coordinates":[[[91,26],[94,26],[94,22.5],[91.5,22.5],[91,26]]]}}]},"defaultOn":true,"labelKey":"name","style":{"color":"#c46a3d","fillColor":"#e8985a","fillOpacity":0.5,"weight":1.5,"pattern":"dots"}},{"id":"arid","name":"Arid / Desert Soil","description":"Sandy, saline, low organic content. Thar.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"arid-thar","name":"Arid / Desert Soil — Thar"},"geometry":{"type":"Polygon","coordinates":[[[69.5,24.5],[73.5,24],[75,26.5],[74.5,29],[72,29.5],[70,28.5],[69.5,24.5]]]}}]},"defaultOn":true,"labelKey":"name","style":{"color":"#c4a06a","fillColor":"#e8c590","fillOpacity":0.5,"weight":1.5}},{"id":"mountain","name":"Mountain / Forest Soil","description":"Shallow, immature. Himalayas + NE hills.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"mountain-himalaya","name":"Mountain / Forest Soil — Himalayas"},"geometry":{"type":"Polygon","coordinates":[[[74,33.5],[78,31.5],[82,31],[88,28.5],[93,28.5],[96,29],[95,30.5],[88,29.5],[82,31.5],[76,34],[74,33.5]]]}}]},"defaultOn":true,"labelKey":"name","style":{"color":"#5e4a8a","fillColor":"#9b8ac4","fillOpacity":0.4,"weight":1.5}},{"id":"peaty","name":"Peaty / Marshy Soil","description":"High organic matter. Kuttanad (Kerala, below sea level), Sundarbans.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"peaty-kuttanad","name":"Peaty / Marshy — Kuttanad (Kerala)"},"geometry":{"type":"Point","coordinates":[76.407,9.498]}},{"type":"Feature","properties":{"id":"peaty-sundarbans","name":"Peaty / Marshy — Sundarbans"},"geometry":{"type":"Point","coordinates":[88.9,21.95]}}]},"defaultOn":true,"labelKey":"name"},{"id":"saline","name":"Saline / Alkaline Soil","description":"Salt accumulation. Reh / Kallar / Usar. Rann of Kachchh + arid irrigated patches.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"saline-rann","name":"Saline / Alkaline — Rann of Kachchh"},"geometry":{"type":"Polygon","coordinates":[[[68.5,24.5],[71,24.5],[71.5,23.5],[68.5,23],[68.5,24.5]]]}},{"type":"Feature","properties":{"id":"saline-up","name":"Saline patches — Western UP / Punjab (Reh / Kallar)"},"geometry":{"type":"Point","coordinates":[77.5,28.5]}}]},"defaultOn":true,"labelKey":"name","style":{"color":"#7a8a8a","fillColor":"#c5d0d0","fillOpacity":0.5,"weight":1.5}}],"facts":[{"id":"f1","text":"The Indian Council of Agricultural Research (ICAR) classifies Indian soils into 8 major groups: Alluvial, Black, Red & Yellow, Laterite, Arid/Desert, Mountain/Forest, Peaty/Marshy, and Saline/Alkaline. Soil formation depends on CLORPT — Climate, Living organisms, Original parent material, Relief, and Time."},{"id":"f2","text":"Alluvial soil is India’s largest soil group, covering about 43% of the country. Found in the Indo-Gangetic-Brahmaputra Plains and along the eastern coastal deltas. Rich in potash (K) and lime, deficient in nitrogen (N) and humus.","linkedLayerId":"alluvial"},{"id":"f3","text":"Alluvial soils have two sub-types matching the Northern Plains belts: Khadar (newer alluvium, in flood plains, very fertile, replenished yearly) and Bhangar (older alluvium, terrace tops, contains \"kankar\" calcareous nodules, less fertile).","linkedLayerId":"alluvial"},{"id":"f4","text":"Black soil (locally Regur) formed from weathering of Deccan basalt lava flows. It contains montmorillonite clay, which makes it \"self-ploughing\" — it shrinks and cracks deeply when dry, then swells when wet, mixing itself. Highly water-retentive. Ideal for cotton.","linkedLayerId":"black"},{"id":"f5","text":"Black soil distribution: Maharashtra (the largest spread), Madhya Pradesh, Gujarat, northern Karnataka, parts of Andhra Pradesh and Tamil Nadu. Crops: cotton (its main association), soybean, jowar, oilseeds, pulses. Rich in lime, iron, magnesia; poor in nitrogen and phosphorus.","linkedLayerId":"black"},{"id":"f6","text":"Red & Yellow soils form from weathering of crystalline igneous rocks in low-rainfall regions. The colour comes from iron oxide (red when dehydrated, yellow when hydrated). Found in the eastern and southern Peninsular Plateau: Odisha, Chhattisgarh, Jharkhand, parts of AP, Karnataka, Tamil Nadu. Generally low fertility — needs fertiliser to be productive. Crops: millets, groundnut, potato, pulses.","linkedLayerId":"red"},{"id":"f7","text":"Laterite soil forms in regions with high temperature AND heavy seasonal rainfall — the alternation between wet and dry causes severe leaching of silica, leaving behind iron and aluminium oxides (gives the brick-red colour). Found on: Western Ghats summit, parts of Eastern Ghats and Odisha, Northeast hills (including Mizoram and Meghalaya).","linkedLayerId":"laterite"},{"id":"f8","text":"Laterite soils are typically acidic and low in nutrients but are valuable for plantation crops that don’t need fertile soil: tea, coffee, cashew, rubber. Karnataka and Kerala laterite zones are famous for coffee, cashew, and spice plantations.","linkedLayerId":"laterite"},{"id":"f9","text":"Arid (Desert) soils cover western Rajasthan and adjoining Gujarat. Sandy, low in organic matter, often saline. High phosphate content but very low nitrogen. With irrigation (Indira Gandhi Canal) parts have become productive for wheat, barley, and cotton.","linkedLayerId":"arid"},{"id":"f10","text":"Mountain (Forest) soils occupy the Himalayan slopes and the NE hills. They are shallow, immature, and stony — humus-rich on forest floors, less developed on bare slopes. Mizoram’s steep terrain bears mostly thin mountain/forest soils overlying laterite, supporting bamboo and evergreen forests but limiting settled agriculture.","linkedLayerId":"mountain"},{"id":"f11","text":"Peaty/Marshy soils form in waterlogged areas with high organic accumulation. India’s classic example is Kuttanad in Kerala — a region farmed mostly *below* sea level, where rice is grown on reclaimed wetland. The Sundarbans delta also has peaty soils mixed with saline mud.","linkedLayerId":"peaty"},{"id":"f12","text":"Saline/Alkaline soils (locally Reh, Kallar, or Usar) develop where salts accumulate at the surface — typically in arid regions with poor drainage, or in over-irrigated areas where rising groundwater brings salts up by capillary action. Found in the Rann of Kachchh and patches of western UP, Punjab, and Haryana.","linkedLayerId":"saline"},{"id":"f13","text":"Reclamation of saline soils: gypsum application (replaces Na⁺ with Ca²⁺), improved drainage, and leaching with fresh water. The Central Soil Salinity Research Institute at Karnal leads this work.","linkedLayerId":"saline"},{"id":"f14","text":"Mizoram-specific: the state’s steep terrain and heavy rainfall produce extensive lateritic and mountain/forest soils. Combined with jhum (shifting cultivation), erosion is a major concern. Terrace farming on contour lines is increasingly used to retain soil and water on the slopes."}],"quiz":[{"id":"q1","type":"mcq","question":"Which soil type is India’s most extensive, covering about 43% of the land area?","options":["Black (Regur)","Red & Yellow","Alluvial","Laterite"],"answerIndex":2,"explanation":"Alluvial soil covers the entire Indo-Gangetic-Brahmaputra Plains and the eastern coastal deltas — about 43% of India and the source of over 60% of food production."},{"id":"q2","type":"mcq","question":"Black cotton soil (Regur) gets its self-ploughing property from:","options":["A high sand content that prevents compaction","Montmorillonite clay that shrinks deeply on drying and swells on wetting","High organic matter from forest litter","Iron oxide that contracts in sunlight"],"answerIndex":1,"explanation":"Montmorillonite clay is the key. When dry, the soil cracks 1 m+ deep, and surface material falls in. When wet, the clay swells shut, mixing the soil. The soil tills itself."},{"id":"q3","type":"map_click","question":"Click anywhere in the main black cotton soil belt.","answer":{"lat":20,"lng":76,"toleranceKm":350},"explanation":"The black soil belt centres on Maharashtra (the largest spread) and extends into MP, Gujarat, and northern Karnataka — exactly the Deccan basalt zone. Its weathering produced the soil."},{"id":"q4","type":"mcq","question":"Laterite soil is best suited for which group of crops?","options":["Wheat and sugarcane","Cotton and soybean","Tea, coffee, cashew, and rubber","Rice and jute"],"answerIndex":2,"explanation":"Laterite is acidic, leached of nutrients, and not suited for grains. But it works very well for plantation crops that tolerate poor soil and need warm, wet conditions — tea, coffee, cashew, rubber."},{"id":"q5","type":"mcq","question":"Mizoram’s dominant soil types are best described as:","options":["Alluvial and saline","Black cotton soil","Lateritic and mountain/forest soils","Arid desert soil"],"answerIndex":2,"explanation":"Mizoram’s combination of steep hilly terrain and very heavy monsoon rainfall produces lateritic soil on weathered slopes and shallow mountain/forest soil over the hill ranges — acidic, low in nutrients, but supports rich evergreen forest cover."},{"id":"q6","type":"mcq","question":"What is the most common technique used to reclaim saline/alkaline soils?","options":["Adding urea","Application of gypsum and improved drainage","Burning the topsoil","Heavy ploughing to expose subsoil"],"answerIndex":1,"explanation":"Gypsum (calcium sulphate) replaces the harmful sodium ions in the soil with calcium ions, which leach away. Combined with better drainage and leaching, it restores fertility. CSSRI Karnal leads this research."},{"id":"q7","type":"map_click","question":"Click the Kuttanad region — famous for peaty/marshy soil and rice farming below sea level.","answer":{"lat":9.5,"lng":76.41,"toleranceKm":100},"explanation":"Kuttanad lies in central Kerala, around the backwaters of Vembanad Lake. Much of it is below sea level. Rice is cultivated on reclaimed wetland — unique within India."},{"id":"q8","type":"mcq","question":"Which factor is NOT one of the five soil-forming factors (CLORPT)?","options":["Climate","Living organisms","Latitude","Parent material"],"answerIndex":2,"explanation":"CLORPT = Climate, Living organisms, Original parent material, Relief, and Time. Latitude affects climate, but it isn’t one of the five factors directly. Topography/relief is."}]},"position":4,"hash":"8a56e1b4f87adb0000a291a11bc5b80e868b49a0e9b12433906ad7f1b1abdb8b"},{"body":{"id":"forests-protected-areas","subject":"geography","unit":"India Physical","tags":["western-ghats","himalayas","purvanchal","islands","biodiversity"],"title":"Forests & Protected Areas","summary":"India’s forest cover, biodiversity hotspots, national parks, tiger reserves, and biosphere reserves.","focus":"India protects nature in concentric layers — sanctuaries for species, parks for landscapes, tiger reserves for whole food chains, biosphere reserves for ecosystems including humans. The northeast (especially Mizoram) carries the highest forest cover by percentage.","view":{"center":[22.5,80],"zoom":5},"basemap":"physical","layers":[{"id":"hotspots","name":"Biodiversity Hotspots in India","description":"India has 4 of the world’s 36 biodiversity hotspots: Western Ghats, Eastern Himalayas, Indo-Burma, Sundaland (Nicobar).","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"wghats","name":"Western Ghats – Sri Lanka Hotspot"},"geometry":{"type":"Polygon","coordinates":[[[73,21],[74.5,20],[76.5,12.5],[77,8.5],[76,8.5],[75.5,11],[73.5,15.5],[72.5,19],[73,21]]]}},{"type":"Feature","properties":{"id":"ehimalaya","name":"Eastern Himalayas Hotspot"},"geometry":{"type":"Polygon","coordinates":[[[88,26],[92.5,26.5],[97,28.5],[97,29.5],[92,29],[88.5,28],[88,26]]]}},{"type":"Feature","properties":{"id":"indoburma","name":"Indo-Burma Hotspot — includes Mizoram"},"geometry":{"type":"Polygon","coordinates":[[[91.5,26],[97,26],[97,21.5],[92,21.5],[91.5,26]]]}},{"type":"Feature","properties":{"id":"sundaland","name":"Sundaland Hotspot — Nicobar Islands"},"geometry":{"type":"Polygon","coordinates":[[[92.5,9],[94,9],[94,6.5],[92.5,6.5],[92.5,9]]]}}]},"defaultOn":true,"labelKey":"name","style":{"color":"#2d6a4f","fillColor":"#5fa580","fillOpacity":0.4,"weight":1.5,"pattern":"dots"}},{"id":"biosphere-reserves","name":"Biosphere Reserves (12 UNESCO MAB)","description":"India has 18 biosphere reserves; 12 are part of UNESCO’s Man and Biosphere network.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"nilgiri","name":"Nilgiri Biosphere Reserve (1986, India’s first; UNESCO MAB)"},"geometry":{"type":"Point","coordinates":[76.67,11.4]}},{"type":"Feature","properties":{"id":"nanda-devi-br","name":"Nanda Devi BR (UNESCO MAB)"},"geometry":{"type":"Point","coordinates":[79.9707,30.376]}},{"type":"Feature","properties":{"id":"sundarbans","name":"Sundarbans BR (UNESCO MAB; world’s largest mangrove)"},"geometry":{"type":"Point","coordinates":[88.9,21.95]}},{"type":"Feature","properties":{"id":"gulf-mannar","name":"Gulf of Mannar BR (UNESCO MAB)"},"geometry":{"type":"Point","coordinates":[79,9]}},{"type":"Feature","properties":{"id":"manas","name":"Manas BR (UNESCO MAB; Assam)"},"geometry":{"type":"Point","coordinates":[90.9,26.7]}},{"type":"Feature","properties":{"id":"nokrek","name":"Nokrek BR (UNESCO MAB; Meghalaya)"},"geometry":{"type":"Point","coordinates":[90.3,25.45]}},{"type":"Feature","properties":{"id":"simlipal","name":"Simlipal BR (UNESCO MAB; Odisha)"},"geometry":{"type":"Point","coordinates":[86.3,21.75]}},{"type":"Feature","properties":{"id":"khangchendzonga","name":"Khangchendzonga BR (UNESCO MAB; Sikkim)"},"geometry":{"type":"Point","coordinates":[88.1475,27.7025]}},{"type":"Feature","properties":{"id":"pachmarhi","name":"Pachmarhi BR (UNESCO MAB; MP)"},"geometry":{"type":"Point","coordinates":[78.43,22.47]}},{"type":"Feature","properties":{"id":"achanakmar","name":"Achanakmar-Amarkantak BR (UNESCO MAB; Chhattisgarh–MP)"},"geometry":{"type":"Point","coordinates":[81.78,22.45]}},{"type":"Feature","properties":{"id":"agasthyamalai","name":"Agasthyamalai BR (UNESCO MAB; Kerala–Tamil Nadu)"},"geometry":{"type":"Point","coordinates":[77.25,8.6]}},{"type":"Feature","properties":{"id":"great-nicobar","name":"Great Nicobar BR (UNESCO MAB)"},"geometry":{"type":"Point","coordinates":[93.8,7]}}]},"defaultOn":true,"labelKey":"name"},{"id":"national-parks","name":"Key National Parks","description":"India has ~106 national parks. These are the most exam-relevant ones (incl. Mizoram’s Phawngpui and Murlen).","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"jim-corbett","name":"Jim Corbett NP (1936) — India’s oldest; first tiger reserve"},"geometry":{"type":"Point","coordinates":[78.7747,29.53]}},{"type":"Feature","properties":{"id":"kaziranga","name":"Kaziranga NP (UNESCO WHS) — 70% of world’s one-horned rhinos"},"geometry":{"type":"Point","coordinates":[93.17,26.5775]}},{"type":"Feature","properties":{"id":"gir","name":"Gir NP (Gujarat) — last home of Asiatic lion"},"geometry":{"type":"Point","coordinates":[70.965,21.124]}},{"type":"Feature","properties":{"id":"ranthambore","name":"Ranthambore NP (Rajasthan) — famous tiger reserve"},"geometry":{"type":"Point","coordinates":[76.44,26.0173]}},{"type":"Feature","properties":{"id":"bandipur","name":"Bandipur NP (Karnataka) — Nilgiri complex"},"geometry":{"type":"Point","coordinates":[76.63,11.67]}},{"type":"Feature","properties":{"id":"kanha","name":"Kanha NP (MP) — inspiration for The Jungle Book"},"geometry":{"type":"Point","coordinates":[80.61,22.33]}},{"type":"Feature","properties":{"id":"sundarban-np","name":"Sundarban NP — swimming Bengal tigers"},"geometry":{"type":"Point","coordinates":[88.9,21.95]}},{"type":"Feature","properties":{"id":"periyar","name":"Periyar NP (Kerala) — elephant reserve"},"geometry":{"type":"Point","coordinates":[77.24,9.46]}},{"type":"Feature","properties":{"id":"silent-valley","name":"Silent Valley NP (Kerala) — saved from dam, 1980s"},"geometry":{"type":"Point","coordinates":[76.43,11.08]}},{"type":"Feature","properties":{"id":"phawngpui-np","name":"Phawngpui NP (Mizoram) — Blue Mountain"},"geometry":{"type":"Point","coordinates":[92.8333,22.6333]}},{"type":"Feature","properties":{"id":"murlen-np","name":"Murlen NP (Mizoram) — evergreen forest, near Champhai"},"geometry":{"type":"Point","coordinates":[93.27,23.63]}}]},"defaultOn":true,"labelKey":"name"},{"id":"tiger-reserves","name":"Tiger Reserves (58)","description":"As of 2025: 58 tiger reserves. India hosts ~3,682 wild tigers (2022) — ~70-75% of the world’s.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"dampa","name":"Dampa TR (Mizoram, declared 1994) — ~500 km² core"},"geometry":{"type":"Point","coordinates":[92.3667,23.567]}},{"type":"Feature","properties":{"id":"sundarbans-tr","name":"Sundarbans TR"},"geometry":{"type":"Point","coordinates":[88.9,21.95]}},{"type":"Feature","properties":{"id":"corbett-tr","name":"Corbett TR — highest tiger population"},"geometry":{"type":"Point","coordinates":[78.7747,29.53]}},{"type":"Feature","properties":{"id":"nagarjunsagar","name":"Nagarjunsagar-Srisailam TR (AP) — largest by area"},"geometry":{"type":"Point","coordinates":[78.95,16.42]}},{"type":"Feature","properties":{"id":"bandipur-tr","name":"Bandipur TR (Karnataka)"},"geometry":{"type":"Point","coordinates":[76.63,11.67]}},{"type":"Feature","properties":{"id":"kanha-tr","name":"Kanha TR (MP)"},"geometry":{"type":"Point","coordinates":[80.61,22.33]}},{"type":"Feature","properties":{"id":"bandhavgarh","name":"Bandhavgarh TR (MP)"},"geometry":{"type":"Point","coordinates":[80.98,23.7]}},{"type":"Feature","properties":{"id":"periyar-tr","name":"Periyar TR (Kerala)"},"geometry":{"type":"Point","coordinates":[77.24,9.46]}}]},"defaultOn":false,"labelKey":"name"},{"id":"high-forest-states","name":"States with >75% Forest Cover","description":"8 states/UTs have over 75% forest cover — all but Lakshadweep & A&N are NE states.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"mizoram-fc","name":"Mizoram — 85.34% (2nd highest in India)","pct":85.34},"geometry":{"type":"Point","coordinates":[92.7,23.5]}},{"type":"Feature","properties":{"id":"lakshadweep-fc","name":"Lakshadweep — 91.33% (highest)","pct":91.33},"geometry":{"type":"Point","coordinates":[72,10.5]}},{"type":"Feature","properties":{"id":"anIsland-fc","name":"A&N Islands — 81.62%","pct":81.62},"geometry":{"type":"Point","coordinates":[92.8,10]}},{"type":"Feature","properties":{"id":"arunachal-fc","name":"Arunachal Pradesh — ~79%","pct":79},"geometry":{"type":"Point","coordinates":[94.5,28]}},{"type":"Feature","properties":{"id":"meghalaya-fc","name":"Meghalaya — ~76%","pct":76},"geometry":{"type":"Point","coordinates":[91.4,25.6]}},{"type":"Feature","properties":{"id":"nagaland-fc","name":"Nagaland — ~74%","pct":74},"geometry":{"type":"Point","coordinates":[94.5,26]}}]},"defaultOn":true,"labelKey":"name"}],"facts":[{"id":"f1","text":"India’s total forest and tree cover is 25.17% of the geographical area (ISFR 2023). Forest cover alone is 21.76%; tree cover (small patches, agroforestry) is 3.41%. The National Forest Policy 1988 targets 33% — the country is still well below that."},{"id":"f2","text":"States with the highest forest cover by AREA: Madhya Pradesh (77,073 km²) leads, then Arunachal Pradesh (65,882 km²) and Chhattisgarh (55,812 km²). States with the highest forest cover by PERCENTAGE: Lakshadweep (91.33%), Mizoram (85.34%), Andaman & Nicobar (81.62%).","linkedLayerId":"high-forest-states"},{"id":"f3","text":"Eight states/UTs have over 75% forest cover: Lakshadweep, Mizoram, A&N Islands, Arunachal Pradesh, Nagaland, Meghalaya, Tripura, Manipur — mostly the northeast. The NE region as a whole has 67% forest cover, far above the national average.","linkedLayerId":"high-forest-states"},{"id":"f4","text":"Mizoram is in a special position. It has the maximum INCREASE in forest cover in ISFR 2023 (+242 km²) AND the 2nd highest cover by percentage. Combined with declining cover in neighbouring NE states, Mizoram is becoming the green anchor of the region.","linkedFeatureId":"mizoram-fc"},{"id":"f5","text":"Protected Areas in India come in four legal categories under the Wildlife Protection Act, 1972: National Parks (IUCN Cat II), Wildlife Sanctuaries (IUCN Cat IV), Conservation Reserves, and Community Reserves. Together they cover ~5.28% of India."},{"id":"f6","text":"India has approximately 106 National Parks (number varies slightly across sources and updates). Jim Corbett (Uttarakhand, established 1936) is the oldest. Madhya Pradesh has the most national parks. Hemis NP in Ladakh is the largest by area.","linkedLayerId":"national-parks"},{"id":"f7","text":"Project Tiger was launched on 1 April 1973 by PM Indira Gandhi after a 1972 census revealed only 1,800 tigers remained (from ~40,000 a century earlier). It started with 9 reserves; today there are 58 tiger reserves covering ~84,500 km².","linkedLayerId":"tiger-reserves"},{"id":"f8","text":"India’s 2022 tiger census counted 3,682 wild tigers — about 70-75% of the world’s wild tiger population. Madhya Pradesh and Maharashtra have 6 tiger reserves each (the most). Corbett Tiger Reserve has the highest tiger population and density.","linkedLayerId":"tiger-reserves"},{"id":"f9","text":"Mizoram’s Dampa Tiger Reserve (declared 1994) is in western Mizoram, bordering Bangladesh. Core area ~500 km². It is the largest wildlife sanctuary in Mizoram. Tiger numbers here are low — the reserve has struggled with shifting cultivation and a border fence that blocks tiger movement.","linkedFeatureId":"dampa"},{"id":"f10","text":"India has 18 Biosphere Reserves; 12 of them are part of UNESCO’s Man and Biosphere (MAB) network. Each has three concentric zones: Core (strictly protected), Buffer (research and tourism), and Transition (sustainable human use).","linkedLayerId":"biosphere-reserves"},{"id":"f11","text":"Nilgiri (Tamil Nadu – Karnataka – Kerala) was India’s FIRST biosphere reserve (1986). It hosts the largest tiger population in South Asia across Bandipur, Nagarhole, Mudumalai, and Wayanad.","linkedFeatureId":"nilgiri"},{"id":"f12","text":"India has FOUR of the world’s 36 biodiversity hotspots: (1) Western Ghats & Sri Lanka, (2) Eastern Himalayas, (3) Indo-Burma (which includes Mizoram and most of NE India), (4) Sundaland (the Nicobar Islands). Mizoram falls squarely in the Indo-Burma hotspot.","linkedLayerId":"hotspots"},{"id":"f13","text":"Famous one-off conservation facts often asked: Kaziranga (Assam, UNESCO WHS) hosts ~70% of the world’s one-horned rhinos. Gir (Gujarat) is the only remaining home of the Asiatic lion. Sundarbans has the only swimming tigers (salt-adapted). Kanha (MP) inspired Kipling’s Jungle Book. Silent Valley (Kerala) was saved from a dam in the 1980s.","linkedLayerId":"national-parks"},{"id":"f14","text":"Mizoram has 2 National Parks: Phawngpui (Blue Mountain) NP and Murlen NP. Phawngpui surrounds the highest peak in Mizoram. Murlen lies near Champhai in eastern Mizoram, with evergreen sub-tropical forest.","linkedLayerId":"national-parks"},{"id":"f15","text":"India’s mangrove cover is ~4,992 km² (0.15% of geographical area). The Sundarbans (West Bengal) is the world’s largest mangrove forest. Mangroves are critical against cyclones, coastal erosion, and carbon storage."}],"quiz":[{"id":"q1","type":"mcq","question":"According to ISFR 2023, which state has the highest forest cover by percentage of geographical area?","options":["Mizoram","Lakshadweep","Arunachal Pradesh","Madhya Pradesh"],"answerIndex":1,"explanation":"Lakshadweep tops at 91.33%, then Mizoram (85.34%), then A&N Islands (81.62%). MP has the highest by AREA but lower by percentage. Be careful — UPSC loves to test the area-vs-percentage distinction."},{"id":"q2","type":"mcq","question":"Which state reported the maximum INCREASE in forest cover in ISFR 2023?","options":["Gujarat","Mizoram","Odisha","Madhya Pradesh"],"answerIndex":1,"explanation":"Mizoram led with a +242 km² increase in forest cover, followed by Gujarat (+180) and Odisha (+152). MP actually saw the LARGEST DECREASE (−612 km²). Mizoram has become the green anchor of the NE."},{"id":"q3","type":"map_click","question":"Click the location of Dampa Tiger Reserve.","answer":{"lat":23.57,"lng":92.37,"toleranceKm":80},"explanation":"Dampa Tiger Reserve lies in western Mizoram, near the Bangladesh border. Declared in 1994 with a ~500 km² core, it is the largest wildlife sanctuary in Mizoram."},{"id":"q4","type":"mcq","question":"Project Tiger was launched in:","options":["1972","1973","1980","2006"],"answerIndex":1,"explanation":"1 April 1973, launched by PM Indira Gandhi after the 1972 Wildlife Protection Act and a census that found only 1,800 tigers left. By 2022, India had 3,682 wild tigers."},{"id":"q5","type":"mcq","question":"How many of the world’s 36 biodiversity hotspots are in India?","options":["2","3","4","5"],"answerIndex":2,"explanation":"India has 4 biodiversity hotspots: Western Ghats & Sri Lanka, Eastern Himalayas, Indo-Burma (includes Mizoram and most of NE India), and Sundaland (Nicobar Islands)."},{"id":"q6","type":"map_click","question":"Click the location of the Nilgiri Biosphere Reserve — India’s first.","answer":{"lat":11.4,"lng":76.67,"toleranceKm":150},"explanation":"Nilgiri BR (1986) spans Karnataka, Tamil Nadu, and Kerala. It contains Bandipur, Nagarhole, Mudumalai, and Wayanad — the largest tiger population in South Asia."},{"id":"q7","type":"mcq","question":"Which biodiversity hotspot does Mizoram lie in?","options":["Western Ghats","Eastern Himalayas","Indo-Burma","Sundaland"],"answerIndex":2,"explanation":"Mizoram is firmly in the Indo-Burma biodiversity hotspot — the largest of the four in India, covering most of NE India south of the Brahmaputra."},{"id":"q8","type":"mcq","question":"Which of the following is NOT a UNESCO World Heritage Site?","options":["Kaziranga","Sundarbans","Manas","Bandhavgarh"],"answerIndex":3,"explanation":"Bandhavgarh is a famous tiger reserve in MP but NOT a UNESCO WHS. Kaziranga, Sundarbans, and Manas are all UNESCO Natural WHS."}]},"position":5,"hash":"47d1d723e3bd4e00d3a5937553a669e8e632af2e2145e02c8b1fdebdbfb850e4"},{"body":{"id":"mizoram-geography","subject":"geography","unit":"Mizoram","tags":["tlawng","kaladan","karnaphuli","mizo-hills","purvanchal","tropic-of-cancer"],"title":"Geography of Mizoram","summary":"Ridges, three river families, lakes, geology & climate — GS-V Unit II.","focus":"Mizoram is 90%+ structural hills aligned north–south. That grain sorts every river into three families — north to the Barak (Tlawng), south to the Kaladan (Chhimtuipui), west to the Karnaphuli (Khawthlangtuipui).","view":{"center":[23.3,92.85],"zoom":8},"basemap":"opentopo","theme":{"accent":"#1e6e5c","mapBg":"#eaf4f0"},"layers":[{"id":"ranges","name":"Mountain ranges","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"phawngpui","name":"Phawngpui Range (Lawngtlai) — Blue Mountain, 2157 m, highest"},"geometry":{"type":"Point","coordinates":[93.03,22.63]}},{"type":"Feature","properties":{"id":"sialkal","name":"Sialkal Range — NE Mizoram, Manipur/Myanmar border"},"geometry":{"type":"Point","coordinates":[93.25,23.9]}},{"type":"Feature","properties":{"id":"chalfilh","name":"Chalfilh Range (Aizawl District)"},"geometry":{"type":"Point","coordinates":[92.9,23.85]}},{"type":"Feature","properties":{"id":"hmuifang","name":"Hmuifang Range (Aizawl District)"},"geometry":{"type":"Point","coordinates":[92.75,23.45]}},{"type":"Feature","properties":{"id":"reiek","name":"Reiek Range (Mamit District)"},"geometry":{"type":"Point","coordinates":[92.6,23.69]}}]},"style":{"color":"#6b4f2a","weight":2,"fillColor":"#8a683a","fillOpacity":0.9,"shadow":true},"defaultOn":true,"labelKey":"name"},{"id":"north-rivers","name":"North-flowing (→ Barak)","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"tlawng","name":"Tlawng — longest (185.5 km); Zopui Hill → north; Dhaleswari in Cachar"},"geometry":{"type":"LineString","coordinates":[[92.7,22.9],[92.65,23.2],[92.6,23.5],[92.55,23.8],[92.53,24.1],[92.5,24.35]]}},{"type":"Feature","properties":{"id":"tuirial","name":"Tuirial (~117 km) — Chawilung Hills → Barak; partially navigable"},"geometry":{"type":"LineString","coordinates":[[92.85,23.55],[92.83,23.9],[92.8,24.2],[92.78,24.45]]}},{"type":"Feature","properties":{"id":"tuivawl","name":"Tuivawl (~72 km) — from near Chhawrtui, northward"},"geometry":{"type":"LineString","coordinates":[[93,23.6],[92.98,23.9],[92.95,24.2]]}}]},"style":{"color":"#1f5fa8","weight":3,"flow":true},"defaultOn":true,"labelKey":"name"},{"id":"south-rivers","name":"South-flowing (→ Kaladan/Myanmar)","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"chhimtuipui","name":"Chhimtuipui (Kaladan) — largest by volume; Myanmar boundary"},"geometry":{"type":"LineString","coordinates":[[93.05,23],[93,22.7],[92.95,22.4],[92.9,22.15],[92.88,21.95]]}},{"type":"Feature","properties":{"id":"tiau","name":"Tiau (~159 km) — natural boundary with Myanmar (east)"},"geometry":{"type":"LineString","coordinates":[[93.35,23.9],[93.38,23.6],[93.4,23.3],[93.42,23]]}}]},"style":{"color":"#7a2ea0","weight":3,"flow":true},"defaultOn":true,"labelKey":"name"},{"id":"west-rivers","name":"West-flowing (→ Bangladesh)","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"khawthlangtuipui","name":"Khawthlangtuipui (Karnaphuli) — Saithah, Mamit → Bangladesh near Tlabung (~128 km)"},"geometry":{"type":"LineString","coordinates":[[92.5,23.5],[92.47,23.25],[92.44,23.05],[92.42,22.87]]}}]},"style":{"color":"#0e8a6a","weight":3,"flow":true},"defaultOn":true,"labelKey":"name"},{"id":"lakes-plains","name":"Lakes & plains","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"palak","name":"Palak Dil — large lake (south)"},"geometry":{"type":"Point","coordinates":[92.9,22.2]}},{"type":"Feature","properties":{"id":"tamdil","name":"Tamdil — large lake (near Saitual)"},"geometry":{"type":"Point","coordinates":[92.95,23.74]}},{"type":"Feature","properties":{"id":"rengdil","name":"Rengdil — large lake (north)"},"geometry":{"type":"Point","coordinates":[92.55,24.02]}},{"type":"Feature","properties":{"id":"champhai","name":"Champhai Plain — largest; wet-rice cultivation"},"geometry":{"type":"Point","coordinates":[93.33,23.47]}}]},"style":{"color":"#0d6efd","weight":2,"fillColor":"#3b8beb","fillOpacity":0.9,"shadow":true},"defaultOn":false,"labelKey":"name"}],"facts":[{"id":"f1","text":"Vitals: 21°56′–24°31′ N, 92°16′–93°26′ E; area 21,081 sq km (0.64% of India); the Tropic of Cancer crosses the state. Stretch: 277 km N–S, 121 km E–W. International borders: Myanmar 404 km, Bangladesh 318 km; national borders with Manipur, Assam, Tripura total 146.6 km."},{"id":"f2","text":"Terrain: 90.5% structural hills, 6.4% linear ridges, only 3.1% floodplains and valley fills. Altitude runs 400–2,157 m (average ~1,000 m); ridges are N–S aligned and WESTERN slopes are steeper than eastern. Forest cover: 85.34% (ISFR 2023) — among India’s highest.","linkedLayerId":"ranges"},{"id":"f3","text":"Ranges to name: Sialkal (NE, on the Manipur–Myanmar border), Chalfilh and Hmuifang (Aizawl district), Reiek (Mamit), and Phawngpui (Lawngtlai) — the Blue Mountain, 2,157 m, the state’s highest point.","linkedLayerId":"ranges","linkedFeatureId":"phawngpui"},{"id":"f4","text":"North-flowing family (→ Barak system): TLAWNG is the longest at 185.5 km — rises at Zopui Hill (Lunglei), splits the state into two nearly equal halves, and is called the Dhaleswari in Cachar (Assam). Tributaries include Tut and Teirei. Tuirial (~117 km, partially navigable) and Tuivawl (~72 km) also flow north.","linkedLayerId":"north-rivers"},{"id":"f5","text":"South-flowing family: CHHIMTUIPUI (Kaladan) is the largest river by water volume — it rises in western Myanmar near Sabawngte, flows ~138 km, and forms the international boundary with Myanmar. Dendritic pattern; tributaries Tuichang, Tuichawng, Mat, Mengpui. TIAU (~159 km) is the natural boundary with Myanmar in the east.","linkedLayerId":"south-rivers"},{"id":"f6","text":"West-flowing family: KHAWTHLANGTUIPUI (Karnaphuli) drains the southwest — rises at Saithah (Mamit), runs ~128 km, enters Bangladesh near Tlabung, and forms the natural boundary with Bangladesh. Tributaries: Kawrpui, Tuichawng, Phairuang, Kau, De. Strategic trade route to Chittagong.","linkedLayerId":"west-rivers"},{"id":"f7","text":"Lakes formed where hills and ridges act as embankments — large: Palak, Tamdil, Rengdil; smaller: Rungdil, Vachadil. Plains are only ~3% and inter-montane: Champhai (largest — wet rice), Serchhip plains, the Northern plains, and Chamdur (western Siaha).","linkedLayerId":"lakes-plains"},{"id":"f8","text":"Geology: longitudinal anticlines and synclines control drainage and slopes; BIS (2016) puts Mizoram in SEISMIC ZONE V; the Indo-Myanmar tectonic arc passes through Siaha district. Tertiary sandstones and shales; marine fossils near Lunglei. Stratigraphy (ascending): Barail → Surma (Bhuban + Bokabil — Bokabil holds petroleum) → Tipam (youngest, coarse sandstone)."},{"id":"f9","text":"Climate & vegetation: tropical to temperate-montane; 10–30 °C (avg 22 °C); ~2,394 mm rain a year, ~40% of it in July–August; three seasons, the rainy one running nearly six months (mid-May to late Oct). Forests: Tropical Wet-Evergreen (west), Tropical Semi-Evergreen (~50% of area, central belt), Mountain Sub-Tropical on the high eastern fringe. Minerals: sandstone widespread, limestone in patches, coal at Kolasib/Thinglian, petroleum confirmed at Bilkhawthlir, uranium potential in Middle Bhuban sandstones (~4 ppm)."}],"quiz":[{"id":"q1","type":"mcq","question":"Which is the LONGEST river of Mizoram, and what is it called in Assam’s Cachar district?","options":["Chhimtuipui — Kaladan","Tlawng — Dhaleswari","Tiau — Karnaphuli","Tuirial — Barak"],"answerIndex":1,"explanation":"Tlawng (185.5 km) rises at Zopui Hill, Lunglei, flows north dividing the state into two nearly equal parts, and becomes the Dhaleswari in Cachar. Chhimtuipui is the largest by VOLUME — a different superlative."},{"id":"q2","type":"map_click","question":"Click Phawngpui — the Blue Mountain, Mizoram’s highest point (2,157 m).","answer":{"lat":22.63,"lng":93.03,"toleranceKm":60},"explanation":"Phawngpui rises in Lawngtlai district in the southeast, near the Myanmar border — matching the state’s altitude ceiling of 2,157 m."},{"id":"q3","type":"mcq","question":"Match river → boundary: which pair is CORRECT?","options":["Tiau → Bangladesh; Khawthlangtuipui → Myanmar","Tiau & Chhimtuipui → Myanmar (east/southeast); Khawthlangtuipui → Bangladesh (west)","Tlawng → Myanmar; Tuirial → Bangladesh","Chhimtuipui → Tripura; Tiau → Assam"],"answerIndex":1,"explanation":"Tiau and Chhimtuipui form the natural boundaries with Myanmar in the east and southeast; western rivers, led by the Khawthlangtuipui (Karnaphuli), form parts of the Bangladesh boundary."},{"id":"q4","type":"mcq","question":"Under BIS (2016), Mizoram falls in seismic zone:","options":["Zone II","Zone III","Zone IV","Zone V"],"answerIndex":3,"explanation":"Zone V — the highest hazard. The Indo-Myanmar tectonic arc passes through Siaha district, giving frequent tectonic disturbance; the hills are Tertiary sandstone and shale, prone to landslides."},{"id":"q5","type":"map_click","question":"Click the Champhai plain — the largest plain, known for wet-rice cultivation.","answer":{"lat":23.47,"lng":93.33,"toleranceKm":60},"explanation":"Champhai sits against the Myanmar border in the east. Plains are just ~3% of Mizoram and inter-montane — Champhai, Serchhip, the Northern plains, and Chamdur."},{"id":"q6","type":"mcq","question":"Which stratigraphic group of Mizoram is the YOUNGEST, and which formation holds petroleum reserves?","options":["Barail youngest; Bhuban has petroleum","Surma youngest; Barail has petroleum","Tipam youngest; Bokabil (Surma group) has petroleum","Bhuban youngest; Tipam has petroleum"],"answerIndex":2,"explanation":"Ascending order: Barail → Surma → Tipam (youngest, coarse sandstone with pebbles). Within the Surma group, the Bokabil formation is known for petroleum/hydrocarbons — confirmed presence at Bilkhawthlir."},{"id":"q7","type":"mcq","question":"Mizoram’s three large lakes are:","options":["Palak, Tamdil, Rengdil","Rungdil, Vachadil, Tamdil","Palak, Loktak, Umiam","Tamdil, Rihdil, Rungdil"],"answerIndex":0,"explanation":"Palak, Tamdil and Rengdil are the large lakes; Rungdil and Vachadil are smaller. They formed where hills and ridges served as natural embankments. (Loktak is Manipur; Umiam is Meghalaya.)"},{"id":"q8","type":"map_click","question":"Click roughly where the Khawthlangtuipui (Karnaphuli) leaves Mizoram for Bangladesh — near Tlabung.","answer":{"lat":22.87,"lng":92.42,"toleranceKm":60},"explanation":"The Karnaphuli exits near Tlabung in the southwest after ~128 km from its source at Saithah (Mamit) — the state’s strategic water route toward Chittagong."},{"id":"q9","type":"mcq","question":"Which statement about Mizoram’s relief is TRUE?","options":["Eastern slopes are steeper than western slopes","Plains cover about 30% of the state","Western slopes are steeper; hills are N–S aligned; plains are only ~3%","The ridges run east–west like the Himalayas"],"answerIndex":2,"explanation":"90.5% structural hills in N–S grain, western slopes steeper than eastern, floodplains/valley fills a mere 3.1%. This ridge grain is exactly why the rivers sort into north/south/west families."}]},"position":6,"hash":"5dce683af23d307d0e65d0686f5a115c3356f284ce7c5ce76151acdaebe132c8"},{"body":{"id":"world-restless-earth","subject":"geography","unit":"World","tags":["himalayas","ring-of-fire","earthquakes","plate-boundaries","aravalli"],"title":"World: The Restless Earth","summary":"Ring of Fire, quake belts, fold vs block mountains, volcanism.","focus":"The Circum-Pacific “Ring of Fire” alone accounts for ~68% of all earthquakes — quakes, volcanoes and young fold mountains all cluster on the same convergent plate boundaries.","view":{"center":[15,60],"zoom":2},"worldExtent":true,"basemap":"physical","theme":{"accent":"#c2452d","mapBg":"#f3ede2"},"layers":[{"id":"ring-of-fire","name":"Pacific Ring of Fire","description":"~68% of all earthquakes; dense volcano chain.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"rof-west","name":"Ring of Fire — western arc (NZ → Japan → Aleutians)"},"geometry":{"type":"LineString","coordinates":[[178,-40],[175,-30],[170,-20],[160,-10],[150,-6],[140,-2],[128,2],[124,8],[122,14],[122,20],[124,26],[130,32],[140,36],[145,42],[152,48],[160,53],[170,55],[180,55]]}},{"type":"Feature","properties":{"id":"rof-east","name":"Ring of Fire — eastern arc (Alaska → Andes)"},"geometry":{"type":"LineString","coordinates":[[-180,55],[-170,54],[-160,56],[-150,60],[-140,59],[-130,52],[-125,45],[-122,38],[-115,28],[-105,18],[-95,12],[-85,8],[-80,2],[-78,-8],[-72,-20],[-70,-32],[-72,-44],[-74,-52]]}}]},"style":{"color":"#c2452d","weight":4,"flow":true,"glow":true},"defaultOn":true,"labelKey":"name"},{"id":"alpide-belt","name":"Alpine–Himalayan belt","description":"The second great quake belt — runs through India.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"alpide","name":"Alpine–Himalayan belt — Alps → Turkey → Iran → Himalaya → Indonesia"},"geometry":{"type":"LineString","coordinates":[[-8,37],[3,40],[10,45],[20,42],[30,39],[44,38],[52,35],[62,34],[72,35],[80,30],[88,28],[95,27],[98,20],[98,10],[102,2],[110,-6],[118,-8.5],[126,-8]]}}]},"style":{"color":"#b0632c","weight":3.5,"flow":true},"defaultOn":true,"labelKey":"name"},{"id":"mid-atlantic","name":"Mid-Atlantic Ridge","description":"Divergent boundary — fissure-type volcanism.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"mar","name":"Mid-Atlantic Ridge — divergent boundary (fissure volcanoes)"},"geometry":{"type":"LineString","coordinates":[[-18,64.5],[-25,55],[-30,45],[-38,35],[-44,25],[-46,15],[-44,5],[-30,-5],[-22,-15],[-18,-25],[-15,-35],[-14,-45]]}}]},"style":{"color":"#4a5fa5","weight":3,"dashArray":"2 8","flow":true},"defaultOn":false,"labelKey":"name"},{"id":"fold-mountains","name":"Fold mountains","description":"Himalaya, Alps, Rockies, Andes — convergent boundaries.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"himalaya-w","name":"Himalayas (Asia) — fold, convergent boundary"},"geometry":{"type":"Point","coordinates":[84,28.5]}},{"type":"Feature","properties":{"id":"alps-w","name":"Alps (Europe) — fold"},"geometry":{"type":"Point","coordinates":[10,46.5]}},{"type":"Feature","properties":{"id":"rockies-w","name":"Rockies (North America) — fold"},"geometry":{"type":"Point","coordinates":[-110,45]}},{"type":"Feature","properties":{"id":"andes-w","name":"Andes (South America) — fold, longest chain"},"geometry":{"type":"Point","coordinates":[-70,-25]}}]},"style":{"color":"#2e7d5b","weight":2,"fillColor":"#2e7d5b","markerRadius":8,"glow":true},"defaultOn":true,"labelKey":"name"},{"id":"block-mountains","name":"Block mountains (horsts)","description":"Sierra Nevada, Black Forest — tension + faulting.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"sierra-nevada","name":"Sierra Nevada (N. America) — block mountain / horst"},"geometry":{"type":"Point","coordinates":[-119,37.5]}},{"type":"Feature","properties":{"id":"black-forest","name":"Black Forest (Germany) — block mountain; Rhine rift = graben"},"geometry":{"type":"Point","coordinates":[8.2,48.2]}}]},"style":{"color":"#7a5aa8","weight":2,"fillColor":"#7a5aa8","markerRadius":8},"defaultOn":false,"labelKey":"name"}],"facts":[{"id":"f1","text":"Mountains cover ~27% of the world’s land surface, supply up to 80% of the planet’s fresh surface water, house ~12% of humanity (FAO) — and over 50% of people depend directly or indirectly on mountain resources."},{"id":"f2","text":"Three-way classification: FOLD mountains form at convergent plate boundaries (Himalayas, Alps, Rockies, Andes); BLOCK mountains form by tension and faulting — the uplifted block is a HORST, the dropped valley a GRABEN (Sierra Nevada, Black Forest); VOLCANIC mountains are “mountains of accumulation” built from erupted material.","linkedLayerId":"fold-mountains"},{"id":"f3","text":"Earthquake anatomy: energy releases at the FOCUS (hypocentre) inside the earth; the point on the surface directly above is the EPICENTRE. Most shallow quakes are sudden stress release along a fault rupture."},{"id":"f4","text":"Shadow zones — how we know the core: P-waves go missing between 103° and 142° from the epicentre; S-waves vanish beyond 103° entirely (they cannot cross the liquid outer core). Beyond 142° only P-waves reappear. The 103°–142° band is the shadow zone for BOTH wave types."},{"id":"f5","text":"The Circum-Pacific Belt — the “Pacific Ring of Fire” — accounts for about 68% of all earthquakes and hugs heavily populated coasts. It is a chain of subduction zones: converging plates dive, melt, and feed explosive volcanoes.","linkedLayerId":"ring-of-fire"},{"id":"f6","text":"Volcanism 101: magma from the upper mantle reaches the surface as LAVA plus ash, gases and rock fragments. Eruption style (explosive vs effusive) depends on magma composition, gas content and volcano structure. Divergent boundaries produce fissure-type volcanoes and mid-ocean ridges; convergent boundaries produce subduction-zone volcanoes.","linkedLayerId":"mid-atlantic"},{"id":"f7","text":"Tsunami logic: an undersea quake suddenly displaces the water column; waves race across open ocean and rear up in shallow coastal water. Depth of focus sets the warning delay — roughly 60–90 seconds between P-wave arrival and the destructive shaking."}],"quiz":[{"id":"q1","type":"mcq","question":"The Pacific Ring of Fire accounts for approximately what share of all earthquakes?","options":["25%","45%","68%","90%"],"answerIndex":2,"explanation":"About 68% — the Circum-Pacific Belt is the planet’s most important earthquake belt, and because it is a chain of subduction zones it also carries most active volcanoes."},{"id":"q2","type":"mcq","question":"In block-mountain country, the uplifted block and the dropped rift valley are called, respectively:","options":["Graben and horst","Horst and graben","Syncline and anticline","Butte and mesa"],"answerIndex":1,"explanation":"HORST = the raised block (the mountain, e.g. Black Forest, Sierra Nevada); GRABEN = the sunken rift between parallel faults. Tension + faulting, not folding."},{"id":"q3","type":"map_click","question":"Click the Andes — the fold-mountain wall of South America on the Ring of Fire.","answer":{"lat":-25,"lng":-70,"toleranceKm":900},"explanation":"The Andes run down South America’s Pacific edge — where the Nazca plate subducts under South America. Fold mountains, earthquakes and volcanoes stacked on one boundary."},{"id":"q4","type":"mcq","question":"The P-wave shadow zone appears as a band around the earth between:","options":["0° and 45° from the epicentre","45° and 90° from the epicentre","103° and 142° from the epicentre","142° and 180° from the epicentre"],"answerIndex":2,"explanation":"103°–142°. S-waves disappear beyond 103° altogether (liquid outer core blocks them); P-waves reappear beyond 142°. The overlap band is the shadow zone for both."},{"id":"q5","type":"map_click","question":"Click the Black Forest — the classic European block mountain.","answer":{"lat":48.2,"lng":8.2,"toleranceKm":500},"explanation":"The Black Forest in Germany is a horst; the Rhine rift valley beside it is the matching graben."},{"id":"q6","type":"mcq","question":"Fissure-type volcanoes and mid-ocean ridges form at which kind of plate boundary?","options":["Convergent","Divergent","Transform","Passive margin"],"answerIndex":1,"explanation":"Divergent boundaries — plates pull apart and magma wells up through fissures (e.g. the Mid-Atlantic Ridge). Convergent/subduction boundaries give the explosive Ring-of-Fire volcanoes instead."},{"id":"q7","type":"mcq","question":"The point INSIDE the earth where quake energy is released, and the surface point directly above it, are:","options":["Epicentre; focus","Focus (hypocentre); epicentre","Fault; scarp","Node; antinode"],"answerIndex":1,"explanation":"Focus/hypocentre = the release point at depth; epicentre = the surface point vertically above it, where shaking is usually strongest."}]},"position":7,"hash":"e569ffbdbe2c3e84ba8a181ad9a16abbb1f095eb3371182bcfaa41727f5aee2e"},{"body":{"id":"world-winds-currents","subject":"geography","unit":"World","tags":["el-nino","monsoon","trade-winds","ocean-currents","heat-budget"],"title":"World: Winds, Belts & Currents","summary":"Seven pressure belts → planetary winds → ocean gyres → El Niño.","focus":"One engine, three layers: pressure belts make the planetary winds, the winds drag the oceans into gyres (warm poleward, cold equatorward), and a hiccup in the Pacific limb of this engine is El Niño.","view":{"center":[10,20],"zoom":2},"worldExtent":true,"basemap":"relief","theme":{"accent":"#1f5fa8","mapBg":"#e8f0f4"},"layers":[{"id":"low-belts","name":"Low-pressure belts","description":"Doldrums + sub-polar lows — rising air, rain.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"eq-low","name":"Equatorial Low (Doldrums) — rising hot air, thunderstorms"},"geometry":{"type":"Polygon","coordinates":[[[-180,-5],[180,-5],[180,5],[-180,5],[-180,-5]]]}},{"type":"Feature","properties":{"id":"subpolar-low-n","name":"Sub-polar Low (45°N–Arctic Circle) — converging winds rise"},"geometry":{"type":"Polygon","coordinates":[[[-180,45],[180,45],[180,66.5],[-180,66.5],[-180,45]]]}},{"type":"Feature","properties":{"id":"subpolar-low-s","name":"Sub-polar Low (45°S–Antarctic Circle)"},"geometry":{"type":"Polygon","coordinates":[[[-180,-66.5],[180,-66.5],[180,-45],[-180,-45],[-180,-66.5]]]}}]},"style":{"color":"#c2452d","weight":1,"fillColor":"#e06a4e","fillOpacity":0.18,"pattern":"wave"},"defaultOn":true,"labelKey":"name"},{"id":"high-belts","name":"High-pressure belts","description":"Horse latitudes + polar highs — sinking air, deserts.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"subtrop-high-n","name":"Sub-tropical High / Horse Latitudes (≈30–35°N) — sinking air, world’s hot deserts"},"geometry":{"type":"Polygon","coordinates":[[[-180,27],[180,27],[180,36],[-180,36],[-180,27]]]}},{"type":"Feature","properties":{"id":"subtrop-high-s","name":"Sub-tropical High (≈30–35°S)"},"geometry":{"type":"Polygon","coordinates":[[[-180,-36],[180,-36],[180,-27],[-180,-27],[-180,-36]]]}},{"type":"Feature","properties":{"id":"polar-high-n","name":"North Polar High — cold dense sinking air"},"geometry":{"type":"Polygon","coordinates":[[[-180,80],[180,80],[180,90],[-180,90],[-180,80]]]}},{"type":"Feature","properties":{"id":"polar-high-s","name":"South Polar High"},"geometry":{"type":"Polygon","coordinates":[[[-180,-90],[180,-90],[180,-80],[-180,-80],[-180,-90]]]}}]},"style":{"color":"#1f5fa8","weight":1,"fillColor":"#4a7fc0","fillOpacity":0.16,"pattern":"dots"},"defaultOn":true,"labelKey":"name"},{"id":"winds","name":"Planetary winds","description":"Trades, westerlies, polar easterlies — watch the flow.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"ne-trade-1","name":"NE Trade Winds (30°N → equator)"},"geometry":{"type":"LineString","coordinates":[[-40,28],[-52,18],[-62,8]]}},{"type":"Feature","properties":{"id":"ne-trade-2","name":"NE Trade Winds"},"geometry":{"type":"LineString","coordinates":[[150,28],[138,18],[128,8]]}},{"type":"Feature","properties":{"id":"se-trade-1","name":"SE Trade Winds (30°S → equator)"},"geometry":{"type":"LineString","coordinates":[[-10,-28],[-22,-18],[-32,-8]]}},{"type":"Feature","properties":{"id":"se-trade-2","name":"SE Trade Winds"},"geometry":{"type":"LineString","coordinates":[[170,-28],[158,-18],[148,-8]]}},{"type":"Feature","properties":{"id":"westerlies-n","name":"Westerlies (SW → NE, 35–60°N)"},"geometry":{"type":"LineString","coordinates":[[-60,38],[-40,46],[-18,52]]}},{"type":"Feature","properties":{"id":"westerlies-s","name":"Roaring Forties — Westerlies (NW → SE, 35–60°S)"},"geometry":{"type":"LineString","coordinates":[[40,-38],[65,-46],[90,-52]]}},{"type":"Feature","properties":{"id":"polar-e-n","name":"Polar Easterlies (NE → SW)"},"geometry":{"type":"LineString","coordinates":[[20,78],[2,71],[-12,65]]}}]},"style":{"color":"#5b8a2e","weight":3,"flow":true},"defaultOn":true,"labelKey":"name"},{"id":"warm-currents","name":"Warm currents","description":"Equator → poles: Gulf Stream, Kuroshio, Brazil, Agulhas…","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"gulf-stream","name":"Gulf Stream → North Atlantic Drift (warm)"},"geometry":{"type":"LineString","coordinates":[[-80,25],[-74,33],[-60,40],[-40,48],[-20,54],[-5,58]]}},{"type":"Feature","properties":{"id":"kuroshio","name":"Kuroshio Current (warm, Japan)"},"geometry":{"type":"LineString","coordinates":[[124,20],[130,27],[138,33],[150,40]]}},{"type":"Feature","properties":{"id":"brazil","name":"Brazil Current (warm) — S. Equatorial current splits at Brazil’s shoulder"},"geometry":{"type":"LineString","coordinates":[[-34,-8],[-38,-16],[-42,-25],[-48,-33]]}},{"type":"Feature","properties":{"id":"agulhas","name":"Agulhas Current (warm, E. Africa)"},"geometry":{"type":"LineString","coordinates":[[42,-22],[36,-30],[28,-36]]}},{"type":"Feature","properties":{"id":"e-australia","name":"East Australian Current (warm)"},"geometry":{"type":"LineString","coordinates":[[155,-18],[154,-26],[151,-34]]}}]},"style":{"color":"#d1495b","weight":3.5,"flow":true,"glow":true},"defaultOn":false,"labelKey":"name"},{"id":"cold-currents","name":"Cold currents","description":"Poles → equator: Labrador, Canary, Benguela, Humboldt…","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"labrador","name":"Labrador Current (cold) — meets Gulf Stream: Newfoundland fogs & fisheries"},"geometry":{"type":"LineString","coordinates":[[-58,60],[-54,52],[-50,46]]}},{"type":"Feature","properties":{"id":"canary","name":"Canary Current (cold)"},"geometry":{"type":"LineString","coordinates":[[-12,40],[-16,32],[-18,24]]}},{"type":"Feature","properties":{"id":"benguela","name":"Benguela Current (cold, SW Africa)"},"geometry":{"type":"LineString","coordinates":[[16,-34],[12,-26],[10,-18]]}},{"type":"Feature","properties":{"id":"humboldt","name":"Peru / Humboldt Current (cold) — the El Niño stage"},"geometry":{"type":"LineString","coordinates":[[-74,-40],[-76,-28],[-80,-16],[-82,-6]]}},{"type":"Feature","properties":{"id":"oyashio","name":"Oyashio Current (cold, NW Pacific)"},"geometry":{"type":"LineString","coordinates":[[158,52],[150,46],[144,41]]}},{"type":"Feature","properties":{"id":"california","name":"California Current (cold)"},"geometry":{"type":"LineString","coordinates":[[-126,44],[-122,36],[-117,29]]}}]},"style":{"color":"#2d7dd2","weight":3.5,"flow":true,"glow":true},"defaultOn":false,"labelKey":"name"},{"id":"el-nino","name":"El Niño stage","description":"The equatorial Pacific see-saw.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"walker","name":"Normal year: trades push warm water WEST → rain over Indonesia/Australia; cold upwelling off Peru"},"geometry":{"type":"LineString","coordinates":[[-82,0],[-120,2],[-160,0],[150,-2],[128,0]]}},{"type":"Feature","properties":{"id":"peru-coast","name":"Peru–Ecuador coast — El Niño warming appears here (every 2–7 yrs)"},"geometry":{"type":"Point","coordinates":[-81,-5]}},{"type":"Feature","properties":{"id":"indo-pool","name":"Indonesia–N. Australia — normal-year warm pool & low pressure"},"geometry":{"type":"Point","coordinates":[128,-5]}}]},"style":{"color":"#b0632c","weight":2.5,"dashArray":"6 6","flow":true,"markerRadius":8},"defaultOn":false,"labelKey":"name"}],"facts":[{"id":"f1","text":"Air has weight — that weight is atmospheric pressure; isobars join points of equal pressure. Warm air expands, gets lighter and rises (low pressure); cold air compresses, densifies and sinks (high pressure). Wind is simply air moving from high to low."},{"id":"f2","text":"Seven belts, alternating: Equatorial Low (intense heating, rising air, daily thunderstorms — the calm “doldrums”); Sub-tropical Highs to ~35° (air sinking after the Hadley circuit — hot deserts and the “horse latitudes”); Sub-polar Lows (45°–polar circles, where sub-tropical and polar winds converge and rise); Polar Highs (cold dense sinking air).","linkedLayerId":"high-belts"},{"id":"f3","text":"Tri-cellular model: the HADLEY cell (largest, equator to ~30–40°) drives the trade winds; the FERREL cell (middle, moves opposite — “like a cog in a machine” between the other two) gives the westerlies; the POLAR cell (smallest, weakest) gives the polar easterlies."},{"id":"f4","text":"Coriolis: because Earth’s surface spins fastest at the equator, moving air and water deflect RIGHT in the northern hemisphere and LEFT in the southern. That is why the trades arrive as NE trades (north) and SE trades (south), and why ocean gyres spin clockwise in the north and anticlockwise in the south.","linkedLayerId":"winds"},{"id":"f5","text":"Trade winds are descending and stable at their origin (sub-tropical highs); where the two hemispheres’ trades meet at the equator, the air rises into storms. Their eastern flanks ride over cool ocean and stay dry — which is why deserts hug the western coasts of continents in the trade-wind belt.","linkedLayerId":"winds"},{"id":"f6","text":"Currents come in two families: WARM (originate near the equator, flow poleward, high surface temperature) and COLD (originate polewards, flow toward the equator). Drivers: planetary winds (the biggest), Coriolis, temperature (an ~8 cm sea-surface gradient from equator to mid-latitudes!), salinity (denser saline water sinks), and coastline shape.","linkedLayerId":"warm-currents"},{"id":"f7","text":"Name-drop set for prelims — warm: Gulf Stream→North Atlantic Drift, Kuroshio, Brazil (the South Equatorial current splits in two on Brazil’s shoulder), Agulhas, East Australian. Cold: Labrador, Canary, Benguela, Peru/Humboldt, Oyashio, California. Where Labrador meets the Gulf Stream: fog + the great Newfoundland fishing grounds.","linkedLayerId":"cold-currents"},{"id":"f8","text":"Normal Pacific year: high pressure sits off Peru, low over Indonesia/N. Australia — strong easterly trades push warm water west (rain in Indonesia), while cold nutrient-rich water UPWELLS off Peru (rich fisheries).","linkedLayerId":"el-nino"},{"id":"f9","text":"EL NIÑO year (irregular, every 2–7 years, avg ~3–4): pressure drops over the central Pacific and South America’s coast, trades weaken, the Peru current runs warm, upwelling collapses — rain shifts to the Peruvian coast while Indonesia/Australia (and often the Indian monsoon) dry out. LA NIÑA is the cold overcorrection of the same see-saw.","linkedLayerId":"el-nino"}],"quiz":[{"id":"q1","type":"mcq","question":"Arrange the pressure belts from equator to pole:","options":["Equatorial Low → Sub-polar Low → Sub-tropical High → Polar High","Equatorial Low → Sub-tropical High → Sub-polar Low → Polar High","Sub-tropical High → Equatorial Low → Polar High → Sub-polar Low","Equatorial High → Sub-tropical Low → Sub-polar High → Polar Low"],"answerIndex":1,"explanation":"Low–High–Low–High, alternating: Equatorial Low (0–5°) → Sub-tropical High (≈30–35°) → Sub-polar Low (45°–polar circle) → Polar High. The wind systems blow between them."},{"id":"q2","type":"mcq","question":"Which cell of the tri-cellular model is the largest, and which winds does it drive?","options":["Ferrel cell — westerlies","Polar cell — polar easterlies","Hadley cell — the trade winds","Walker cell — monsoons"],"answerIndex":2,"explanation":"The Hadley cell (equator to ~30–40°) is the largest and powers the trades. Ferrel is the middle “cog” (westerlies); Polar is the smallest and weakest (easterlies)."},{"id":"q3","type":"mcq","question":"Coriolis deflection sends moving air and currents:","options":["Left in the northern hemisphere, right in the southern","Right in the northern hemisphere, left in the southern","Always toward the equator","Always toward the poles"],"answerIndex":1,"explanation":"Right in the north, left in the south — because the surface rotates faster at the equator. Hence NE/SE trades, and gyres clockwise (N) / anticlockwise (S)."},{"id":"q4","type":"map_click","question":"Click the Peru (Humboldt) cold current — the stage on which El Niño plays out.","answer":{"lat":-15,"lng":-79,"toleranceKm":1200},"explanation":"The cold Humboldt current runs up South America’s west coast. Its upwelling feeds the anchovy fisheries — exactly what an El Niño year shuts down."},{"id":"q5","type":"mcq","question":"In a NORMAL (non-El Niño) year over the Pacific:","options":["Low pressure off Peru; warm water piles up off Ecuador","High pressure off Peru, low over Indonesia; trades push warm water west and cold water upwells off Peru","The trade winds reverse and blow west to east","Upwelling occurs off Australia"],"answerIndex":1,"explanation":"Normal year = Peru high + Indonesian low → strong easterly trades → warm pool and thunderstorms in the west, cold nutrient-rich upwelling off Peru. El Niño weakens or reverses this."},{"id":"q6","type":"map_click","question":"Click where the warm Gulf Stream and the cold Labrador current meet — fog and fisheries off Newfoundland.","answer":{"lat":46,"lng":-50,"toleranceKm":1100},"explanation":"Off Newfoundland the Labrador current collides with the Gulf Stream: dense fogs, and one of the world’s richest fishing grounds where cold and warm waters mix."},{"id":"q7","type":"mcq","question":"El Niño events recur roughly every:","options":["Every year","2 to 7 years (avg ~3–4)","Exactly every 11 years","Once a century"],"answerIndex":1,"explanation":"Irregular, every 2–7 years, averaging once every 3–4 years. When it comes, upwelling off Peru collapses and global rainfall patterns — including the Indian monsoon — shift."},{"id":"q8","type":"mcq","question":"Warm currents generally flow ______ and circulate ______ in the northern hemisphere.","options":["Poleward; clockwise","Equatorward; clockwise","Poleward; anticlockwise","Equatorward; anticlockwise"],"answerIndex":0,"explanation":"Warm currents originate near the equator and carry heat poleward; northern-hemisphere gyres turn clockwise (Coriolis right-deflection), southern ones anticlockwise."}]},"position":8,"hash":"851245f2bc7e5c5322bc2cdb5eab93a89b067fa99ac9962fcaba389a6f7ed135"},{"body":{"id":"world-resources-industries","subject":"geography","unit":"World","tags":["chotanagpur","coal","iron-ore","peninsular-plateau","ruhr","jharkhand","deccan"],"title":"World: Resources & Industry","summary":"Why industry sits where it does — iron, coal, copper, oil belts mapped.","focus":"Industry sits where its inputs are cheapest to assemble — so every great industrial region is parked on a coalfield, an ore belt, or a port. Map the minerals first and the factory regions locate themselves.","view":{"center":[22,40],"zoom":2},"worldExtent":true,"basemap":"relief","theme":{"accent":"#8a5a2b","mapBg":"#f2ede4"},"layers":[{"id":"industrial-regions","name":"Industrial regions","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"ruhr","name":"Ruhr (Germany) — Europe’s classic coal–steel region"},"geometry":{"type":"Point","coordinates":[7.2,51.5]}},{"type":"Feature","properties":{"id":"great-lakes","name":"Great Lakes (N. America) — iron (Mesabi) + coal (Appalachia) meet on cheap water transport"},"geometry":{"type":"Point","coordinates":[-83,42.5]}},{"type":"Feature","properties":{"id":"manchuria","name":"Manchuria (NE China) — largest coal industry of China; Anshan iron & steel"},"geometry":{"type":"Point","coordinates":[123.4,41.8]}},{"type":"Feature","properties":{"id":"kyushu","name":"Northern Kyushu (Japan) — coal, iron & steel"},"geometry":{"type":"Point","coordinates":[130.7,33.7]}},{"type":"Feature","properties":{"id":"chotanagpur","name":"Chotanagpur plateau (India) — steel, cement, paper; Jamshedpur, Hazaribagh"},"geometry":{"type":"Point","coordinates":[85.8,23.4]}},{"type":"Feature","properties":{"id":"delhi-ncr","name":"Delhi NCR — textiles, pharma, consumer goods (Faridabad, Ghaziabad, Noida, Gurgaon)"},"geometry":{"type":"Point","coordinates":[77.2,28.6]}}]},"style":{"color":"#8a5a2b","weight":2,"fillColor":"#8a5a2b","markerRadius":8,"glow":true},"defaultOn":true,"labelKey":"name"},{"id":"iron-belts","name":"Iron-ore belts","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"carajas","name":"Carajas–Itabira–Minas Gerais (Brazil)"},"geometry":{"type":"Point","coordinates":[-49.9,-6.1]}},{"type":"Feature","properties":{"id":"ural-iron","name":"Ural / Magnitogorsk (Russia–Kazakhstan)"},"geometry":{"type":"Point","coordinates":[59,53.4]}},{"type":"Feature","properties":{"id":"mesabi","name":"Great Lakes–Labrador (N. America)"},"geometry":{"type":"Point","coordinates":[-92.5,47.5]}},{"type":"Feature","properties":{"id":"pilbara","name":"Australia — Koolyanobbing, Iron Knob, Iron Duke"},"geometry":{"type":"Point","coordinates":[119.5,-30.9]}},{"type":"Feature","properties":{"id":"odisha-iron","name":"India — Odisha–Jharkhand belt: Sundergarh, Mayurbhanj; Noamundi & Gua (Singhbhum)"},"geometry":{"type":"Point","coordinates":[85.5,22.3]}},{"type":"Feature","properties":{"id":"bailadila","name":"India — Chhattisgarh: Durg, Dantewada, Bailadila"},"geometry":{"type":"Point","coordinates":[81.2,18.7]}},{"type":"Feature","properties":{"id":"ballari","name":"India — Karnataka: Sandur–Hospet (Ballari), Kudremukh, Baba Budan hills"},"geometry":{"type":"Point","coordinates":[76.5,15.1]}}]},"style":{"color":"#b3261e","weight":2,"fillColor":"#b3261e","markerRadius":6},"defaultOn":true,"labelKey":"name"},{"id":"coal-fields","name":"Coalfields","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"silesia","name":"Europe — Ruhr, Upper Silesia, Durham/Cumberland"},"geometry":{"type":"Point","coordinates":[19,50.3]}},{"type":"Feature","properties":{"id":"appalachia","name":"USA — Appalachian fields (Kentucky, Illinois, Indiana…)"},"geometry":{"type":"Point","coordinates":[-83.5,37.8]}},{"type":"Feature","properties":{"id":"shansi","name":"China — Shansi, Sichuan, Fushun, Shenyang"},"geometry":{"type":"Point","coordinates":[112.5,37.8]}},{"type":"Feature","properties":{"id":"kuznetsk","name":"Russia — Moscow, Ob & Lena basins, E. Siberia"},"geometry":{"type":"Point","coordinates":[87.1,55.3]}},{"type":"Feature","properties":{"id":"damodar","name":"India — Jharia, Bokaro, Raniganj (Damodar valley); Korba, Singrauli, Talcher, Neyveli, Singareni"},"geometry":{"type":"Point","coordinates":[86.4,23.7]}},{"type":"Feature","properties":{"id":"nsw","name":"Australia — Newcastle, Brisbane, Ipswich"},"geometry":{"type":"Point","coordinates":[151.7,-32.9]}}]},"style":{"color":"#3d3833","weight":2,"fillColor":"#3d3833","markerRadius":6},"defaultOn":false,"labelKey":"name"},{"id":"other-minerals","name":"Copper & petroleum","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"chile-cu","name":"COPPER — Chile (27% of world output): Escondida, Collahuasi; Peru next (10%)"},"geometry":{"type":"Point","coordinates":[-69.1,-24.3]}},{"type":"Feature","properties":{"id":"india-cu","name":"COPPER (India) — Singhbhum (JH), Balaghat (MP), Jhunjhunu–Alwar (RJ)"},"geometry":{"type":"Point","coordinates":[75.4,27.9]}},{"type":"Feature","properties":{"id":"gulf-oil","name":"PETROLEUM — the Persian Gulf: the world’s densest reserves"},"geometry":{"type":"Point","coordinates":[50.5,27.5]}},{"type":"Feature","properties":{"id":"india-oil","name":"PETROLEUM (India) — Mumbai High, Assam (Digboi), Gujarat (Ankleshwar)"},"geometry":{"type":"Point","coordinates":[71.3,19.3]}}]},"style":{"color":"#1f5fa8","weight":2,"fillColor":"#1f5fa8","markerRadius":6},"defaultOn":false,"labelKey":"name"}],"facts":[{"id":"f1","text":"Location factors, geographical: raw materials (steel near ore), power (coal/hydro/oil), transport (roads, rail, PORTS), labour (skilled or cheap — textiles chase workforces), water (iron & steel, textiles, chemicals are thirsty), flat land and moderate climate, market proximity (consumer goods)."},{"id":"f2","text":"Non-geographical factors: capital and loans, investment climate, government policy (subsidised power, tax breaks, siting rules against pollution and over-clustering), pressure groups — and INDUSTRIAL INERTIA: the tendency of industry to stay put even after its original locational advantage is gone."},{"id":"f3","text":"Sector logic: PRIMARY industries (mining, forestry, agriculture) sit on the resource itself; SECONDARY (manufacturing) minimises assembly cost of materials + energy + labour; TERTIARY (services) follows market demand and population density. Industrialisation then grows the towns around it."},{"id":"f4","text":"Classic industrial regions: RUHR (Germany) — the coal–steel template; GREAT LAKES (N. America) — Mesabi iron meets Appalachian coal on cheap lake transport; MANCHURIA — China’s biggest coal industry, Anshan steel; NORTHERN KYUSHU — Japan’s coal–steel cradle; in India, the CHOTANAGPUR plateau (steel–cement–paper: Jamshedpur, Hazaribagh) and the market-driven DELHI NCR belt (textiles, leather, pharma, consumer goods).","linkedLayerId":"industrial-regions"},{"id":"f5","text":"IRON ORE (world reserves ~3,20,000 million tonnes): N. America (Great Lakes, Labrador), Russia–Kazakhstan (Urals, Magnitogorsk), Brazil (Carajas, Itabira, Minas Gerais), Australia (Koolyanobbing, Iron Knob/Iron Duke), Europe (Lorraine, S. Wales), Africa (Transvaal, Liberia), China (Manchuria, Anshan).","linkedLayerId":"iron-belts"},{"id":"f6","text":"IRON ORE, India — ~95% of reserves in Odisha, Jharkhand, Chhattisgarh, Karnataka, Goa, TN, AP, Telangana. Belts: Odisha (Sundergarh, Mayurbhanj); Jharkhand (oldest mines — Noamundi & Gua in Singhbhum); Chhattisgarh (Durg, Dantewada, BAILADILA); Karnataka (Sandur–Hospet in Ballari, Baba Budan hills, Kudremukh); plus Goa, Maharashtra (Chandrapur, Ratnagiri) and Tamil Nadu (Salem, Nilgiris).","linkedLayerId":"iron-belts"},{"id":"f7","text":"COAL — the most UNEVENLY distributed mineral; used for thermal power and smelting. China (Shansi, Fushun, Shenyang), USA (Appalachia: Kentucky, Illinois…), Europe (Ruhr, Upper Silesia, Durham), Russia (Moscow, Ob & Lena basins), Australia (Newcastle), Africa (Transvaal, Natal). India: JHARIA, BOKARO, RANIGANJ on the Damodar; Korba, Singrauli, Talcher, Singareni; NEYVELI = lignite.","linkedLayerId":"coal-fields"},{"id":"f8","text":"COPPER — CHILE leads with ~27% of world output (Escondida and Collahuasi are among the biggest mines on earth); PERU next (~10%). India: Singhbhum (Jharkhand), Balaghat (MP), Jhunjhunu & Alwar (Rajasthan). Resources split: RENEWABLE (solar, wind — replenish fast) vs NON-RENEWABLE (coal, petroleum, gas — fixed stock, millennia to renew).","linkedLayerId":"other-minerals"}],"quiz":[{"id":"q1","type":"mcq","question":"“Industrial inertia” means:","options":["Industries always chase the cheapest labour","Industries tend to stay in a location even after its original advantage has disappeared","Government freezes on new factories","The slowdown of heavy industry"],"answerIndex":1,"explanation":"The predisposition of firms to avoid relocating even when the founding advantage (a coalfield, a port subsidy) is gone — sunk capital, linked suppliers and skilled labour hold them in place."},{"id":"q2","type":"map_click","question":"Click the Ruhr — Europe’s classic coal-and-steel industrial region.","answer":{"lat":51.5,"lng":7.2,"toleranceKm":500},"explanation":"The Ruhr in western Germany: coal seams + Rhine transport + iron (initially local, later imported Lorraine/Swedish ore) = the template every textbook uses."},{"id":"q3","type":"mcq","question":"Roughly what share of India’s iron-ore reserves lies in Odisha, Jharkhand, Chhattisgarh, Karnataka, Goa, TN, AP and Telangana together?","options":["50%","70%","95%","25%"],"answerIndex":2,"explanation":"About 95% — the peninsular shield holds the ore. Flagship mines: Noamundi & Gua (Singhbhum, Jharkhand — the oldest), Bailadila (Chhattisgarh), Sandur–Hospet (Ballari, Karnataka)."},{"id":"q4","type":"map_click","question":"Click the Damodar valley coal belt — Jharia, Bokaro, Raniganj.","answer":{"lat":23.7,"lng":86.4,"toleranceKm":250},"explanation":"The Damodar valley (Jharkhand–West Bengal) is India’s prime coking-coal store — which is exactly why the Chotanagpur industrial region (Jamshedpur!) sits beside it."},{"id":"q5","type":"mcq","question":"The world’s leading copper producer, with ~27% of output and the Escondida mine, is:","options":["Peru","Chile","DR Congo","Australia"],"answerIndex":1,"explanation":"Chile — Escondida and Collahuasi are among the biggest mines on earth. Peru follows at ~10%. In India: Singhbhum, Balaghat, Jhunjhunu–Alwar."},{"id":"q6","type":"mcq","question":"Neyveli (Tamil Nadu) is best known for:","options":["Iron ore","Lignite coal","Copper","Bauxite"],"answerIndex":1,"explanation":"Neyveli mines LIGNITE (brown coal) feeding thermal power. The hard-coal heartland is the Damodar valley: Jharia, Bokaro, Raniganj."},{"id":"q7","type":"mcq","question":"Which factor best explains the Great Lakes industrial region?","options":["Cheap labour from the South","Mesabi iron ore meeting Appalachian coal over cheap water transport","Proximity to the Pacific ports","Government subsidies alone"],"answerIndex":1,"explanation":"Iron from the Mesabi range sailed down the lakes to meet Appalachian coal — assembly cost minimised on water, the cheapest transport. Same logic as the Ruhr and Chotanagpur."}]},"position":9,"hash":"561350893c08d1972819065c791fe78c659155bb3ee88819ebb495fcbe4a5255"},{"body":{"id":"world-atmosphere-heat","subject":"geography","unit":"World","tags":["tropic-of-cancer","insolation","ozone","heat-budget","monsoon"],"title":"World: Atmosphere & Heat Zones","summary":"Five layers overhead, three heat zones on the map, one heat budget.","focus":"Sunlight arrives at an angle — latitude decides everything. The torrid, temperate and frigid zones are just the geometry of the overhead sun; the atmosphere’s five layers and the heat budget do the rest.","view":{"center":[15,30],"zoom":2},"worldExtent":true,"basemap":"relief","theme":{"accent":"#c07a1a","mapBg":"#f6f0e2"},"layers":[{"id":"heat-zones","name":"Three heat zones","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"torrid","name":"TORRID ZONE — between the tropics (23½°N–23½°S): overhead sun at least once a year"},"geometry":{"type":"Polygon","coordinates":[[[-180,-23.5],[180,-23.5],[180,23.5],[-180,23.5],[-180,-23.5]]]}},{"type":"Feature","properties":{"id":"temperate-n","name":"NORTH TEMPERATE ZONE (23½°–66½°N): slanting sun, moderate heat"},"geometry":{"type":"Polygon","coordinates":[[[-180,23.5],[180,23.5],[180,66.5],[-180,66.5],[-180,23.5]]]}},{"type":"Feature","properties":{"id":"temperate-s","name":"SOUTH TEMPERATE ZONE (23½°–66½°S)"},"geometry":{"type":"Polygon","coordinates":[[[-180,-66.5],[180,-66.5],[180,-23.5],[-180,-23.5],[-180,-66.5]]]}},{"type":"Feature","properties":{"id":"frigid-n","name":"NORTH FRIGID ZONE (66½°–90°N): sun never far above horizon"},"geometry":{"type":"Polygon","coordinates":[[[-180,66.5],[180,66.5],[180,90],[-180,90],[-180,66.5]]]}},{"type":"Feature","properties":{"id":"frigid-s","name":"SOUTH FRIGID ZONE (66½°–90°S)"},"geometry":{"type":"Polygon","coordinates":[[[-180,-90],[180,-90],[180,-66.5],[-180,-66.5],[-180,-90]]]}}]},"style":{"color":"#c07a1a","weight":1,"fillColor":"#e0a24e","fillOpacity":0.18,"pattern":"dots"},"defaultOn":true,"labelKey":"name"},{"id":"key-latitudes","name":"Key latitudes","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"cancer","name":"Tropic of Cancer, 23½°N — crosses India through 8 states (and Mizoram!)"},"geometry":{"type":"LineString","coordinates":[[-180,23.5],[180,23.5]]}},{"type":"Feature","properties":{"id":"capricorn","name":"Tropic of Capricorn, 23½°S"},"geometry":{"type":"LineString","coordinates":[[-180,-23.5],[180,-23.5]]}},{"type":"Feature","properties":{"id":"equator-l","name":"Equator, 0° — maximum annual insolation"},"geometry":{"type":"LineString","coordinates":[[-180,0],[180,0]]}},{"type":"Feature","properties":{"id":"arctic","name":"Arctic Circle, 66½°N — midnight sun / polar night begins"},"geometry":{"type":"LineString","coordinates":[[-180,66.5],[180,66.5]]}}]},"style":{"color":"#b3261e","weight":2,"dashArray":"8 6"},"defaultOn":true,"labelKey":"name"}],"facts":[{"id":"f1","text":"Atmosphere composition: nitrogen ~78%, oxygen ~21%, argon ~0.93%, CO₂ ~0.04% — but the climatic action lives in the minor players: WATER VAPOUR, particulate matter (dust as condensation nuclei), CO₂ and OZONE, which absorb and re-radiate heat."},{"id":"f2","text":"Five layers, ascending: TROPOSPHERE (up to ~18 km over the equator, ~8 km at poles — thickest where heating is greatest) — ALL weather (cyclones, clouds, rain) happens here; the TROPOPAUSE caps it. STRATOSPHERE (to 50 km): temperature RISES with height because ozone absorbs UV — jets fly in its calm lower reaches; the OZONOSPHERE spans the stratosphere and lower mesosphere. MESOSPHERE: coldest layer — meteors burn here. THERMOSPHERE/IONOSPHERE: radio waves reflect. EXOSPHERE: fades to space."},{"id":"f3","text":"INSOLATION = incoming solar radiation. Factors: (1) solar output — the ~11-year sunspot cycle swings it between ~1340 and 1380 W/m²; (2) ANGLE OF INCIDENCE — insolation falls as latitude rises (slanting rays spread over more area and cross more atmosphere); (3) duration of day; (4) distance from the sun — perihelion (Jan, nearest) vs aphelion (July, farthest); (5) transparency of the atmosphere."},{"id":"f4","text":"HEAT BUDGET: the earth keeps a constant temperature because heat received (insolation) exactly equals heat lost (terrestrial radiation). Of 100 units arriving: roughly a third is reflected straight back (ALBEDO — clouds, ice, dust); the rest is absorbed by atmosphere and surface, then returned as long-wave terrestrial radiation. The atmosphere is heated mainly FROM BELOW — by terrestrial radiation, conduction and convection — not directly by sunlight."},{"id":"f5","text":"The three heat zones are pure geometry: TORRID zone (23½°N–23½°S) — the overhead sun visits at least once a year; TEMPERATE zones (23½°–66½°) — never overhead, always slanting; FRIGID zones (66½°–poles) — the sun barely climbs, and inside the polar circles you get midnight sun and polar night.","linkedLayerId":"heat-zones"},{"id":"f6","text":"The TROPIC OF CANCER threads India through eight states — Gujarat, Rajasthan, MP, Chhattisgarh, Jharkhand, West Bengal, Tripura and MIZORAM — the same line you saw in the Mizoram chapter. Latitude connects the world map to the home map.","linkedLayerId":"key-latitudes","linkedFeatureId":"cancer"}],"quiz":[{"id":"q1","type":"mcq","question":"All weather phenomena — cyclones, clouds, rain — occur in which layer?","options":["Stratosphere","Troposphere","Mesosphere","Thermosphere"],"answerIndex":1,"explanation":"The troposphere — thickest (~18 km) over the equator because of stronger convection, ~8 km at the poles. The tropopause caps it; jets prefer the calm stratosphere above."},{"id":"q2","type":"mcq","question":"Temperature RISES with height in the stratosphere because:","options":["It is closer to the sun","Ozone absorbs ultraviolet radiation there","Jet engines heat it","CO₂ concentrates there"],"answerIndex":1,"explanation":"The ozonosphere (spanning the stratosphere and lower mesosphere) absorbs harmful UV — warming the layer and shielding life. The mesosphere above is the coldest layer."},{"id":"q3","type":"map_click","question":"Click anywhere on the Torrid Zone — the belt where the sun is overhead at least once a year.","answer":{"lat":0,"lng":20,"toleranceKm":2600},"explanation":"Between the tropics, 23½°N to 23½°S. Overhead sun = maximum insolation = the engine room of the global circulation (Hadley cells, monsoons)."},{"id":"q4","type":"mcq","question":"Insolation DECREASES as latitude increases mainly because:","options":["The poles are farther from the sun","Slanting rays spread over a larger area and cross more atmosphere","There is more ozone at the poles","The earth spins slower at the poles"],"answerIndex":1,"explanation":"Angle of incidence: oblique rays deliver less energy per unit area and lose more to a longer atmospheric path. Latitude and insolation vary inversely — the whole heat-zone map follows."},{"id":"q5","type":"mcq","question":"The earth’s heat budget means:","options":["The earth slowly accumulates solar heat","Heat received (insolation) equals heat emitted (terrestrial radiation), so overall temperature stays constant","The oceans store all incoming heat","Albedo equals insolation"],"answerIndex":1,"explanation":"A perfect balance: intake = outflow, so the planet as a whole neither gains nor loses heat. Albedo is the ~third reflected straight back by clouds, ice and dust."},{"id":"q6","type":"mcq","question":"The atmosphere is heated mainly by:","options":["Direct absorption of incoming sunlight","Terrestrial (long-wave) radiation from below, plus conduction and convection","Ozone reactions","Lightning"],"answerIndex":1,"explanation":"The surface absorbs short-wave solar energy and re-emits long-wave radiation, which the lower atmosphere (water vapour, CO₂) traps — heating from BELOW. That’s why temperature falls with height in the troposphere."},{"id":"q7","type":"mcq","question":"The 11-year cycle affecting solar output (≈1340–1380 W/m²) is the:","options":["Milankovitch cycle","Sunspot cycle","El Niño cycle","Precession cycle"],"answerIndex":1,"explanation":"The sunspot cycle — one of five insolation factors, alongside angle of incidence, day length, sun–earth distance (perihelion Jan / aphelion July) and atmospheric transparency."}]},"position":10,"hash":"8d10b14a31e7d2ecfc48b3e24a476c13db25d3439bebae85a7acefb47682aacd"},{"body":{"id":"indus-valley","subject":"history","unit":"Ancient","tags":["indus","ravi","chenab","ghaggar-saraswati","gujarat","punjab"],"title":"Indus Valley Civilization","summary":"Bronze Age cities on the Indus — sites, rivers, excavators, extremes.","focus":"Every IVC exam question is secretly a map question: pin each site to its river, its excavator, and its direction on the map — Manda north, Daimabad south, Sutkagendor west, Alamgirpur east.","view":{"center":[26.5,71.5],"zoom":5},"basemap":"natgeo","theme":{"accent":"#a5622d","mapBg":"#f6efe4"},"layers":[{"id":"ivc-extent","name":"Civilization extent","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"ivc-extent","name":"Approximate spread of the Harappan Civilization"},"geometry":{"type":"Polygon","coordinates":[[[61.5,25],[66,28.5],[69,34],[75,33.5],[78,29.5],[76.5,27],[75.5,22.5],[75,19.2],[73.5,19],[71.5,21],[68.5,22.5],[66.5,24.5],[61.5,25]]]}}]},"style":{"color":"#a5622d","weight":1.5,"fillColor":"#c98a4b","fillOpacity":0.25,"pattern":"dots"},"defaultOn":true,"labelKey":"name"},{"id":"ivc-sites","name":"Major sites","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"harappa","name":"Harappa — R. Ravi — Dayaram Sahni, 1921 (capital city)"},"geometry":{"type":"Point","coordinates":[72.87,30.63]}},{"type":"Feature","properties":{"id":"mohenjodaro","name":"Mohenjodaro — R. Indus — R.D. Banerji, 1922 (largest site; Great Bath)"},"geometry":{"type":"Point","coordinates":[68.14,27.33]}},{"type":"Feature","properties":{"id":"chanhudaro","name":"Chanhudaro (Sindh) — only site without a citadel"},"geometry":{"type":"Point","coordinates":[68.32,26.17]}},{"type":"Feature","properties":{"id":"kalibangan","name":"Kalibangan (Rajasthan) — world’s first ploughed field"},"geometry":{"type":"Point","coordinates":[74.13,29.47]}},{"type":"Feature","properties":{"id":"lothal","name":"Lothal (Gujarat) — port city; dockyard; rice husk"},"geometry":{"type":"Point","coordinates":[72.25,22.52]}},{"type":"Feature","properties":{"id":"dholavira","name":"Dholavira (Gujarat) — three-part city; water reservoirs"},"geometry":{"type":"Point","coordinates":[70.21,23.89]}},{"type":"Feature","properties":{"id":"banawali","name":"Banawali (Haryana)"},"geometry":{"type":"Point","coordinates":[75.39,29.6]}},{"type":"Feature","properties":{"id":"rakhigarhi","name":"Rakhigarhi (Haryana) — largest site in India"},"geometry":{"type":"Point","coordinates":[76.11,29.29]}}]},"style":{"color":"#7a3b10","weight":2,"fillColor":"#7a3b10","fillOpacity":0.9,"shadow":true},"defaultOn":true,"labelKey":"name"},{"id":"ivc-extremes","name":"Extreme points (N/S/E/W)","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"manda","name":"NORTH: Manda (Jammu) — R. Chenab"},"geometry":{"type":"Point","coordinates":[74.85,32.72]}},{"type":"Feature","properties":{"id":"daimabad","name":"SOUTH: Daimabad (Maharashtra) — R. Pravara"},"geometry":{"type":"Point","coordinates":[74.71,19.51]}},{"type":"Feature","properties":{"id":"sutkagendor","name":"WEST: Sutkagendor — Makran coast (also a port)"},"geometry":{"type":"Point","coordinates":[62.03,25.5]}},{"type":"Feature","properties":{"id":"alamgirpur","name":"EAST: Alamgirpur (Western U.P.)"},"geometry":{"type":"Point","coordinates":[77.48,29]}},{"type":"Feature","properties":{"id":"shortugai","name":"Shortugai (Afghanistan) — farthest outpost, lapis lazuli trade"},"geometry":{"type":"Point","coordinates":[69.5,37.35]}}]},"style":{"color":"#b3261e","weight":2,"fillColor":"#b3261e","fillOpacity":0.9,"shadow":true},"defaultOn":false,"labelKey":"name"}],"facts":[{"id":"f1","text":"The IVC belongs to the Bronze Age and to the Proto-history of India. Its contemporaries were Mesopotamia (Tigris–Euphrates), Egypt (Nile), and China (Hwang Ho). Phases: Early 3500–2600 BC, Mature 2600–1900 BC, Late 1900–1500 BC."},{"id":"f2","text":"Discovery chain: Charles Masson noticed the ruins in 1826; Alexander Cunningham collected seals five decades later; Dayaram Sahni excavated Harappa in 1921 (banks of the Ravi); R.D. Banerji excavated Mohenjodaro (“mound of the dead”) in 1922 on the Indus; in 1924 John Marshall named it the Indus Valley Civilization.","linkedLayerId":"ivc-sites"},{"id":"f3","text":"Extremes — memorize as a compass: Manda in Jammu (river Chenab) is the northernmost site, Daimabad in Maharashtra (river Pravara) the southernmost, Sutkagendor on the Makran coast the westernmost, Alamgirpur in western U.P. the easternmost. Shortugai in Afghanistan was a distant trade outpost.","linkedLayerId":"ivc-extremes"},{"id":"f4","text":"Superlatives: Mohenjodaro is the largest site overall; Rakhigarhi (Haryana) is the largest site in India; Harappa and Mohenjodaro were the “capital cities”; Lothal and Sutkagendor were port cities.","linkedLayerId":"ivc-sites"},{"id":"f5","text":"Town planning: grid system with streets at right angles; the raised Citadel on the western mound housed public buildings and the ruling class, the lower eastern town housed common people; brilliant covered drains of mortar, lime and gypsum. The Great Bath (with bitumen-lined bed) and a granary stand at Mohenjodaro; Harappa also had granaries."},{"id":"f6","text":"Economy: main crops wheat and barley; rice evidence at Lothal and Rangpur; world’s first ploughed field found at Kalibangan; the Indus people were the first in the world to produce cotton (Greeks called it Sindon). Trade with Mesopotamia was by barter — no coins; Sumerian texts call the Indus region “Meluha”."},{"id":"f7","text":"Things the Harappans did NOT know — a favourite trick question: iron, the horse (debated), the lion, and sugarcane. Weights were made of limestone and steatite, usually cubical."}],"events":[{"id":"e1","date":"1826","label":"Masson","description":"Charles Masson first records the ruins of Harappa.","view":{"center":[30.63,72.87],"zoom":6}},{"id":"e2","date":"1921","label":"Harappa dug","description":"Dayaram Sahni excavates Harappa on the banks of the Ravi (Sahiwal district, Pakistan).","showLayers":["ivc-sites"],"view":{"center":[30.63,72.87],"zoom":7}},{"id":"e3","date":"1922","label":"Mohenjodaro dug","description":"R.D. Banerji excavates Mohenjodaro — “mound of the dead” — on the Indus.","showLayers":["ivc-sites"],"view":{"center":[27.33,68.14],"zoom":7}},{"id":"e4","date":"1924","label":"Named IVC","description":"John Marshall announces and names the Indus Valley Civilization. Historians prefer “Harappan Civilization” — named after the first site found.","showLayers":["ivc-extent","ivc-sites","ivc-extremes"],"view":{"center":[26.5,71.5],"zoom":5}}],"quiz":[{"id":"q1","type":"map_click","question":"Click Mohenjodaro — the largest Harappan site, excavated by R.D. Banerji in 1922.","answer":{"lat":27.33,"lng":68.14,"toleranceKm":150},"explanation":"Mohenjodaro (“mound of the dead”) sits on the Indus in Sindh. It holds the Great Bath (bitumen-lined, for ritual bathing) and a granary to its west."},{"id":"q2","type":"mcq","question":"Match the excavation: Harappa (1921) and Mohenjodaro (1922) were dug by, respectively:","options":["John Marshall and Charles Masson","Dayaram Sahni and R.D. Banerji","R.D. Banerji and Dayaram Sahni","Alexander Cunningham and John Marshall"],"answerIndex":1,"explanation":"Dayaram Sahni excavated Harappa (1921, river Ravi); R.D. Banerji excavated Mohenjodaro (1922, river Indus). John Marshall only *named* the civilization in 1924; Masson had noticed the ruins back in 1826."},{"id":"q3","type":"mcq","question":"Which pairing of extreme points is CORRECT?","options":["North: Alamgirpur — East: Manda","West: Daimabad — South: Sutkagendor","North: Manda (Chenab) — South: Daimabad (Pravara)","East: Shortugai — West: Rakhigarhi"],"answerIndex":2,"explanation":"Manda in Jammu on the Chenab is northernmost; Daimabad in Maharashtra on the Pravara is southernmost. Sutkagendor (Makran coast) is westernmost and Alamgirpur (western U.P.) easternmost."},{"id":"q4","type":"map_click","question":"Click Lothal — the port city where rice husk was found.","answer":{"lat":22.52,"lng":72.25,"toleranceKm":120},"explanation":"Lothal in Gujarat had a dockyard and yielded rice evidence (with Rangpur). The other port was Sutkagendor far west on the Makran coast."},{"id":"q5","type":"mcq","question":"The world’s first ploughed field was found at:","options":["Lothal","Kalibangan","Banawali","Dholavira"],"answerIndex":1,"explanation":"Kalibangan in Rajasthan preserves furrow marks of the world’s earliest ploughed field. Harappans used wooden ploughshares and stone sickles."},{"id":"q6","type":"mcq","question":"Which of these was UNKNOWN to the Indus people?","options":["Cotton","Iron","Barley","The bull"],"answerIndex":1,"explanation":"Iron, the lion, and sugarcane were unknown; there were no coins (barter trade). They were, however, the FIRST in the world to grow cotton — the Greeks called it Sindon."},{"id":"q7","type":"map_click","question":"Click Rakhigarhi — the largest Harappan site within India.","answer":{"lat":29.29,"lng":76.11,"toleranceKm":120},"explanation":"Rakhigarhi in Haryana is India’s largest Harappan site; Mohenjodaro (in Pakistan) is the largest overall."},{"id":"q8","type":"mcq","question":"In Harappan town planning, the Citadel stood:","options":["On the lower eastern mound, for common people","At the exact centre of the grid","On the higher western mound, housing public buildings and the ruling class","Outside the city walls"],"answerIndex":2,"explanation":"Citadel = higher mound, WESTERN side, public buildings + rulers. The lower EASTERN town housed commoners. Streets crossed at right angles, with covered drains of mortar, lime and gypsum."}]},"position":11,"hash":"a34d8c158ac63c206d3b08d38d44f84e9806dc96a3ddbfff530ed7af8ddec9aa"},{"body":{"id":"vedic-age","subject":"history","unit":"Ancient","tags":["indus","jhelum","chenab","ravi","beas","sutlej","ghaggar-saraswati","punjab","ganga","northern-plains"],"title":"The Vedic Age","summary":"Sapta Sindhu river names, Rig Vedic society, and the eastward shift.","focus":"The Rig Veda is a map: Sapta Sindhu is the Punjab river system under older names (Vitasta=Jhelum, Asikni=Chenab, Parushni=Ravi, Vipasha=Beas, Shutudri=Sutlej). Then, 1000–500 BC, the whole civilization slides east down the Ganga.","view":{"center":[29.5,75.5],"zoom":5},"basemap":"natgeo","theme":{"accent":"#9a6b1f","mapBg":"#f7f0df"},"layers":[{"id":"sapta-sindhu","name":"Sapta Sindhu rivers","description":"Vedic names ↔ modern rivers.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"sindhu","name":"Sindhu = INDUS — the axis of the Sapta Sindhu"},"geometry":{"type":"LineString","coordinates":[[74.5,34.5],[72.5,33],[70.9,31],[69.5,28.5],[68.3,26],[67.9,24.3]]}},{"type":"Feature","properties":{"id":"vitasta","name":"Vitasta = JHELUM"},"geometry":{"type":"LineString","coordinates":[[74.8,34.1],[73.7,33],[72.6,31.9],[71.7,31.2]]}},{"type":"Feature","properties":{"id":"asikni","name":"Asikni = CHENAB"},"geometry":{"type":"LineString","coordinates":[[76.6,33.4],[74.9,32.5],[73.5,31.7],[71.9,30.9]]}},{"type":"Feature","properties":{"id":"parushni","name":"Parushni = RAVI — river of the Battle of Ten Kings"},"geometry":{"type":"LineString","coordinates":[[76.5,32.5],[75.2,31.9],[73.9,31.2],[72.5,30.6]]}},{"type":"Feature","properties":{"id":"vipasha","name":"Vipasha = BEAS"},"geometry":{"type":"LineString","coordinates":[[77.1,32],[76,31.6],[75.1,31.4],[74.8,31.2]]}},{"type":"Feature","properties":{"id":"shutudri","name":"Shutudri = SUTLEJ"},"geometry":{"type":"LineString","coordinates":[[78.7,31.8],[76.8,31.2],[75.3,30.8],[73.8,30.2],[72.2,29.6]]}},{"type":"Feature","properties":{"id":"saraswati","name":"Saraswati — the lost river (Ghaggar–Hakra bed)"},"geometry":{"type":"LineString","coordinates":[[77.2,30.5],[76,29.9],[74.8,29.4],[73.6,28.9],[72.5,28.3]]}}]},"style":{"color":"#1f5fa8","weight":3,"flow":true},"defaultOn":true,"labelKey":"name"},{"id":"eastward-shift","name":"Eastward shift (Later Vedic)","description":"Punjab → doab → eastern UP/Bihar, 1000–500 BC.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"shift","name":"The great eastward shift, 1000–500 BC: Punjab → Ganga–Yamuna doab → eastern UP/Bihar"},"geometry":{"type":"LineString","coordinates":[[73.5,31],[76,29.8],[78,28.6],[80.5,27.2],[83,26],[85.1,25.6]]}},{"type":"Feature","properties":{"id":"early-home","name":"Early Vedic homeland — Sapta Sindhu (Punjab)"},"geometry":{"type":"Point","coordinates":[73.5,31]}},{"type":"Feature","properties":{"id":"later-home","name":"Later Vedic heartland — Ganga–Yamuna doab (Kuru–Panchala)"},"geometry":{"type":"Point","coordinates":[78.5,28.4]}},{"type":"Feature","properties":{"id":"pgw","name":"Hastinapura — Painted Grey Ware culture zone"},"geometry":{"type":"Point","coordinates":[78,29.15]}}]},"style":{"color":"#9a6b1f","weight":3,"dashArray":"2 8","flow":true,"markerRadius":7,"glow":true},"defaultOn":false,"labelKey":"name"}],"facts":[{"id":"f1","text":"The Vedic people — Indo-European speakers believed to originate in the Steppes of southern Russia and Central Asia — appeared in India a little before 1500 BC, migrating in waves. Periods: Early/Rig Vedic 1500–1000 BC (Sapta Sindhu, late Bronze–early Iron), Later Vedic 1000–500 BC (Ganga–Yamuna valleys)."},{"id":"f2","text":"The Rig Veda — the earliest Indo-European text — mentions about 40 rivers. The exam pairs: Vitasta=Jhelum, Asikni=Chenab, Parushni=Ravi, Vipasha=Beas, Shutudri=Sutlej, plus the Sindhu (Indus) and the Saraswati (the “lost” Ghaggar). The Battle of Ten Kings (Dasarajna) was fought on the Parushni — the Ravi.","linkedLayerId":"sapta-sindhu"},{"id":"f3","text":"Rig Vedic economy: primarily PASTORAL — the cow was the chief wealth and unit of exchange, most wars were fought over cattle; agriculture was secondary. Horses and spoke-wheeled chariots were their signature technology (both unknown to the Harappans — a favourite contrast question). No clear evidence of trade or coins."},{"id":"f4","text":"Polity: the tribe (Jana/Vis) under a hereditary chief, the RAJAN, checked by assemblies — SABHA (council of elders), SAMITI (national assembly; even elected the Rajan in traces), VIDATHA and GANA. Women attended Sabha and Vidatha in the early period. Bali = voluntary offering, not tax; no standing army. Purohita (Vasishtha the conservative, Vishvamitra the liberal) was the key functionary; Senani led the army; Gramani headed the village."},{"id":"f5","text":"Society: patriarchal, kinship-based; Kula/Griha = family; Vis divided into gramas — when gramas clashed it was SAMGRAMA (the literal origin of the word for war). Monogamy prevailed, widow remarriage existed, and there is no evidence of child marriage in the Rig Vedic period."},{"id":"f6","text":"Later Vedic changes (1000–500 BC): iron (shyama ayas) clears the Ganga forests; agriculture overtakes cattle; territory replaces tribe (Rashtra appears); the varna order hardens; Sabha and Samiti fade before rising kingship. Painted Grey Ware pottery marks the doab settlements like Hastinapura. This eastward world is the stage on which the Mahajanapadas rise.","linkedLayerId":"eastward-shift"},{"id":"f7","text":"Vedic literature ladder: 4 Vedas (Rig — hymns; Sama — melodies; Yajur — rituals; Atharva — charms) → Brahmanas (ritual explanation) → Aranyakas (forest books) → Upanishads (philosophy; “Satyameva Jayate” comes from the Mundaka Upanishad). The Gayatri mantra is addressed to the solar deity Savitri."}],"events":[{"id":"e1","date":"-1500","label":"Arrival","description":"Rig Vedic people settle the Sapta Sindhu — the land of seven rivers (Punjab and fringes).","showLayers":["sapta-sindhu"],"hideLayers":["eastward-shift"],"view":{"center":[31,73.5],"zoom":6}},{"id":"e2","date":"-1200","label":"Ten Kings","description":"Battle of Ten Kings (Dasarajna) on the Parushni (Ravi): Sudas of the Bharatas defeats the tribal confederacy.","showLayers":["sapta-sindhu"],"view":{"center":[31.2,74.5],"zoom":7}},{"id":"e3","date":"-1000","label":"Iron & the move east","description":"Iron technology clears the forests; the centre of gravity shifts into the Ganga–Yamuna doab (Kuru–Panchala country).","showLayers":["sapta-sindhu","eastward-shift"],"view":{"center":[28.5,78],"zoom":6}},{"id":"e4","date":"-0600","label":"Threshold","description":"By 600 BC the Later Vedic world dissolves into the sixteen Mahajanapadas — pick up the story in the next chapter.","showLayers":["eastward-shift"],"view":{"center":[26.5,81],"zoom":5}}],"quiz":[{"id":"q1","type":"mcq","question":"Match the Vedic river names — which pairing is WRONG?","options":["Vitasta = Jhelum","Asikni = Chenab","Parushni = Sutlej","Vipasha = Beas"],"answerIndex":2,"explanation":"Parushni = RAVI (the Battle of Ten Kings river). Shutudri = Sutlej. The full set: Vitasta–Jhelum, Asikni–Chenab, Parushni–Ravi, Vipasha–Beas, Shutudri–Sutlej."},{"id":"q2","type":"map_click","question":"Click the Ravi (Parushni) — the river of the Battle of Ten Kings.","answer":{"lat":31.2,"lng":74.5,"toleranceKm":130},"explanation":"The Ravi flows past Lahore — the same river whose banks hold Harappa. One river, two chapters of history: a connection worth remembering."},{"id":"q3","type":"mcq","question":"In Rig Vedic polity, the SAMITI was:","options":["The council of elders","The national assembly of the people, with traces of electing the Rajan","The kings bodyguard","A tax on cattle"],"answerIndex":1,"explanation":"Samiti = national assembly (even shows traces of electing the chief); Sabha = council of elders. Women attended Sabha and Vidatha. Bali was a voluntary offering — there was no regular taxation."},{"id":"q4","type":"mcq","question":"The chief form of wealth and the standard unit of exchange in the Early Vedic period was:","options":["Gold coins","Land","The cow","The horse"],"answerIndex":2,"explanation":"The cow — most wars were fought over cattle (the word for war, samgrama, literally comes from clashing gramas). The horse mattered almost as much (chariots), but the cow was the currency."},{"id":"q5","type":"mcq","question":"Which TWO things, central to Vedic life, were absent at Harappa?","options":["Cotton and barley","The horse and the spoked-wheel chariot","Bronze and copper","Cattle and pottery"],"answerIndex":1,"explanation":"The Harappans did not know the horse (or iron); the Vedic people arrived with horse-drawn, spoke-wheeled chariots and probably introduced the spoked wheel to India. Classic contrast question between the two chapters."},{"id":"q6","type":"map_click","question":"Click the Later Vedic heartland — the Ganga–Yamuna doab (Kuru–Panchala country).","answer":{"lat":28.4,"lng":78.5,"toleranceKm":160},"explanation":"By 1000 BC iron axes and ploughs pulled the centre of gravity from Punjab into the doab — Hastinapura and the Painted Grey Ware sites mark it."},{"id":"q7","type":"mcq","question":"“Satyameva Jayate”, on India’s national emblem, comes from the:","options":["Rig Veda","Mundaka Upanishad","Sama Veda","Aitareya Brahmana"],"answerIndex":1,"explanation":"The Mundaka Upanishad. Ladder to remember: Vedas → Brahmanas → Aranyakas → Upanishads (ritual to philosophy)."}]},"position":12,"hash":"2d3b6c458a275f0c818f7f25eaa16e29bfd9ad01c1f2395e637d3fa2e81b5f2b"},{"body":{"id":"mahajanapadas-mauryas","subject":"history","unit":"Ancient","tags":["ganga","pataliputra","rajgir","vaishali","magadha","kalinga","taxila","bihar"],"title":"Mahajanapadas → Mauryas","summary":"16 states, the rise of Magadha, and Ashoka’s empire of Dhamma.","focus":"Sixteen Mahajanapadas contested the Gangetic plain; Magadha absorbed them all. The Mauryan climax — and the moral pivot of Indian history — happened on the map at Kalinga, 261 BC.","view":{"center":[24.5,81],"zoom":5},"basemap":"paper","theme":{"accent":"#8a5a00","mapBg":"#f7f1e2","tileUrl":""},"layers":[{"id":"mahajanapadas","name":"16 Mahajanapadas (capitals)","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"magadha","name":"Magadha — cap. Rajgir (Girivraja)"},"geometry":{"type":"Point","coordinates":[85.42,25.03]}},{"type":"Feature","properties":{"id":"kosala","name":"Kosala — cap. Shravasti"},"geometry":{"type":"Point","coordinates":[82.03,27.52]}},{"type":"Feature","properties":{"id":"vatsa","name":"Vatsa — cap. Kausambi"},"geometry":{"type":"Point","coordinates":[81.39,25.34]}},{"type":"Feature","properties":{"id":"avanti","name":"Avanti — cap. Ujjain"},"geometry":{"type":"Point","coordinates":[75.78,23.18]}},{"type":"Feature","properties":{"id":"vajji","name":"Vajji — cap. Vaishali (republican)"},"geometry":{"type":"Point","coordinates":[85.13,25.99]}},{"type":"Feature","properties":{"id":"anga","name":"Anga — cap. Champa"},"geometry":{"type":"Point","coordinates":[87.04,25.24]}},{"type":"Feature","properties":{"id":"kashi","name":"Kashi — cap. Varanasi"},"geometry":{"type":"Point","coordinates":[83.01,25.32]}},{"type":"Feature","properties":{"id":"kuru","name":"Kuru — cap. Indraprastha"},"geometry":{"type":"Point","coordinates":[77.24,28.61]}},{"type":"Feature","properties":{"id":"panchala","name":"Panchala — cap. Ahichchhatra / Kampilya"},"geometry":{"type":"Point","coordinates":[79.13,28.37]}},{"type":"Feature","properties":{"id":"matsya","name":"Matsya — cap. Viratanagara"},"geometry":{"type":"Point","coordinates":[76.18,27.42]}},{"type":"Feature","properties":{"id":"shurasena","name":"Shurasena — cap. Mathura"},"geometry":{"type":"Point","coordinates":[77.67,27.5]}},{"type":"Feature","properties":{"id":"chedi","name":"Chedi — cap. Shuktimati"},"geometry":{"type":"Point","coordinates":[80.33,25.48]}},{"type":"Feature","properties":{"id":"malla","name":"Malla — cap. Kushinara / Pava (republican)"},"geometry":{"type":"Point","coordinates":[83.89,26.74]}},{"type":"Feature","properties":{"id":"gandhara","name":"Gandhara — cap. Taxila"},"geometry":{"type":"Point","coordinates":[72.79,33.74]}},{"type":"Feature","properties":{"id":"kamboja","name":"Kamboja — far northwest"},"geometry":{"type":"Point","coordinates":[71.5,34.5]}},{"type":"Feature","properties":{"id":"asmaka","name":"Asmaka — on the Godavari (only southern one)"},"geometry":{"type":"Point","coordinates":[77.9,18.67]}}]},"style":{"color":"#8a5a00","weight":2,"fillColor":"#c08a1a","fillOpacity":0.9,"shadow":true},"defaultOn":true,"labelKey":"name"},{"id":"maurya-extent","name":"Mauryan Empire (Ashoka)","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"maurya-extent","name":"Mauryan Empire under Ashoka (except extreme south)"},"geometry":{"type":"Polygon","coordinates":[[[66,25],[62,29.5],[66,34],[71,36.5],[77,35.5],[80,30.5],[88,27.5],[92,26],[91.5,22.5],[86.5,20],[83,17],[79.5,13.5],[76.5,13],[74.5,16],[72.5,20],[68.5,22.5],[66,25]]]}}]},"style":{"color":"#7a3b10","weight":1.5,"fillColor":"#c98a4b","fillOpacity":0.2,"pattern":"hatch"},"defaultOn":false,"labelKey":"name"},{"id":"key-sites","name":"Capitals & Kalinga","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"rajgir","name":"Rajgir — first Magadhan capital"},"geometry":{"type":"Point","coordinates":[85.42,25.03]}},{"type":"Feature","properties":{"id":"pataliputra","name":"Pataliputra — imperial capital (Ganga confluence)"},"geometry":{"type":"Point","coordinates":[85.14,25.61]}},{"type":"Feature","properties":{"id":"kalinga","name":"Kalinga (Dhauli) — the war of 261 BC"},"geometry":{"type":"Point","coordinates":[85.84,20.19]}},{"type":"Feature","properties":{"id":"taxila-m","name":"Taxila — NW provincial capital, trade gateway"},"geometry":{"type":"Point","coordinates":[72.79,33.74]}},{"type":"Feature","properties":{"id":"sanchi","name":"Sanchi — Ashokan stupa"},"geometry":{"type":"Point","coordinates":[77.74,23.48]}}]},"style":{"color":"#b3261e","weight":2,"fillColor":"#b3261e","fillOpacity":0.9,"shadow":true},"defaultOn":false,"labelKey":"name"}],"facts":[{"id":"f1","text":"The 16 Mahajanapadas are listed in Buddhist and Jain literature; the period is called the Second Urbanisation, and silver/copper punch-marked coins appear. States were of two kinds: monarchical and republican. Vajji (Vaishali) was the most important republic; the Lichchhavis of Vaishali are called the first republic.","linkedLayerId":"mahajanapadas"},{"id":"f2","text":"The real contest was among four: Magadha, Kosala, Vatsa, and Avanti. Magadha (capital Rajgir) won — founded by Brihadratha/Jarasandha, its growth began under the Haryanka dynasty, expanded under the Shishunagas and Nandas, and peaked under the Mauryas.","linkedLayerId":"mahajanapadas","linkedFeatureId":"magadha"},{"id":"f3","text":"Haryanka kings to remember: Bimbisara (matrimonial alliances, annexed Anga), Ajatashatru (war with Vajji, first Buddhist council patronage), Udayin (founded Pataliputra at the Ganga–Son confluence — moving the capital from hill-ringed Rajgir to the river highway).","linkedLayerId":"key-sites"},{"id":"f4","text":"The Nandas (344–323 BC) under Dhanananda were fabulously rich and unpopular — the empire Alexander’s soldiers refused to face. Chandragupta Maurya (324/321–297 BC), guided by Kautilya, overthrew them, then defeated Seleucus Nicator, gaining territories up to the Hindu Kush."},{"id":"f5","text":"Ashoka (273–232 BC) ruled nearly the whole subcontinent except the extreme south — including Afghanistan, Baluchistan, Kashmir and the Nepal valleys. The Kalinga War (261 BC, 9th regnal year) converted him: from Bherighosha (drum of war) to Dhammaghosha (drum of righteousness). He embraced Buddhism under Upagupta and sent Mahendra and Sanghamitra to Ceylon with a Bodhi sapling.","linkedLayerId":"key-sites","linkedFeatureId":"kalinga"},{"id":"f6","text":"Edicts cheat-sheet: Major Rock Edict XIII describes the Kalinga victory and names five Greek kings (Antiochus, Ptolemy, Magas, Antigonus, Alexander of Epirus); Edict IV = Dhammaghosha over Bherighosha; Edict II mentions the Pandyas, Cholas and Keralaputras plus medical care for humans and animals; Pillar Edict VII sums up Ashoka’s Dhamma work."},{"id":"f7","text":"Ashoka’s Dhamma was not a sect — it was a civic code: respect elders, mercy to slaves and servants, truth, non-violence, tolerance of all sects. Dhamma Mahamatras were a special cadre appointed to spread it (Rock Edict V)."}],"events":[{"id":"e1","date":"-0600","label":"16 states","description":"6th century BC: sixteen Mahajanapadas contest north India. Second urbanisation; punch-marked coins.","showLayers":["mahajanapadas"],"hideLayers":["maurya-extent","key-sites"],"view":{"center":[25.5,80],"zoom":5}},{"id":"e2","date":"-0544","label":"Haryanka rise","description":"Bimbisara and Ajatashatru make Magadha supreme among the four great rivals (Kosala, Vatsa, Avanti fall in line). Udayin founds Pataliputra.","showLayers":["mahajanapadas","key-sites"],"hideLayers":["maurya-extent"],"view":{"center":[25.4,85.2],"zoom":7}},{"id":"e3","date":"-0321","label":"Chandragupta","description":"Chandragupta Maurya, with Kautilya, topples Dhanananda; later defeats Seleucus Nicator and takes the northwest.","showLayers":["key-sites","maurya-extent"],"hideLayers":["mahajanapadas"],"view":{"center":[27,78],"zoom":5}},{"id":"e4","date":"-0261","label":"Kalinga War","description":"Ashoka’s 9th regnal year. The bloodbath at Kalinga turns conquest into Dhamma — Bherighosha to Dhammaghosha (Rock Edict XIII).","showLayers":["maurya-extent","key-sites"],"hideLayers":["mahajanapadas"],"view":{"center":[20.2,85.8],"zoom":7}},{"id":"e5","date":"-0185","label":"Dynasty ends","description":"The last Maurya, Brihadratha, is assassinated by his general Pushyamitra Shunga. The first pan-Indian empire dissolves.","showLayers":["maurya-extent"],"hideLayers":["mahajanapadas"],"view":{"center":[24.5,81],"zoom":5}}],"quiz":[{"id":"q1","type":"mcq","question":"Which four Mahajanapadas fought the final struggle for supremacy in the 6th–4th centuries BC?","options":["Kashi, Anga, Kuru, Panchala","Magadha, Kosala, Vatsa, Avanti","Gandhara, Kamboja, Matsya, Chedi","Vajji, Malla, Shurasena, Asmaka"],"answerIndex":1,"explanation":"Magadha vs Kosala vs Vatsa vs Avanti — Magadha emerged the most powerful and prosperous kingdom of north India, absorbing the rest."},{"id":"q2","type":"map_click","question":"Click Vaishali — seat of the Vajji confederacy, the most important republic (and the Lichchhavis, the “first republic”).","answer":{"lat":25.99,"lng":85.13,"toleranceKm":90},"explanation":"Vaishali, north of the Ganga in Bihar. Note it sits directly across the river from Magadha — which is why Ajatashatru’s wars targeted it."},{"id":"q3","type":"map_click","question":"Click Kalinga (Dhauli) — site of the 261 BC war that changed Ashoka.","answer":{"lat":20.19,"lng":85.84,"toleranceKm":120},"explanation":"Kalinga, on the Odisha coast. Fought in Ashoka’s 9th regnal year; Rock Edict XIII records the horror and the turn to Dhamma."},{"id":"q4","type":"mcq","question":"Which Major Rock Edict mentions Ashoka’s victory over Kalinga AND names five Greek kings?","options":["Edict II","Edict IV","Edict XIII","Pillar Edict VII"],"answerIndex":2,"explanation":"Rock Edict XIII — the Kalinga edict — names Antiochus of Syria, Ptolemy of Egypt, Magas of Cyrene, Antigonus of Macedon and Alexander of Epirus as recipients of Dhamma victory. Edict IV is Dhammaghosha-over-Bherighosha; Edict II mentions southern kingdoms and medical care."},{"id":"q5","type":"mcq","question":"Ashoka embraced Buddhism under the influence of the monk:","options":["Moggaliputta Tissa","Upagupta","Mahendra","Nagasena"],"answerIndex":1,"explanation":"Upagupta. Ashoka then sent his son Mahendra and daughter Sanghamitra to Ceylon as missionaries, carrying a sapling of the Bodhi tree."},{"id":"q6","type":"mcq","question":"The Mauryan empire under Ashoka covered the whole subcontinent EXCEPT:","options":["Afghanistan","Kashmir","The extreme south","Baluchistan"],"answerIndex":2,"explanation":"Only the extreme south (Chola–Pandya country) stayed out — Edict II treats them as friendly neighbours. Afghanistan, Baluchistan, Kashmir and the Nepal valleys were inside."},{"id":"q7","type":"map_click","question":"Click Pataliputra — the capital founded by Udayin at a river confluence.","answer":{"lat":25.61,"lng":85.14,"toleranceKm":80},"explanation":"Pataliputra (Patna), at the Ganga–Son confluence. Udayin moved the capital here from hill-ringed Rajgir — rivers beat hills once an empire needs highways."},{"id":"q8","type":"mcq","question":"Punch-marked coins of the Mahajanapada era were made of:","options":["Gold and silver","Silver and copper","Copper and iron","Only gold"],"answerIndex":1,"explanation":"Silver and copper punch-marked coins mark the second urbanisation — India’s first true money economy."}]},"position":13,"hash":"3676e4ac666719d070fe56b96ddc4ee329cb4cce09f6c28b07384c7ab8d7f0a1"},{"body":{"id":"buddhism-jainism","subject":"history","unit":"Ancient","tags":["magadha","rajgir","pataliputra","vaishali","varanasi","bihar","ganga"],"title":"Buddhism & Jainism","summary":"Buddha’s life-map, the four councils, Mahavira and the Jain sites.","focus":"Buddha’s biography is eight pins on one small map — and every Buddhist council sits on the Magadha–Vaishali circuit you already know from the Mahajanapadas chapter. Same geography, new religion.","view":{"center":[25.8,84],"zoom":6},"basemap":"natgeo","theme":{"accent":"#8f4f9f","mapBg":"#f5eff7"},"layers":[{"id":"buddha-sites","name":"Buddha’s life sites","description":"Born → enlightened → first sermon → died.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"lumbini","name":"Lumbini (Nepal) — BORN 563 BC, Shakya clan of Kapilavastu"},"geometry":{"type":"Point","coordinates":[83.28,27.47]}},{"type":"Feature","properties":{"id":"bodhgaya","name":"Bodh Gaya — ENLIGHTENMENT at 35, under a pipal tree on the Phalgu"},"geometry":{"type":"Point","coordinates":[84.99,24.7]}},{"type":"Feature","properties":{"id":"sarnath","name":"Sarnath (near Varanasi) — FIRST SERMON: Dharma-chakra-pravartana"},"geometry":{"type":"Point","coordinates":[83.02,25.38]}},{"type":"Feature","properties":{"id":"kushinagar","name":"Kushinagar (UP) — DIED 483 BC at 80, under a sal tree (Mahaparinirvana)"},"geometry":{"type":"Point","coordinates":[83.89,26.74]}},{"type":"Feature","properties":{"id":"shravasti-b","name":"Shravasti — most rainy-season retreats (Jetavana)"},"geometry":{"type":"Point","coordinates":[82.03,27.52]}},{"type":"Feature","properties":{"id":"rajgir-b","name":"Rajgir — Griddhakuta hill sermons; 1st Council 483 BC"},"geometry":{"type":"Point","coordinates":[85.42,25.03]}}]},"style":{"color":"#8f4f9f","weight":2,"fillColor":"#8f4f9f","markerRadius":7,"glow":true},"defaultOn":true,"labelKey":"name"},{"id":"councils","name":"Four Buddhist councils","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"c1","name":"1st Council, 483 BC — Rajgir, under Ajatashatru (Haryanka)"},"geometry":{"type":"Point","coordinates":[85.42,25.03]}},{"type":"Feature","properties":{"id":"c2","name":"2nd Council, 383 BC — Vaishali, under Kalashoka (Shishunaga); president Sabakami"},"geometry":{"type":"Point","coordinates":[85.13,25.99]}},{"type":"Feature","properties":{"id":"c3","name":"3rd Council, 250 BC — Pataliputra, under Ashoka (Maurya)"},"geometry":{"type":"Point","coordinates":[85.14,25.61]}},{"type":"Feature","properties":{"id":"c4","name":"4th Council, AD 72 — Kashmir, under Kanishka (Kushan); Mahayana finalized"},"geometry":{"type":"Point","coordinates":[74.8,34.1]}}]},"style":{"color":"#b0632c","weight":2,"fillColor":"#b0632c","markerRadius":6},"defaultOn":false,"labelKey":"name"},{"id":"jain-sites","name":"Jain sites","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"kundagrama","name":"Kundagrama, near Vaishali — Mahavira’s birthplace (540 BC)"},"geometry":{"type":"Point","coordinates":[85.13,26.02]}},{"type":"Feature","properties":{"id":"pava","name":"Pava / Pavapuri — first sermon; Mahavira died here (468 BC)"},"geometry":{"type":"Point","coordinates":[85.55,25.09]}},{"type":"Feature","properties":{"id":"parasnath","name":"Parasnath Hill (Sammed Shikhar) — 20 tirthankaras attained moksha"},"geometry":{"type":"Point","coordinates":[86.13,23.96]}},{"type":"Feature","properties":{"id":"shravanabelagola","name":"Shravanabelagola (Karnataka) — Chandragupta Maurya’s last days; Bahubali"},"geometry":{"type":"Point","coordinates":[76.49,12.86]}}]},"style":{"color":"#2e7d5b","weight":2,"fillColor":"#2e7d5b","markerRadius":6},"defaultOn":false,"labelKey":"name"}],"facts":[{"id":"f1","text":"Gautama Buddha — also Siddhartha, Shakyamuni, Tathagata — born 563 BC at LUMBINI (Nepal) in the Shakya Kshatriya clan of Kapilavastu. Father Suddhodhana, mother Mahamaya (a Koshalan princess); raised by his aunt Mahaprajapati Gautami; wife Yashodhara, son Rahul; teachers Alara Kalama and Udraka Ramaputra; horse Kanthaka.","linkedLayerId":"buddha-sites","linkedFeatureId":"lumbini"},{"id":"f2","text":"The four sights (old man, sick man, corpse, ascetic) drove him out at 29. Enlightenment at 35 at BODH GAYA, under a pipal tree on the banks of the Phalgu, on the 49th day of meditation. First sermon at SARNATH near Varanasi to five disciples — the Dharma-chakra-pravartana, “turning the wheel of law”. Died 483 BC at 80 at KUSHINAGAR (UP) under a sal tree.","linkedLayerId":"buddha-sites"},{"id":"f3","text":"Core doctrine: Buddhism recognizes neither God nor soul (atma). FOUR NOBLE TRUTHS: the world is full of sorrow; desire causes it; conquering desire removes it (nirvana); the way is the EIGHTFOLD PATH (Ashtangika Marga: right observation, speech, determination, livelihood, memory, action, exercise, meditation). TRIRATNA: Buddha, Dhamma, Sangha."},{"id":"f4","text":"Four councils — memorize ruler + dynasty + place: 483 BC Rajgir (Ajatashatru, Haryanka); 383 BC Vaishali (Kalashoka, Shishunaga; president Sabakami); 250 BC Pataliputra (Ashoka, Maurya); AD 72 Kashmir (Kanishka, Kushan) — where the MAHAYANA doctrine was finalized. Literature: the Tripitakas, in PALI.","linkedLayerId":"councils"},{"id":"f5","text":"Jainism: founded by Rishabhanath (1st tirthankara); 23rd Parshvanath; 24th VARDHAMANA MAHAVIRA — “Jina”, the conqueror — born near Vaishali (Kundagrama), father Siddhartha, mother Trishala; attained Kaivalya (supreme knowledge) at 42; first sermon at PAVA, where he also died (468 BC).","linkedLayerId":"jain-sites"},{"id":"f6","text":"Jain doctrine: Triratna = right faith, right knowledge, right conduct. FIVE VOWS: ahimsa, satya (non-lying), asteya (non-stealing), aparigraha (non-possession), brahmacharya — the fifth added by Mahavira to Parshvanath’s four. Sects after the Magadha famine: SVETAMBARA (white-clad, Sthulabhadra) and DIGAMBARA (sky-clad, Bhadrabahu — who took Chandragupta Maurya south to Shravanabelagola).","linkedLayerId":"jain-sites"},{"id":"f7","text":"Why here, why now? Both faiths rose in the 6th-century-BC Mahajanapada world — iron-age surplus, new cities, trade wealth, and Kshatriya resentment of Brahmana ritual cost. Both founders were Kshatriyas from the same Magadha–Vaishali region — the identical geography of the Rise-of-Magadha chapter."}],"events":[{"id":"e1","date":"-0563","label":"Buddha born","description":"Lumbini, in the Shakya clan of Kapilavastu.","showLayers":["buddha-sites"],"view":{"center":[27.47,83.28],"zoom":7}},{"id":"e2","date":"-0540","label":"Mahavira born","description":"Kundagrama near Vaishali — the Jain 24th tirthankara.","showLayers":["jain-sites"],"view":{"center":[26.02,85.13],"zoom":7}},{"id":"e3","date":"-0528","label":"Enlightenment","description":"Bodh Gaya, under the pipal tree by the Phalgu; then the first sermon at Sarnath.","showLayers":["buddha-sites"],"view":{"center":[25,84],"zoom":7}},{"id":"e4","date":"-0483","label":"Mahaparinirvana","description":"Buddha dies at Kushinagar; the First Council meets the same year at Rajgir under Ajatashatru.","showLayers":["buddha-sites","councils"],"view":{"center":[25.8,84.5],"zoom":6}},{"id":"e5","date":"0072","label":"4th Council","description":"Kanishka’s council in Kashmir finalizes Mahayana Buddhism — the faith now travels the Silk Road.","showLayers":["councils"],"view":{"center":[34.1,74.8],"zoom":6}}],"quiz":[{"id":"q1","type":"map_click","question":"Click Sarnath — where Buddha preached the first sermon (Dharma-chakra-pravartana).","answer":{"lat":25.38,"lng":83.02,"toleranceKm":80},"explanation":"Sarnath, just outside Varanasi. Birth Lumbini → enlightenment Bodh Gaya → first sermon Sarnath → death Kushinagar: the four-pin biography."},{"id":"q2","type":"mcq","question":"Match the Buddhist council to its patron — which pair is WRONG?","options":["1st, Rajgir — Ajatashatru","2nd, Vaishali — Kalashoka","3rd, Pataliputra — Kanishka","4th, Kashmir — Kanishka"],"answerIndex":2,"explanation":"The 3rd council (250 BC, Pataliputra) was under ASHOKA. Kanishka patronized the 4th (AD 72, Kashmir), where Mahayana doctrine was finalized."},{"id":"q3","type":"mcq","question":"Buddha attained enlightenment on the banks of which river?","options":["Ganga","Phalgu","Son","Gandak"],"answerIndex":1,"explanation":"The Phalgu at Bodh Gaya, under a pipal tree, on the 49th day of meditation, aged 35."},{"id":"q4","type":"mcq","question":"The fifth vow (brahmacharya) was added to Jainism’s four by:","options":["Rishabhanath","Parshvanath","Mahavira","Bhadrabahu"],"answerIndex":2,"explanation":"Parshvanath (23rd tirthankara) taught four vows; Mahavira added celibacy as the fifth. Triratna of Jainism: right faith, knowledge, conduct."},{"id":"q5","type":"map_click","question":"Click Pavapuri — where Mahavira preached his first sermon and died.","answer":{"lat":25.09,"lng":85.55,"toleranceKm":90},"explanation":"Pava/Pavapuri in Bihar, close to Rajgir. Mahavira died here in 468 BC — the Jain and Buddhist geographies almost perfectly overlap."},{"id":"q6","type":"mcq","question":"The Svetambara and Digambara sects of Jainism are associated respectively with:","options":["Bhadrabahu and Sthulabhadra","Sthulabhadra and Bhadrabahu","Mahavira and Parshvanath","Rishabhanath and Mahavira"],"answerIndex":1,"explanation":"Svetambara (white-clad) — Sthulabhadra; Digambara (unclad) — Bhadrabahu, who migrated south with Chandragupta Maurya to Shravanabelagola during the Magadha famine."},{"id":"q7","type":"mcq","question":"Early Buddhist literature (the Tripitakas) was written mostly in:","options":["Sanskrit","Prakrit","Pali","Magadhi"],"answerIndex":2,"explanation":"Pali — the people’s tongue, part of why Buddhism spread fast. Tri-pitaka = three baskets: Vinaya, Sutta, Abhidhamma."},{"id":"q8","type":"mcq","question":"Which is NOT one of the Four Noble Truths?","options":["The world is full of sorrows","Desire is the cause of sorrow","Sorrow ends when desire is conquered","God must be worshipped to end sorrow"],"answerIndex":3,"explanation":"Buddhism does not recognize God (or the soul). The fourth truth is the PATH — the eightfold Ashtangika Marga — not worship."}]},"position":14,"hash":"bffa072a53a9d018a0d8c35236ab37f68a4a7b213b75266da67687ca64032278"},{"body":{"id":"medieval-gateway-battles","subject":"history","unit":"Medieval","tags":["delhi","panipat","punjab","gujarat","somnath","aravalli","khyber","agra"],"title":"Medieval India: Gateway Battles","summary":"712–1576: Sindh, Somnath, Tarain, Panipat, Khanwa, Haldighati — one corridor, five centuries.","focus":"The Delhi Sultanate was born on the battlefield of Tarain (1192) and ended a few miles away at Panipat (1526). Learn the corridor once and every medieval battle question becomes a map question.","view":{"center":[28,76],"zoom":5},"basemap":"paper","theme":{"accent":"#7a1f2b","mapBg":"#f7efe6"},"layers":[{"id":"corridor","name":"NW invasion corridor","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"nw-corridor","name":"Invasion corridor: Ghazni → Khyber → Punjab → Delhi"},"geometry":{"type":"LineString","coordinates":[[68.42,33.55],[71.08,34.08],[73.05,33.6],[74.35,31.55],[75.86,30.9],[76.94,29.79],[76.97,29.39],[77.21,28.61]]}}]},"style":{"color":"#7a1f2b","weight":3,"dashArray":"8 5","flow":true},"defaultOn":true,"labelKey":"name"},{"id":"battles","name":"Battle sites","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"sindh-712","name":"712: Muhammad-bin-Qasim defeats Dahir (Battle of Rewar, Sindh)"},"geometry":{"type":"Point","coordinates":[68.9,27.72]}},{"type":"Feature","properties":{"id":"somnath-1025","name":"1025: Mahmud of Ghazni sacks Somnath (Kathiawar coast)"},"geometry":{"type":"Point","coordinates":[70.4,20.89]}},{"type":"Feature","properties":{"id":"tarain","name":"1191 & 1192: Battles of Tarain — Prithviraj vs Muhammad Ghori"},"geometry":{"type":"Point","coordinates":[76.94,29.79]}},{"type":"Feature","properties":{"id":"panipat-1","name":"21 Apr 1526: First Panipat — Babur kills Ibrahim Lodi"},"geometry":{"type":"Point","coordinates":[76.97,29.39]}},{"type":"Feature","properties":{"id":"khanwa","name":"1527: Khanwa — Babur defeats Rana Sanga"},"geometry":{"type":"Point","coordinates":[77.42,27.13]}},{"type":"Feature","properties":{"id":"chausa","name":"1539: Chausa — Sher Khan destroys Humayun’s army"},"geometry":{"type":"Point","coordinates":[83.9,25.51]}},{"type":"Feature","properties":{"id":"kanauj-1540","name":"1540: Bilgram/Kanauj — Humayun exiled; Sur Empire begins"},"geometry":{"type":"Point","coordinates":[79.92,27.05]}},{"type":"Feature","properties":{"id":"panipat-2","name":"1556: Second Panipat — Bairam Khan (for Akbar) vs Hemu"},"geometry":{"type":"Point","coordinates":[76.97,29.42]}},{"type":"Feature","properties":{"id":"haldighati","name":"1576: Haldighati — Man Singh (Mughal) vs Rana Pratap"},"geometry":{"type":"Point","coordinates":[73.69,24.89]}},{"type":"Feature","properties":{"id":"chittor","name":"1568: Fall of Chittor — key to central Rajasthan (Jaimal & Patta)"},"geometry":{"type":"Point","coordinates":[74.63,24.88]}}]},"style":{"color":"#7a1f2b","weight":2,"fillColor":"#b3261e","fillOpacity":0.9,"shadow":true},"defaultOn":true,"labelKey":"name"},{"id":"power-centres","name":"Power centres","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"kannauj","name":"Kannauj — prize of the Tripartite Struggle (Pratiharas / Palas / Rashtrakutas)"},"geometry":{"type":"Point","coordinates":[79.92,27.05]}},{"type":"Feature","properties":{"id":"delhi-sultanate","name":"Delhi — seat of Sultanate (1206–1526) & Mughals"},"geometry":{"type":"Point","coordinates":[77.21,28.61]}},{"type":"Feature","properties":{"id":"ghazni-city","name":"Ghazni — Mahmud’s base (17 raids, 1000–1027)"},"geometry":{"type":"Point","coordinates":[68.42,33.55]}},{"type":"Feature","properties":{"id":"sasaram","name":"Sasaram — Sher Shah Suri’s capital/tomb (Sur Empire)"},"geometry":{"type":"Point","coordinates":[84.03,24.95]}}]},"style":{"color":"#3b2a6b","weight":2,"fillColor":"#5b46a8","fillOpacity":0.9,"shadow":true},"defaultOn":false,"labelKey":"name"}],"facts":[{"id":"f1","text":"Before the Turks: the Tripartite Struggle. Pratiharas (west), Palas (Bengal) and Rashtrakutas (Deccan) fought a three-way, century-long contest for Kannauj — the symbolic capital of north India. All three exhausted themselves, opening the door to invaders.","linkedLayerId":"power-centres","linkedFeatureId":"kannauj"},{"id":"f2","text":"712 AD: Al-Hajjaj, governor of Iraq, sent Muhammad-bin-Qasim, who defeated Dahir of Sindh at the Battle of Rewar. Qasim called Multan “the City of Gold”. His end was grim — recalled and tortured to death after Hajjaj’s fall.","linkedLayerId":"battles","linkedFeatureId":"sindh-712"},{"id":"f3","text":"Mahmud of Ghazni raided India 17 times (1000–1027) for plunder, not empire — climaxing with the sack of the Somnath temple on the Kathiawar coast in 1025. Contrast with Muhammad of Ghori, who came to STAY.","linkedLayerId":"battles","linkedFeatureId":"somnath-1025"},{"id":"f4","text":"Tarain, the double battle: 1191 — Prithviraj Chauhan defeats Ghori. 1192 — Ghori returns and crushes the combined Rajput forces. Turkish rule in India begins with the Second Battle of Tarain; Ghori’s slave Qutb-ud-din Aibak founds the Sultanate in 1206. (Iltutmish later won his own battle of Tarain, c. 1215, against Yaldauz.)","linkedLayerId":"battles","linkedFeatureId":"tarain"},{"id":"f5","text":"Sultanate = five dynasties: Slave/Mamluk (1206–90), Khalji (1290–1320), Tughlaq (1320–14), Sayyid (1414–51), Lodi (1451–1526). It ended when Babur defeated and killed Ibrahim Lodi at the FIRST Battle of Panipat, 21 April 1526 — born at Tarain, dead at Panipat, a few miles apart."},{"id":"f6","text":"Babur’s follow-up: Khanwa (1527) against Rana Sanga of Mewar — same tactics as Panipat (artillery + tulughma flanking) — secured the Mughal foothold against the Rajput confederacy.","linkedLayerId":"battles","linkedFeatureId":"khanwa"},{"id":"f7","text":"The Sur interruption: Sher Khan smashed Humayun at Chausa (1539) and again at Bilgram/Kanauj (1540), exiling him 15 years. Sher Shah Suri built the Sur Empire from Sasaram — and the Grand Trunk Road. Humayun returned in 1555, then died in 1556 falling down his library stairs.","linkedLayerId":"battles","linkedFeatureId":"chausa"},{"id":"f8","text":"Second Panipat (1556): 13-year-old Akbar’s regent Bairam Khan defeats Hemu Vikramaditya, wazir of Adil Shah, leading the Afghan forces. Akbar had been crowned at Kalanaur the same year. The Mughal restoration is sealed on the SAME battlefield as 1526.","linkedLayerId":"battles","linkedFeatureId":"panipat-2"},{"id":"f9","text":"Akbar in Rajasthan: Chittor — “the key to central Rajasthan” — fell in 1568 after a 6-month siege (Jaimal and Patta commanded; Udai Singh withdrew to the hills). Ranthambhore and Kalinjar followed. At Haldighati (1576), Man Singh’s Mughal army severely defeated Rana Pratap of Mewar — who nonetheless fought on from the hills.","linkedLayerId":"battles","linkedFeatureId":"haldighati"}],"events":[{"id":"e1","date":"0712","label":"Sindh falls","description":"Muhammad-bin-Qasim defeats Dahir at Rewar. The Arab conquest stays confined to Sindh — but the door is marked.","showLayers":["battles"],"hideLayers":["power-centres"],"view":{"center":[27.5,68.9],"zoom":6}},{"id":"e2","date":"1025","label":"Somnath sacked","description":"Mahmud of Ghazni’s 16th raid reaches the Somnath temple on the Kathiawar coast. Plunder, not conquest.","showLayers":["battles","corridor"],"view":{"center":[21.5,71],"zoom":6}},{"id":"e3","date":"1192","label":"Second Tarain","description":"Ghori crushes Prithviraj’s Rajput coalition. Turkish rule begins; Aibak will found the Sultanate in 1206.","showLayers":["battles","corridor"],"view":{"center":[29.5,76.9],"zoom":7}},{"id":"e4","date":"1526-04-21","label":"First Panipat","description":"Babur’s guns and tulughma destroy Ibrahim Lodi. The Sultanate — born at Tarain — dies a few miles away.","showLayers":["battles","corridor"],"view":{"center":[29.4,77],"zoom":7}},{"id":"e5","date":"1527","label":"Khanwa","description":"Babur defeats Rana Sanga’s Rajput confederacy using the Panipat playbook.","showLayers":["battles"],"view":{"center":[27.1,77.4],"zoom":7}},{"id":"e6","date":"1540","label":"Sur Empire","description":"After Chausa (1539), Sher Khan finishes Humayun at Bilgram/Kanauj. Sher Shah rules from Sasaram; Humayun wanders 15 years.","showLayers":["battles","power-centres"],"view":{"center":[26,82],"zoom":6}},{"id":"e7","date":"1556","label":"Second Panipat","description":"Bairam Khan, regent for 13-year-old Akbar, defeats Hemu. Mughal power is restored on the same field as 1526.","showLayers":["battles","corridor"],"view":{"center":[29.4,77],"zoom":7}},{"id":"e8","date":"1576","label":"Haldighati","description":"Man Singh defeats Rana Pratap in the Aravalli pass. Mewar resists from the hills, but Rajasthan’s plains are Mughal.","showLayers":["battles"],"view":{"center":[24.9,73.7],"zoom":8}}],"quiz":[{"id":"q1","type":"mcq","question":"The Delhi Sultanate is said to have been “born at Tarain and buried at Panipat” because:","options":["Both battles were fought against the Rajputs","Turkish rule began with the 2nd Battle of Tarain (1192) and the last Sultan, Ibrahim Lodi, was killed at the 1st Battle of Panipat (1526) — fields only a few miles apart","Both towns were Sultanate capitals","Both battles were won by artillery"],"answerIndex":1,"explanation":"Ghori’s 1192 victory at Tarain opened Turkish rule; Babur’s 1526 victory at Panipat killed Ibrahim Lodi and ended it. The two battlefields sit within a short march of each other on the same corridor to Delhi."},{"id":"q2","type":"map_click","question":"Click Panipat — the field of the 1526 and 1556 battles.","answer":{"lat":29.39,"lng":76.97,"toleranceKm":70},"explanation":"Panipat guards the last flat approach to Delhi — which is why decisive battles keep landing here (1526 Babur–Lodi, 1556 Bairam Khan–Hemu, and 1761 later still)."},{"id":"q3","type":"mcq","question":"Who represented 13-year-old Akbar at the Second Battle of Panipat (1556), and against whom?","options":["Man Singh, against Rana Pratap","Bairam Khan, against Hemu Vikramaditya","Todar Mal, against Sher Khan","Abul Fazl, against Adil Shah"],"answerIndex":1,"explanation":"Regent Bairam Khan commanded for Akbar against Hemu, the wazir of Adil Shah leading the Afghan forces. Akbar had been crowned at Kalanaur in 1556 aged 13 years 4 months."},{"id":"q4","type":"map_click","question":"Click Somnath — the temple Mahmud of Ghazni sacked in 1025 AD.","answer":{"lat":20.89,"lng":70.4,"toleranceKm":120},"explanation":"Somnath stands on the Kathiawar (Saurashtra) coast of Gujarat. Ghazni raided 17 times for plunder — he never tried to rule India, unlike Ghori."},{"id":"q5","type":"mcq","question":"Put Humayun’s disasters in order:","options":["Kanauj (1540) → Chausa (1539)","Chausa (1539) → Bilgram/Kanauj (1540) → 15-year exile","Khanwa (1527) → Chausa (1539)","Panipat (1526) → Kanauj (1540)"],"answerIndex":1,"explanation":"Sher Khan destroyed Humayun’s army at Chausa in 1539, then finished him at Bilgram (Battle of Kanauj/the Ganges) in 1540 — Humayun lost his kingdom and wandered 15 years while the Sur Empire ruled from Sasaram."},{"id":"q6","type":"mcq","question":"Muhammad-bin-Qasim (712 AD) defeated which ruler, at which battle?","options":["Prithviraj at Tarain","Dahir of Sindh at the Battle of Rewar","Jaipal at Waihind","Rana Sanga at Khanwa"],"answerIndex":1,"explanation":"Qasim, sent by Al-Hajjaj the governor of Iraq, beat Dahir at Rewar and took Sindh; he called Multan “the City of Gold”. He was later recalled and tortured to death."},{"id":"q7","type":"map_click","question":"Click Haldighati — the 1576 pass battle between Man Singh and Rana Pratap.","answer":{"lat":24.89,"lng":73.69,"toleranceKm":90},"explanation":"Haldighati is an Aravalli pass near Udaipur in Mewar. Rana Pratap was severely defeated but never submitted, fighting on from the hills."},{"id":"q8","type":"mcq","question":"The Tripartite Struggle was fought for control of:","options":["Delhi","Ujjain","Kannauj","Pataliputra"],"answerIndex":2,"explanation":"Kannauj — contested for over a century by the Gurjara-Pratiharas, the Palas of Bengal, and the Rashtrakutas of the Deccan. Their mutual exhaustion cleared the stage for the Turkish invasions."},{"id":"q9","type":"mcq","question":"Which fort, considered “the key to central Rajasthan”, fell to Akbar in 1568 after a six-month siege defended by Jaimal and Patta?","options":["Ranthambhore","Chittor","Kalinjar","Mehrangarh"],"answerIndex":1,"explanation":"Chittor. Rana Udai Singh retired to the hills leaving Jaimal and Patta in command. Ranthambhore (“the most powerful fortress in Rajasthan”) and Kalinjar fell soon after."}]},"position":15,"hash":"cfd10dcaddb03487bde7140e4843f80650f66d44a03b21f12217eb12eb937c40"},{"body":{"id":"delhi-sultanate","subject":"history","unit":"Medieval","tags":["delhi","punjab","deccan","khyber","agra","panipat"],"title":"Delhi Sultanate: Five Dynasties","summary":"Slave → Khalji → Tughlaq → Sayyid → Lodi — rulers, reforms, experiments.","focus":"One city, five dynasties, 320 years (1206–1526). The Sultanate’s story is a set of experiments radiating from Delhi — Alauddin’s market control, Tughlaq’s capital shift and token currency — and every experiment snaps back to Delhi.","view":{"center":[26,76.5],"zoom":5},"basemap":"natgeo","theme":{"accent":"#5b46a8","mapBg":"#f1eef8"},"layers":[{"id":"sultanate-sites","name":"Capitals & key cities","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"delhi-s","name":"Delhi — seat of all five dynasties; Qutub Minar begun by Aibak, finished by Iltutmish"},"geometry":{"type":"Point","coordinates":[77.23,28.65]}},{"type":"Feature","properties":{"id":"lahore-s","name":"Lahore — Aibak’s first capital; he died here playing chaugan (1210)"},"geometry":{"type":"Point","coordinates":[74.35,31.55]}},{"type":"Feature","properties":{"id":"daulatabad","name":"Daulatabad (Devagiri) — Muhammad-bin-Tughlaq’s capital experiment, 1327"},"geometry":{"type":"Point","coordinates":[75.21,19.94]}},{"type":"Feature","properties":{"id":"multan-s","name":"Multan — frontier province against the Mongols"},"geometry":{"type":"Point","coordinates":[71.47,30.2]}},{"type":"Feature","properties":{"id":"agra-s","name":"Agra — founded by Sikandar Lodi (1504) as his capital"},"geometry":{"type":"Point","coordinates":[78.01,27.18]}}]},"style":{"color":"#5b46a8","weight":2,"fillColor":"#5b46a8","markerRadius":7,"glow":true},"defaultOn":true,"labelKey":"name"},{"id":"capital-shift","name":"MBT’s capital shift (1327)","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"shift-line","name":"1327: Delhi → Daulatabad (and back) — 1,500+ km of forced march"},"geometry":{"type":"LineString","coordinates":[[77.23,28.65],[76.8,26.9],[76.2,24.8],[75.8,22.5],[75.4,21],[75.21,19.94]]}}]},"style":{"color":"#b0632c","weight":3,"dashArray":"2 8","flow":true},"defaultOn":true,"labelKey":"name"},{"id":"timur-path","name":"Timur’s invasion (1398)","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"timur-line","name":"1398: Timur — Central Asia → Punjab → sack of Delhi (death blow to the Tughlaqs)"},"geometry":{"type":"LineString","coordinates":[[69.2,34.5],[71.5,33.5],[73.1,32.5],[74.35,31.55],[75.9,30.2],[77.23,28.65]]}}]},"style":{"color":"#b3261e","weight":3,"dashArray":"8 5","flow":true},"defaultOn":false,"labelKey":"name"}],"facts":[{"id":"f1","text":"The five dynasties in order: SLAVE/Mamluk (1206–90), KHALJI (1290–1320), TUGHLAQ (1320–1414), SAYYID (1414–51), LODI (1451–1526). Mnemonic: “Slaves Keep The Sultan’s Law”."},{"id":"f2","text":"Qutb-ud-din AIBAK (1206–10): Ghori’s Turkish slave, governor of his Indian lands, founder of the Slave dynasty; called “Lakh Baksh” (giver of lakhs) for generosity; began the Qutub Minar (named for the sufi Qutbuddin Bakhtiyar Kaki); died at Lahore playing chaugan (horse polo). His incapable son Aram Shah lasted eight months.","linkedLayerId":"sultanate-sites","linkedFeatureId":"lahore-s"},{"id":"f3","text":"ILTUTMISH (1211–36): the real consolidator — completed the Qutub Minar, introduced the silver TANKA and copper JITAL, organized the CHAHALGANI (corps of forty Turkish nobles), and saved India from Chingiz Khan by refusing refuge to the Khwarizm prince (1221). He nominated his daughter RAZIA (1236–40) — the first and only woman on the Delhi throne; her rise fell foul of the Forty."},{"id":"f4","text":"BALBAN (1266–87): broke the Chahalgani, ruled by “blood and iron”, enforced SIJDA (prostration) and PAIBOS (kissing the royal feet), introduced the Persian Nauroz festival, ran an efficient spy network, and championed Turkish-only nobility — theory of kingship: the Sultan as Zil-e-Ilahi, shadow of God."},{"id":"f5","text":"ALAUDDIN KHALJI (1296–1316): first Sultan with a large PERMANENT standing army paid in cash; introduced DAGH (horse branding) and HULIYA (soldier descriptive rolls); ruthless MARKET CONTROL — fixed prices, separate markets, the shahna-i-mandi inspector; land revenue raised to half the produce in the doab. His general Malik Kafur raided the deep south (Devagiri, Warangal, Madurai)."},{"id":"f6","text":"MUHAMMAD-BIN-TUGHLAQ (1325–51): the Sultanate’s great experimenter. (1) Capital transfer 1327: Delhi → Devagiri, renamed DAULATABAD, to control the south — the whole population force-marched 1,500+ km; water scarcity forced the return two years later. (2) TOKEN CURRENCY 1329: copper coins valued as silver, on the Chinese paper-money model — forgery exploded, the treasury emptied redeeming them. Brilliant ideas, broken execution.","linkedLayerId":"capital-shift"},{"id":"f7","text":"FIROZ SHAH TUGHLAQ (1351–88): the builder-welfare Sultan — canals, new towns (Firozabad, Hisar), employment bureau, Diwan-i-Khairat (charity); but he revived the jagir system and made the army hereditary, weakening the centre. After him: TIMUR, 1398 — the Chagatai Mongol sacked Delhi for three days against barely any opposition, and his withdrawal in 1399 was the death blow to the Tughlaqs.","linkedLayerId":"timur-path"},{"id":"f8","text":"Endgame: the SAYYIDS (1414–51, Khizr Khan — Timur’s nominee) ruled a shrunken Delhi; the LODIS (Afghan, not Turkish) followed — Bahlol (1451–89), SIKANDAR (1489–1517, founded AGRA 1504, moved the capital there), and IBRAHIM (1517–26), whose harshness pushed Daulat Khan Lodi to invite Babur. First Battle of Panipat, 21 April 1526 — the Sultanate ends where the Gateway-Battles chapter picks up."}],"events":[{"id":"e1","date":"1206","label":"Aibak","description":"Qutb-ud-din Aibak founds the Slave dynasty — the Delhi Sultanate begins. Capital at Lahore.","showLayers":["sultanate-sites"],"hideLayers":["timur-path"],"view":{"center":[30,75.5],"zoom":6}},{"id":"e2","date":"1236","label":"Razia","description":"Iltutmish’s daughter Razia takes the throne — the only woman Sultan of Delhi. The Forty bring her down by 1240.","view":{"center":[28.65,77.23],"zoom":7}},{"id":"e3","date":"1296","label":"Khalji zenith","description":"Alauddin Khalji: standing army, dagh & huliya, market control; Malik Kafur raids to Madurai.","view":{"center":[24,77],"zoom":5}},{"id":"e4","date":"1327","label":"Capital shift","description":"Muhammad-bin-Tughlaq marches Delhi to Daulatabad — and back. Token currency follows in 1329.","showLayers":["capital-shift","sultanate-sites"],"view":{"center":[24,76],"zoom":5}},{"id":"e5","date":"1398","label":"Timur sacks Delhi","description":"Timur, head of the Chagatai Turks, plunders Delhi for three days — the Tughlaqs never recover.","showLayers":["timur-path"],"view":{"center":[30.5,74],"zoom":5}},{"id":"e6","date":"1526-04-21","label":"Panipat: the end","description":"Ibrahim Lodi falls to Babur at Panipat. Five dynasties, 320 years — done.","hideLayers":["timur-path"],"view":{"center":[29.39,76.97],"zoom":7}}],"quiz":[{"id":"q1","type":"mcq","question":"Arrange the five Sultanate dynasties in order:","options":["Khalji → Slave → Tughlaq → Lodi → Sayyid","Slave → Khalji → Tughlaq → Sayyid → Lodi","Slave → Tughlaq → Khalji → Sayyid → Lodi","Tughlaq → Khalji → Slave → Lodi → Sayyid"],"answerIndex":1,"explanation":"Slave (1206–90) → Khalji (1290–1320) → Tughlaq (1320–1414) → Sayyid (1414–51) → Lodi (1451–1526). “Slaves Keep The Sultan’s Law”."},{"id":"q2","type":"mcq","question":"The silver tanka and copper jital were introduced by:","options":["Aibak","Iltutmish","Balban","Alauddin Khalji"],"answerIndex":1,"explanation":"Iltutmish — also completer of the Qutub Minar, creator of the Chahalgani, and the Sultan who dodged Chingiz Khan in 1221. He nominated Razia as successor."},{"id":"q3","type":"map_click","question":"Click Daulatabad (Devagiri) — Muhammad-bin-Tughlaq’s ill-fated new capital.","answer":{"lat":19.94,"lng":75.21,"toleranceKm":130},"explanation":"Daulatabad sits in the Deccan near Aurangabad — 1,500+ km from Delhi. Chosen to control the south; abandoned within two years for want of water."},{"id":"q4","type":"mcq","question":"Muhammad-bin-Tughlaq’s token currency failed mainly because:","options":["Gold ran out in the treasury","The copper tokens were easy to forge, and people hoarded gold/silver","The Mongols stole the mint","Merchants refused all coins"],"answerIndex":1,"explanation":"Modelled on Kublai Khan’s paper money, the copper tokens were freely forged; when MBT redeemed them all in gold/silver, the treasury emptied. Brilliant idea, broken execution — his signature."},{"id":"q5","type":"mcq","question":"Dagh (branding of horses) and huliya (descriptive rolls of soldiers) were military reforms of:","options":["Balban","Alauddin Khalji","Firoz Shah Tughlaq","Sikandar Lodi"],"answerIndex":1,"explanation":"Alauddin Khalji — paired with the first cash-paid permanent standing army and his famous market-control system (fixed prices, shahna-i-mandi)."},{"id":"q6","type":"mcq","question":"Sijda and paibos (prostration and kissing the royal feet) were court ceremonies enforced by:","options":["Iltutmish","Razia","Balban","Ibrahim Lodi"],"answerIndex":2,"explanation":"Balban — with the Nauroz festival, the spy system, the destruction of the Chahalgani, and the theory of the Sultan as Zil-e-Ilahi (shadow of God)."},{"id":"q7","type":"map_click","question":"Click Agra — founded in 1504 by Sikandar Lodi as his new capital.","answer":{"lat":27.18,"lng":78.01,"toleranceKm":90},"explanation":"Sikandar Lodi moved the capital from Delhi to his new city of Agra — which is why Babur’s Mughals inherited Agra as a power centre."},{"id":"q8","type":"mcq","question":"Timur’s 1398 invasion is significant because it:","options":["Founded the Mughal empire directly","Gave a death blow to the Tughlaq dynasty and left Delhi power shattered","Was repelled by Firoz Shah","Introduced gunpowder to India"],"answerIndex":1,"explanation":"Timur sacked a nearly undefended Delhi for three days and withdrew in 1399. The Tughlaqs collapsed; his nominee Khizr Khan founded the Sayyid dynasty. (Timur’s descendant Babur returned in 1526.)"}]},"position":16,"hash":"9a5c942df22a8c3bace39032ca4b3aa1dc49013e38b9911f0751848aa60c95ce"},{"body":{"id":"medieval-south","subject":"history","unit":"Medieval","tags":["kaveri","krishna","tungabhadra","deccan","hampi","thanjavur","peninsular-plateau","bengal"],"title":"Medieval South: Cholas to Talikota","summary":"Chola navy on the Kaveri, Vijayanagara on the Tungabhadra, Bahmani rivalry.","focus":"The medieval south runs on rivers: Chola power grew from the Kaveri delta and sailed to the Ganga and Srivijaya; Vijayanagara rose on the Tungabhadra; and the Krishna–Tungabhadra doab was the bleeding frontier with the Bahmani sultans — until Talikota, 1565.","view":{"center":[14.5,78.5],"zoom":5},"basemap":"natgeo","theme":{"accent":"#0e7a70","mapBg":"#eaf5f2"},"layers":[{"id":"south-sites","name":"Capitals & battle sites","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"thanjavur","name":"Thanjavur — Chola capital; Rajaraja I’s Brihadesvara temple (1010)"},"geometry":{"type":"Point","coordinates":[79.13,10.79]}},{"type":"Feature","properties":{"id":"gangaikonda","name":"Gangaikondacholapuram — Rajendra I’s victory city after the Ganga campaign"},"geometry":{"type":"Point","coordinates":[79.45,11.21]}},{"type":"Feature","properties":{"id":"hampi","name":"Hampi (Vijayanagara) — capital on the Tungabhadra, founded 1336 by Harihara & Bukka"},"geometry":{"type":"Point","coordinates":[76.47,15.34]}},{"type":"Feature","properties":{"id":"gulbarga","name":"Gulbarga — first Bahmani capital (1347, Alauddin Hasan Bahman Shah)"},"geometry":{"type":"Point","coordinates":[76.83,17.33]}},{"type":"Feature","properties":{"id":"bidar","name":"Bidar — later Bahmani capital; Mahmud Gawan’s madrasa"},"geometry":{"type":"Point","coordinates":[77.52,17.91]}},{"type":"Feature","properties":{"id":"talikota","name":"Talikota / Rakshasa-Tangadi (1565) — Deccan sultans crush Vijayanagara"},"geometry":{"type":"Point","coordinates":[76.31,16.47]}}]},"style":{"color":"#0e7a70","weight":2,"fillColor":"#0e7a70","markerRadius":7,"glow":true},"defaultOn":true,"labelKey":"name"},{"id":"south-rivers","name":"The three rivers of power","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"krishna-r","name":"Krishna — the contested frontier (Raichur doab between Krishna & Tungabhadra)"},"geometry":{"type":"LineString","coordinates":[[73.7,17.5],[75,16.9],[76.5,16.5],[78,16.4],[79.5,16.2],[80.9,15.8]]}},{"type":"Feature","properties":{"id":"tungabhadra-r","name":"Tungabhadra — Vijayanagara’s river (Hampi on its bank)"},"geometry":{"type":"LineString","coordinates":[[75.3,14.2],[75.9,14.8],[76.47,15.34],[77.2,15.7],[78.2,15.9]]}},{"type":"Feature","properties":{"id":"kaveri-r","name":"Kaveri — the Chola rice bowl; Thanjavur delta"},"geometry":{"type":"LineString","coordinates":[[75.5,12.4],[76.6,12.2],[77.6,11.9],[78.6,11.3],[79.13,10.9],[79.8,10.75]]}}]},"style":{"color":"#1f5fa8","weight":3,"flow":true},"defaultOn":true,"labelKey":"name"},{"id":"chola-navy","name":"Rajendra’s expeditions","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"ganga-exp","name":"c. 1022: Rajendra I’s Ganga expedition — defeats Mahipala I of Bengal"},"geometry":{"type":"LineString","coordinates":[[79.45,11.21],[80.3,13.2],[80.9,15.8],[83,18],[85.8,20.3],[87.5,22.5],[88.4,24]]}},{"type":"Feature","properties":{"id":"srivijaya-exp","name":"c. 1025: naval expedition against Srivijaya (Malaya–Sumatra) — command of the sea lanes"},"geometry":{"type":"LineString","coordinates":[[79.9,10.8],[84,9],[89,7.5],[94,6],[98.5,4.5],[102,3]]}}]},"style":{"color":"#b0632c","weight":2.5,"dashArray":"6 6","flow":true},"defaultOn":false,"labelKey":"name"}],"facts":[{"id":"f1","text":"The IMPERIAL CHOLAS (c. 850–1200) rebuilt Tamil power from the Kaveri delta. RAJARAJA I (985–1014) conquered Kerala, northern Sri Lanka and the Maldives, and raised the Brihadesvara (Rajarajesvaram) temple at Thanjavur — the grandest Dravidian temple, completed 1010.","linkedLayerId":"south-sites","linkedFeatureId":"thanjavur"},{"id":"f2","text":"RAJENDRA I (1014–44) took the empire to its peak: marched north and defeated MAHIPALA I of the Pala empire of Bengal, and to commemorate it founded GANGAIKONDACHOLAPURAM (“the Chola who took the Ganga”) with its own Rajesvaram temple. Called Pandita Cholan for his patronage of learning.","linkedLayerId":"chola-navy"},{"id":"f3","text":"The Chola NAVY was the age’s wonder: the c. 1025 expedition against SRIVIJAYA (Malaya–Sumatra) secured the eastern sea lanes to China. Chola local government is equally famous — the Uttaramerur inscriptions describe elected village assemblies (sabha/ur) with committee (variyam) systems.","linkedLayerId":"chola-navy"},{"id":"f4","text":"VIJAYANAGARA (1336–1672): founded by HARIHARA and BUKKA of the Sangama dynasty on the Tungabhadra — capital HAMPI. Four dynasties: Sangama → Saluva → Tuluva → Aravidu. Deva Raya II (1425–46) recruited Muslim cavalry and archers to modernize the army.","linkedLayerId":"south-sites","linkedFeatureId":"hampi"},{"id":"f5","text":"The BAHMANI kingdom (1347–1527): founded by ALAUDDIN HASAN BAHMAN SHAH in revolt against Muhammad-bin-Tughlaq; capital first at GULBARGA, later BIDAR. Its greatest figure was the minister MAHMUD GAWAN (1461–81) — conquests, administrative reform, and the great madrasa at Bidar — executed on a forged letter; the kingdom then split into the five Deccan sultanates (Bijapur, Ahmadnagar, Golkonda, Bidar, Berar).","linkedLayerId":"south-sites","linkedFeatureId":"bidar"},{"id":"f6","text":"Vijayanagara vs Bahmani: a 200-year war over the RAICHUR DOAB — the fertile, fort-studded strip between the Krishna and the Tungabhadra. KRISHNADEVA RAYA (1509–29, Tuluva) was the climax: took Raichur (1520), patronized Telugu letters (Amuktamalyada), hosted Portuguese travellers (Domingo Paes) — the “Andhra Bhoja”.","linkedLayerId":"south-rivers"},{"id":"f7","text":"TALIKOTA (Rakshasa-Tangadi / Bannihatti), 1565: the combined Deccan sultanates — Bijapur, Ahmadnagar, Golkonda and Bidar (all except Berar) — crushed Vijayanagara; regent RAMA RAYA was captured and executed, Hampi sacked. The empire lingered under the Aravidus but the south’s balance of power was broken — setting the stage for the Mughals and then the Europeans.","linkedLayerId":"south-sites","linkedFeatureId":"talikota"}],"events":[{"id":"e1","date":"1010","label":"Brihadesvara","description":"Rajaraja I completes the great temple at Thanjavur — the Kaveri delta is the engine of Chola power.","showLayers":["south-sites","south-rivers"],"hideLayers":["chola-navy"],"view":{"center":[10.79,79.13],"zoom":7}},{"id":"e2","date":"1022","label":"Ganga campaign","description":"Rajendra I defeats Mahipala I of Bengal; Gangaikondacholapuram founded in commemoration.","showLayers":["chola-navy","south-sites"],"view":{"center":[16,83],"zoom":5}},{"id":"e3","date":"1025","label":"Srivijaya raid","description":"The Chola navy strikes Srivijaya across the Bay of Bengal — command of the eastern sea lanes.","showLayers":["chola-navy"],"view":{"center":[8,90],"zoom":4}},{"id":"e4","date":"1336","label":"Vijayanagara founded","description":"Harihara and Bukka found the city on the Tungabhadra; the Bahmani kingdom follows in 1347 — the Deccan splits in two.","showLayers":["south-sites","south-rivers"],"hideLayers":["chola-navy"],"view":{"center":[16.3,76.7],"zoom":6}},{"id":"e5","date":"1520","label":"Raichur","description":"Krishnadeva Raya takes the Raichur doab — the Krishna–Tungabhadra frontier at its high-water mark.","view":{"center":[16.2,77.3],"zoom":7}},{"id":"e6","date":"1565","label":"Talikota","description":"Four Deccan sultanates combine and destroy Vijayanagara; Rama Raya executed, Hampi sacked.","view":{"center":[16.47,76.31],"zoom":7}}],"quiz":[{"id":"q1","type":"map_click","question":"Click Hampi — the Vijayanagara capital on the Tungabhadra.","answer":{"lat":15.34,"lng":76.47,"toleranceKm":110},"explanation":"Hampi sits on the south bank of the Tungabhadra — founded 1336 by Harihara and Bukka of the Sangama dynasty. Today a UNESCO site."},{"id":"q2","type":"mcq","question":"Gangaikondacholapuram was founded by Rajendra I to commemorate:","options":["The conquest of Sri Lanka","His victory over Mahipala I of Bengal in the Ganga campaign","The Srivijaya naval expedition","The completion of the Brihadesvara temple"],"answerIndex":1,"explanation":"“The city of the Chola who took the Ganga” — after defeating the Pala king Mahipala I. He built the Rajesvaram temple there and earned the title Pandita Cholan."},{"id":"q3","type":"mcq","question":"The 200-year Vijayanagara–Bahmani wars were fought chiefly over:","options":["The Kaveri delta","The Raichur doab, between the Krishna and the Tungabhadra","The Konkan coast","The Palghat gap"],"answerIndex":1,"explanation":"The fertile, fort-studded Raichur doab between the two rivers — Krishnadeva Raya’s capture of Raichur in 1520 marked Vijayanagara’s high point."},{"id":"q4","type":"mcq","question":"At Talikota (1565), Vijayanagara was defeated by the combined Deccan sultanates EXCEPT:","options":["Bijapur","Ahmadnagar","Berar","Golkonda"],"answerIndex":2,"explanation":"Bijapur, Ahmadnagar, Golkonda and Bidar combined — Berar stayed out. Rama Raya was executed and Hampi sacked; the battle is also called Rakshasa-Tangadi or Bannihatti."},{"id":"q5","type":"map_click","question":"Click Thanjavur — seat of Rajaraja I and the Brihadesvara temple.","answer":{"lat":10.79,"lng":79.13,"toleranceKm":100},"explanation":"Thanjavur commands the Kaveri delta — the rice bowl that funded the Chola navy and the grandest Dravidian temple (completed 1010)."},{"id":"q6","type":"mcq","question":"Mahmud Gawan is remembered as:","options":["Founder of Vijayanagara","The great Bahmani minister — conquests, reforms, the Bidar madrasa — executed on a forged letter","The admiral of the Chola navy","The last Sangama king"],"answerIndex":1,"explanation":"Gawan (1461–81) was the Bahmani kingdom’s greatest statesman; his judicial murder triggered the breakup into the five Deccan sultanates."},{"id":"q7","type":"mcq","question":"The Uttaramerur inscriptions are famous for describing:","options":["Chola naval tactics","Elected village assemblies and committee (variyam) administration under the Cholas","Vijayanagara market rules","Bahmani land revenue"],"answerIndex":1,"explanation":"Chola local self-government: village sabhas with lot-based elections and specialized committees — a favourite of both prelims and mains answers on ancient local governance."}]},"position":17,"hash":"b1e6377624d29b23841eb1bb1d3df55373d79893b291ab545c2319e1512fd35b"},{"body":{"id":"european-conquest","subject":"history","unit":"Modern","tags":["goa","calicut","bombay","madras","calcutta","bengal","carnatic","deccan","hooghly","coasts"],"title":"Europeans: Ports to Power","summary":"Five flags, one coastline — settlements, Carnatic, Mysore & Maratha wars.","focus":"Five European flags on one coastline. Learn each power’s port pairs — Portuguese–Goa, Dutch–Pulicat, English–Madras/Bombay/Calcutta, French–Pondicherry, Danes–Tranquebar — and the wars of conquest are just those ports fighting their way inland.","view":{"center":[15.5,78],"zoom":5},"basemap":"natgeo","theme":{"accent":"#31597e","mapBg":"#edf2f6"},"layers":[{"id":"portuguese","name":"Portuguese (1498–)","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"calicut","name":"Calicut — Vasco da Gama lands, 1498; welcomed by the Zamorin"},"geometry":{"type":"Point","coordinates":[75.78,11.25]}},{"type":"Feature","properties":{"id":"cochin-p","name":"Cochin — first Portuguese HQ (factories also at Cannanore)"},"geometry":{"type":"Point","coordinates":[76.24,9.93]}},{"type":"Feature","properties":{"id":"goa-p","name":"Goa — taken from Bijapur 1510 (Albuquerque); HQ from 1530; first printing press 1556"},"geometry":{"type":"Point","coordinates":[73.83,15.5]}},{"type":"Feature","properties":{"id":"diu","name":"Diu — Portuguese fort commanding the Gujarat coast"},"geometry":{"type":"Point","coordinates":[70.99,20.71]}},{"type":"Feature","properties":{"id":"daman","name":"Daman — Portuguese enclave (with Goa & Diu till 1961)"},"geometry":{"type":"Point","coordinates":[72.83,20.4]}}]},"style":{"color":"#2e7d5b","weight":2,"fillColor":"#2e7d5b","markerRadius":6},"defaultOn":true,"labelKey":"name"},{"id":"dutch-danish","name":"Dutch & Danes","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"masulipatnam","name":"Masulipatnam — Dutch control 1605"},"geometry":{"type":"Point","coordinates":[81.13,16.17]}},{"type":"Feature","properties":{"id":"pulicat","name":"Pulicat — chief Dutch settlement, 1610"},"geometry":{"type":"Point","coordinates":[80.32,13.42]}},{"type":"Feature","properties":{"id":"tranquebar","name":"Tranquebar (near Tanjore) — Danish factory, 1620"},"geometry":{"type":"Point","coordinates":[79.85,11.03]}},{"type":"Feature","properties":{"id":"serampore","name":"Serampore (near Calcutta) — principal Danish settlement; missionary press"},"geometry":{"type":"Point","coordinates":[88.34,22.75]}}]},"style":{"color":"#b0632c","weight":2,"fillColor":"#b0632c","markerRadius":6},"defaultOn":true,"labelKey":"name"},{"id":"english","name":"English presidencies","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"surat-e","name":"Surat — first English factory, 1613 (after Battle of Surat 1612; Thomas Roe at Jahangir’s court 1615)"},"geometry":{"type":"Point","coordinates":[72.83,21.17]}},{"type":"Feature","properties":{"id":"madras-e","name":"Madras — Fort St. George, 1639–40"},"geometry":{"type":"Point","coordinates":[80.28,13.08]}},{"type":"Feature","properties":{"id":"bombay-e","name":"Bombay — Portuguese dowry to Charles II (1662) → Company 1668 → HQ 1687"},"geometry":{"type":"Point","coordinates":[72.83,18.94]}},{"type":"Feature","properties":{"id":"calcutta-e","name":"Calcutta — Job Charnock at Sutanati 1690; Fort William 1700 (zamindari of Sutanati, Govindpur, Kalikata)"},"geometry":{"type":"Point","coordinates":[88.36,22.57]}}]},"style":{"color":"#b3261e","weight":2,"fillColor":"#b3261e","markerRadius":7,"glow":true},"defaultOn":true,"labelKey":"name"},{"id":"french","name":"French (1664–)","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"pondicherry","name":"Pondicherry — founded 1674; nerve centre of French India"},"geometry":{"type":"Point","coordinates":[79.83,11.93]}},{"type":"Feature","properties":{"id":"chandernagore-f","name":"Chandernagore — French Bengal post (taken by Clive, 1757)"},"geometry":{"type":"Point","coordinates":[88.38,22.87]}}]},"style":{"color":"#5b46a8","weight":2,"fillColor":"#5b46a8","markerRadius":6},"defaultOn":true,"labelKey":"name"},{"id":"war-sites","name":"Wars of conquest","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"st-thome","name":"St. Thome (1746) — 1st Carnatic War: Dupleix’s French rout the Carnatic Nawab"},"geometry":{"type":"Point","coordinates":[80.28,13.03]}},{"type":"Feature","properties":{"id":"wandiwash","name":"Wandiwash (1760) — 3rd Carnatic War: Eyre Coote crushes Lally; French power ends"},"geometry":{"type":"Point","coordinates":[79.62,12.51]}},{"type":"Feature","properties":{"id":"srirangapatna","name":"Srirangapatna — Tipu’s capital; died here in the 4th Anglo-Mysore War, 1799"},"geometry":{"type":"Point","coordinates":[76.68,12.42]}},{"type":"Feature","properties":{"id":"wadgaon","name":"Wadgaon (1779) — 1st Anglo-Maratha War: English defeated; Convention of Wadgaon"},"geometry":{"type":"Point","coordinates":[73.66,18.75]}}]},"style":{"color":"#7a1f2b","weight":2,"fillColor":"#7a1f2b","markerRadius":7,"glow":true},"defaultOn":false,"labelKey":"name"}],"facts":[{"id":"f1","text":"PORTUGUESE: Vasco da Gama reached CALICUT in 1498 (welcomed by the Zamorin, resented by Arab traders); returned 1501. Almeida (Governor 1505) pushed the BLUE WATER POLICY — mastery of the Indian Ocean; ALBUQUERQUE took GOA from Bijapur in 1510 (the first European-held Indian territory since Alexander); Nino da Cunha moved HQ Cochin→Goa in 1530. They brought tobacco cultivation and India’s first printing press (Goa, 1556).","linkedLayerId":"portuguese"},{"id":"f2","text":"DUTCH: the VOC formed 1602; Masulipatnam 1605, PULICAT 1610, Surat 1616, Cochin 1663 — spice-focused, and eventually squeezed out (Battle of Bedara vs the English, 1759). DANES: company founded 1616; TRANQUEBAR (1620) near Tanjore and SERAMPORE near Calcutta — remembered for missionaries more than trade; sold out to Britain in 1845.","linkedLayerId":"dutch-danish"},{"id":"f3","text":"ENGLISH: Charter from Elizabeth I on 31 December 1600 to the “Governor and Company of Merchants of London trading into the East Indies”. Battle of Surat 1612 beat the Portuguese at sea → Jahangir allowed the SURAT factory (1613); Sir THOMAS ROE (1615) at Jahangir’s court as James I’s ambassador. Madras/Fort St. George 1639–40; BOMBAY came as Portuguese dowry to Charles II (1662) → Company 1668 → HQ 1687; JOB CHARNOCK’s Sutanati treaty 1690 → zamindari of Sutanati, Govindpur, Kalikata (1698) → FORT WILLIAM 1700 = Calcutta.","linkedLayerId":"english"},{"id":"f4","text":"FRENCH: Colbert’s Compagnie des Indes Orientales, 1664, under Louis XIV; PONDICHERRY founded 1674 — the nerve centre; reorganized 1720 as the Perpetual Company, strengthened under Lenoir and Dumas, weaponized under DUPLEIX.","linkedLayerId":"french"},{"id":"f5","text":"CARNATIC WARS — the Anglo-French duel: 1st (1746–48): French take Madras; Battle of ST. THOME — Dupleix’s small French force routs the Carnatic Nawab’s army; Treaty of Aix-la-Chapelle (Austrian Succession in the background). 2nd (1749–54): puppet politics — French back Muzaffar Jung (Hyderabad) + Chanda Sahib (Carnatic), English back Nasir Jung + Muhammad Ali; Clive’s side wins; Treaty of Pondicherry/Godehu 1754. 3rd (1756–63): Lally takes Fort St. David but is crushed at WANDIWASH (1760, Eyre Coote); Treaty of Paris 1763 returns Pondicherry as a trading post — French political power in India is finished.","linkedLayerId":"war-sites"},{"id":"f6","text":"ANGLO-MYSORE WARS: 1st (1767–69) — HAIDAR ALI beats the English; Treaty of Madras. 2nd (1780–84) — Treaty of Mangalore under Warren Hastings. 3rd (1790–92) — Cornwallis vs TIPU; Treaty of Srirangapatna halves Mysore. 4th (1799) — Wellesley storms SRIRANGAPATNA; Tipu dies fighting. Mysore falls to Subsidiary Alliance.","linkedLayerId":"war-sites","linkedFeatureId":"srirangapatna"},{"id":"f7","text":"ANGLO-MARATHA WARS: 1st (1775–82) — English humiliated at WADGAON (Convention of Wadgaon, 1779), then Treaty of SALBAI (1782) abandoning Raghunath Rao. 2nd (1803–05) — after the Peshwa’s Subsidiary Alliance Treaty of BASSEIN (1802), the Marathas are beaten; Treaty of Rajghat with the Holkars (1805). 3rd (1817–19) — fought around Lord Hastings’ PINDARI campaign; Maratha power extinguished, British paramountcy complete.","linkedLayerId":"war-sites"}],"events":[{"id":"e1","date":"1498","label":"Vasco da Gama","description":"Calicut, 1498 — the sea route to India opens. The Zamorin welcomes; the Arab traders bristle.","showLayers":["portuguese"],"hideLayers":["war-sites"],"view":{"center":[11.25,75.78],"zoom":6}},{"id":"e2","date":"1510","label":"Goa taken","description":"Albuquerque seizes Goa from Bijapur — Portuguese HQ and the anchor of the Estado da India.","showLayers":["portuguese"],"view":{"center":[15.5,73.83],"zoom":7}},{"id":"e3","date":"1613","label":"Surat factory","description":"After beating the Portuguese at sea (1612), the English get Jahangir’s leave for a Surat factory; Thomas Roe follows in 1615.","showLayers":["english"],"view":{"center":[21.17,72.83],"zoom":6}},{"id":"e4","date":"1674","label":"Pondicherry","description":"François Martin founds Pondicherry — the French nerve centre and the English’s future rival.","showLayers":["french","english"],"view":{"center":[12.5,80],"zoom":6}},{"id":"e5","date":"1700","label":"Fort William","description":"Sutanati + Govindpur + Kalikata become fortified Calcutta — seat of the eastern presidency.","showLayers":["english"],"view":{"center":[22.57,88.36],"zoom":8}},{"id":"e6","date":"1760","label":"Wandiwash","description":"Eyre Coote destroys Lally’s French army — the decisive battle of the Carnatic wars. Paris (1763) leaves France a trader, not a power.","showLayers":["war-sites"],"view":{"center":[12.51,79.62],"zoom":7}},{"id":"e7","date":"1799","label":"Tipu falls","description":"Wellesley storms Srirangapatna; Tipu Sultan dies at the breach. Mysore enters Subsidiary Alliance.","showLayers":["war-sites"],"view":{"center":[12.42,76.68],"zoom":7}},{"id":"e8","date":"1818","label":"Paramountcy","description":"Third Anglo-Maratha war ends (1817–19) with the Pindaris crushed and the Peshwa deposed — Britain is paramount in India.","showLayers":["war-sites"],"view":{"center":[18.75,73.66],"zoom":6}}],"quiz":[{"id":"q1","type":"mcq","question":"Match power → chief settlement. Which pair is WRONG?","options":["Dutch — Pulicat","Danes — Tranquebar","French — Goa","Portuguese — Cochin (early HQ)"],"answerIndex":2,"explanation":"Goa was PORTUGUESE (taken 1510); the French nerve centre was Pondicherry (founded 1674). Dutch–Pulicat, Danes–Tranquebar/Serampore, Portuguese–Cochin-then-Goa are correct."},{"id":"q2","type":"map_click","question":"Click Calicut — where Vasco da Gama landed in 1498.","answer":{"lat":11.25,"lng":75.78,"toleranceKm":110},"explanation":"Calicut (Kozhikode) on the Malabar coast, ruled by the Zamorin. The sea route around the Cape rewired world trade — and India’s history."},{"id":"q3","type":"mcq","question":"Bombay came to the English East India Company as:","options":["A conquest from the Marathas","Portuguese dowry to Charles II (1662), transferred to the Company in 1668","A gift from Jahangir to Thomas Roe","Part of the Treaty of Paris"],"answerIndex":1,"explanation":"Catherine of Braganza’s dowry → Crown 1662 → Company 1668 (for £10 a year) → western HQ from 1687, replacing Surat."},{"id":"q4","type":"map_click","question":"Click Wandiwash — the 1760 battle that finished French power in India.","answer":{"lat":12.51,"lng":79.62,"toleranceKm":110},"explanation":"Eyre Coote crushed Count de Lally at Wandiwash (Vandavasi), Tamil Nadu. The Treaty of Paris (1763) returned Pondicherry — but only as a trading post."},{"id":"q5","type":"mcq","question":"In the SECOND Carnatic War, the French under Dupleix backed:","options":["Nasir Jung and Muhammad Ali","Muzaffar Jung (Hyderabad) and Chanda Sahib (Carnatic)","The Nizam and the Peshwa","Haidar Ali and Tipu"],"answerIndex":1,"explanation":"French: Muzaffar Jung + Chanda Sahib; English: Nasir Jung + Muhammad Ali. Clive’s side prevailed — Treaty of Pondicherry/Godehu, 1754, and Dupleix was recalled."},{"id":"q6","type":"mcq","question":"Sequence the Anglo-Mysore treaties: 1st, 2nd, 3rd wars ended respectively with:","options":["Mangalore → Madras → Srirangapatna","Madras → Mangalore → Srirangapatna","Srirangapatna → Madras → Mangalore","Madras → Srirangapatna → Mangalore"],"answerIndex":1,"explanation":"Treaty of Madras (1769, after Haidar Ali WON) → Treaty of Mangalore (1784) → Treaty of Srirangapatna (1792, Mysore halved). The 4th war (1799) ended with Tipu’s death, no treaty needed."},{"id":"q7","type":"mcq","question":"The Convention of Wadgaon (1779) is notable because:","options":["The French surrendered Pondicherry","The English were DEFEATED by the Marathas and signed on losing terms","Tipu ceded half his kingdom","The Pindaris were disbanded"],"answerIndex":1,"explanation":"A rare English humiliation — in the 1st Anglo-Maratha War. The Treaty of Salbai (1782) later restored the balance, with the English dropping Raghunath Rao’s cause."},{"id":"q8","type":"mcq","question":"Which Subsidiary Alliance treaty pulled the Peshwa under British protection and triggered the 2nd Anglo-Maratha War?","options":["Treaty of Salbai","Treaty of Bassein (1802)","Treaty of Rajghat","Treaty of Surat"],"answerIndex":1,"explanation":"Bassein, 1802 — Peshwa Baji Rao II signed Wellesley’s Subsidiary Alliance; Scindia and Bhonsle fought and lost (1803–05). Rajghat (1805) settled the Holkars."}]},"position":18,"hash":"934d6d0b9471efce45dd5100dd4a1850ca37ff64a6317e674f5d2dac64ea6b37"},{"body":{"id":"battle-of-plassey","subject":"history","unit":"Modern","tags":["bengal","calcutta","hooghly","ganga","murshidabad","carnatic"],"title":"Battle of Plassey, 1757","summary":"How one afternoon on a Bengal riverbank changed who ruled India for two centuries.","focus":"Plassey was a small skirmish that decided two centuries of Indian history — and it was decided by geography, weather, and betrayal, not by numerical strength.","view":{"center":[23.5,88],"zoom":7},"basemap":"natgeo","theme":{"accent":"#7a4a2a","mapBg":"#f0e6d2"},"layers":[{"id":"bengal-territory","name":"Bengal Subah, 1757","description":"The Nawab’s domain — wealthiest province of the dying Mughal Empire.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"bengal-1757","name":"Bengal Subah (under Siraj-ud-Daulah)"},"geometry":{"type":"Polygon","coordinates":[[[85,26.5],[88.5,27],[92.2,26],[92.5,24],[91,22],[88.5,21.5],[86.5,22],[85.5,24],[85,26.5]]]}}]},"defaultOn":true,"labelKey":"name","style":{"color":"#7a4a2a","fillColor":"#c4a06a","fillOpacity":0.35,"weight":2,"pattern":"hatch","flow":true}},{"id":"trading-posts","name":"European Trading Posts","description":"Why Europeans were in Bengal in the first place.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"calcutta","name":"Calcutta (British — Fort William)","power":"british"},"geometry":{"type":"Point","coordinates":[88.3639,22.5726]}},{"type":"Feature","properties":{"id":"chandernagore","name":"Chandernagore (French)","power":"french"},"geometry":{"type":"Point","coordinates":[88.355,22.866]}},{"type":"Feature","properties":{"id":"chinsurah","name":"Chinsurah (Dutch)","power":"dutch"},"geometry":{"type":"Point","coordinates":[88.39,22.9]}},{"type":"Feature","properties":{"id":"serampore","name":"Serampore (Danish)","power":"danish"},"geometry":{"type":"Point","coordinates":[88.35,22.75]}}]},"defaultOn":true,"labelKey":"name"},{"id":"key-locations","name":"Murshidabad & Plassey","description":"The Nawab’s capital and the village where it all ended.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"murshidabad","name":"Murshidabad (Nawab’s capital)"},"geometry":{"type":"Point","coordinates":[88.272,24.187]}},{"type":"Feature","properties":{"id":"plassey","name":"Plassey (Palashi)"},"geometry":{"type":"Point","coordinates":[88.255,23.795]}}]},"defaultOn":true,"labelKey":"name"},{"id":"clive-march","name":"Clive’s March","description":"150 km up the Bhagirathi, June 13–22, 1757.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"clive-march","name":"Clive’s march, June 13–22, 1757"},"geometry":{"type":"LineString","coordinates":[[88.3639,22.5726],[88.36,22.9],[88.35,23.1],[88.3,23.35],[88.27,23.6],[88.255,23.795]]}}]},"defaultOn":true,"style":{"color":"#1d4f7a","weight":3,"dashArray":"6 5"}},{"id":"battlefield","name":"Troop Positions, dawn June 23","description":"British 3,000 vs Nawab 50,000 — but a third of the Nawab’s force was Mir Jafar’s, secretly bribed.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"british-position","name":"British line (Clive, 3,000)","side":"british"},"geometry":{"type":"Polygon","coordinates":[[[88.25,23.8],[88.258,23.802],[88.258,23.798],[88.25,23.796],[88.25,23.8]]]}},{"type":"Feature","properties":{"id":"nawab-position","name":"Nawab’s army (Siraj-ud-Daulah, 50,000)","side":"nawab"},"geometry":{"type":"Polygon","coordinates":[[[88.255,23.815],[88.275,23.815],[88.275,23.805],[88.255,23.805],[88.255,23.815]]]}},{"type":"Feature","properties":{"id":"mir-jafar","name":"Mir Jafar’s cavalry (the betrayer — refused to fight)","side":"mir-jafar"},"geometry":{"type":"Polygon","coordinates":[[[88.265,23.81],[88.28,23.81],[88.28,23.802],[88.265,23.802],[88.265,23.81]]]}}]},"defaultOn":false,"labelKey":"name","style":{"weight":2.5,"fillOpacity":0.6,"shadow":true}},{"id":"aftermath","name":"EIC Territory by 1765","description":"Eight years later: the Diwani of Bengal, Bihar, and Orissa.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"eic-1765","name":"East India Company control by 1765 (Diwani)"},"geometry":{"type":"Polygon","coordinates":[[[83.5,26],[88.5,27],[92.5,26],[92.5,24],[91,21.5],[86.5,21.5],[83,22],[83.5,26]]]}}]},"defaultOn":false,"labelKey":"name","style":{"color":"#7a3a3a","fillColor":"#a05a3a","fillOpacity":0.4,"weight":2.5,"pattern":"cross"}}],"facts":[{"id":"f1","text":"By 1757 the Mughal Empire was collapsing. Bengal was its wealthiest province, governed by a semi-independent Nawab.","linkedLayerId":"bengal-territory"},{"id":"f2","text":"The East India Company’s Fort William at Calcutta had become rich on Bengal trade — and had been fortifying without the Nawab’s permission.","linkedLayerId":"trading-posts","linkedFeatureId":"calcutta"},{"id":"f3","text":"In June 1756 the young Nawab Siraj-ud-Daulah seized Calcutta. Surviving prisoners died in a packed cell — the \"Black Hole\" incident gave the British their pretext."},{"id":"f4","text":"Robert Clive sailed from Madras, retook Calcutta, captured the French post of Chandernagore, then marched north with about 3,000 men.","linkedLayerId":"clive-march"},{"id":"f5","text":"The Nawab’s army was around 50,000 strong with 50 French-officered cannons. The British were outnumbered roughly 17 to 1.","linkedLayerId":"battlefield"},{"id":"f6","text":"But Clive had bribed Mir Jafar, the Nawab’s commander, with the throne. A third of Bengal’s army would not fight.","linkedLayerId":"battlefield","linkedFeatureId":"mir-jafar"},{"id":"f7","text":"During the battle a sudden monsoon downpour soaked the Nawab’s gunpowder. The British had covered theirs with tarpaulins. The artillery duel was decided by weather."},{"id":"f8","text":"Within three hours the Nawab’s army broke. Mir Jafar was installed as the puppet Nawab."},{"id":"f9","text":"By 1765 the Company held the Diwani — the right to collect revenue — of Bengal, Bihar, and Orissa. Merchants had become rulers.","linkedLayerId":"aftermath"}],"events":[{"id":"e1","date":"1756-06-20","label":"Calcutta falls","description":"Siraj-ud-Daulah captures Fort William. The \"Black Hole\" incident follows.","showLayers":["bengal-territory","trading-posts"],"hideLayers":["clive-march","battlefield","aftermath"],"view":{"center":[22.7,88.4],"zoom":8}},{"id":"e2","date":"1757-01-02","label":"Clive retakes Calcutta","description":"Clive’s expedition from Madras recaptures the city.","showLayers":["bengal-territory","trading-posts"],"hideLayers":["battlefield","aftermath"],"view":{"center":[22.7,88.4],"zoom":8}},{"id":"e3","date":"1757-03-23","label":"Chandernagore taken","description":"The British seize the French outpost — eliminating European competition in Bengal.","showLayers":["trading-posts"],"hideLayers":["battlefield","aftermath"],"view":{"center":[22.9,88.35],"zoom":9}},{"id":"e4","date":"1757-06-13","label":"March begins","description":"Clive sets out from Calcutta with 3,000 men, heading for Murshidabad.","showLayers":["bengal-territory","clive-march","key-locations"],"hideLayers":["battlefield","aftermath"],"view":{"center":[23.2,88.3],"zoom":8}},{"id":"e5","date":"1757-06-23","label":"Battle of Plassey","description":"Three hours of fighting. A monsoon downpour, a soaked enemy artillery, and a commander who would not charge. The Nawab flees and is killed days later.","showLayers":["battlefield","clive-march","key-locations"],"hideLayers":["aftermath"],"view":{"center":[23.795,88.255],"zoom":11}},{"id":"e6","date":"1765-08-12","label":"Diwani granted","description":"The Mughal emperor formally grants the Company the right to collect revenue in Bengal, Bihar, and Orissa. The transformation is complete.","showLayers":["aftermath"],"hideLayers":["battlefield","clive-march"],"view":{"center":[24,86],"zoom":6}}],"quiz":[{"id":"q1","type":"map_click","question":"Click the river along which the Battle of Plassey was fought.","answer":{"lat":23.795,"lng":88.255,"toleranceKm":80},"explanation":"The Bhagirathi-Hooghly — a distributary of the Ganges. The battle was on its east bank near Palashi village. The river was the highway of trade, of armies, and of empires."},{"id":"q2","type":"mcq","question":"Despite being outnumbered roughly 17 to 1, the British won at Plassey primarily because:","options":["Their muskets had longer range","Mir Jafar, commanding much of the Nawab’s army, had been bribed and refused to fight, and a sudden downpour soaked the Nawab’s gunpowder","They had more artillery","The Mughal emperor sent reinforcements"],"answerIndex":1,"explanation":"Plassey was decided by betrayal and weather, not numerical or technical superiority. Mir Jafar held back a third of the Nawab’s force; the monsoon ruined the rest of the artillery. This is the single most important fact about the battle."},{"id":"q3","type":"map_click","question":"Click the capital of Bengal in 1757 — the city Clive was marching toward.","answer":{"lat":24.187,"lng":88.272,"toleranceKm":60},"explanation":"Murshidabad. Named after Murshid Quli Khan, the first Nawab. After Plassey it remained nominally the capital, but real power moved south to Calcutta."},{"id":"q4","type":"mcq","question":"What did the British gain from the Mughal emperor in 1765, formalizing Plassey’s real consequence?","options":["The right to mint coins","A monopoly on Indian Ocean trade","The Diwani of Bengal, Bihar, and Orissa — the right to collect revenue","Direct sovereignty over India"],"answerIndex":2,"explanation":"The Diwani grant of 1765 turned the East India Company from a trading enterprise into the de facto government of India’s richest provinces. Sovereignty technically remained Mughal; tax revenue went to the Company. This was Plassey’s true meaning."},{"id":"q5","type":"map_click","question":"Click the French trading post Clive captured before marching to Plassey.","answer":{"lat":22.866,"lng":88.355,"toleranceKm":30},"explanation":"Chandernagore (Chandannagar). Taken in March 1757, just months before Plassey. Removing the French was essential — Siraj-ud-Daulah had been counting on French support that never came."},{"id":"q6","type":"mcq","question":"Which treaty, signed in February 1757 after Clive arrived from Madras, saw Siraj concede British demands months before Plassey?","options":["Treaty of Allahabad","Treaty of Alinagar","Treaty of Salbai","Treaty of Srirangapatna"],"answerIndex":1,"explanation":"The Treaty of Alinagar (Feb 1757) — signed after Siraj had seized the Kasim Bazar factory and taken Fort William (20 June 1756, followed by the Black Hole incident). It bought time, not peace: Plassey came four months later."},{"id":"q7","type":"mcq","question":"Who among these did NOT betray Siraj-ud-Daulah at Plassey?","options":["Mir Jafar (Mir Bakshi)","Jagat Seth (biggest banker of Bengal)","Manik Chand (officer-in-charge of Calcutta)","Mir Qasim"],"answerIndex":3,"explanation":"The conspirators were Mir Jafar, Manik Chand, Amichand, Jagat Seth and Khadim Khan. Mir Qasim enters the story LATER — as Mir Jafar’s son-in-law and successor, whose revolt led to Buxar (1764). Siraj was killed by Mir Jafar’s son Miran."},{"id":"q8","type":"mcq","question":"The Battle of Buxar (22 Oct 1764) was fought by the British against the combined forces of:","options":["Mir Jafar, Siraj-ud-Daulah and the French","Mir Qasim, Shuja-ud-Daula (Awadh) and Shah Alam II (Mughal emperor)","The Marathas and the Nizam","Haidar Ali and Tipu Sultan"],"answerIndex":1,"explanation":"Mir Qasim — deposed for abolishing dastak abuse and duties — allied with Shuja-ud-Daula of Awadh and emperor Shah Alam II. Their defeat at Buxar mattered MORE than Plassey militarily, and produced the Treaty of Allahabad (Aug 1765) granting the Diwani."},{"id":"q9","type":"mcq","question":"Under Clive’s Dual Government of Bengal (1765–1772):","options":["The Company held Nizamat, the Nawab held Diwani","The Company collected revenue (Diwani) while the Nawab kept civil administration (Nizamat); Warren Hastings ended it in 1772","The Mughal emperor administered Bengal directly","Bengal was split between Britain and France"],"answerIndex":1,"explanation":"Diwani (revenue) to the Company, Nizamat (administration) to the Nawab — power without responsibility, responsibility without power. Warren Hastings abolished the system in 1772 and the Company took direct charge."}]},"position":19,"hash":"c9a5741b67a2b060fea4329eaf9181162d251858abd2590348fc8555bb5e1503"},{"body":{"id":"freedom-struggle-map","subject":"history","unit":"Modern","tags":["delhi","bengal","calcutta","bombay","gujarat","champaran","punjab","bihar"],"title":"Freedom Struggle on the Map","summary":"1857 centres & leaders; Champaran to Dandi to Quit India.","focus":"Two map-layers of resistance: 1857’s garrison towns each paired with a leader, and Gandhi’s satyagrahas each pinned to a village. Centre–leader and movement–place pairings are what exams actually test.","view":{"center":[24.5,79],"zoom":5},"basemap":"natgeo","theme":{"accent":"#1a6b3c","mapBg":"#eef5ef"},"layers":[{"id":"revolt-1857","name":"1857 revolt centres","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"barrackpore","name":"Barrackpore — Mangal Pandey, 34th Native Infantry (29 Mar 1857)"},"geometry":{"type":"Point","coordinates":[88.37,22.76]}},{"type":"Feature","properties":{"id":"meerut","name":"Meerut — outbreak, 10 May 1857"},"geometry":{"type":"Point","coordinates":[77.71,28.98]}},{"type":"Feature","properties":{"id":"delhi-1857","name":"Delhi — Bahadur Shah II & General Bakht Khan"},"geometry":{"type":"Point","coordinates":[77.23,28.66]}},{"type":"Feature","properties":{"id":"lucknow","name":"Lucknow — Begum Hazrat Mahal, Birjis Qadir, Ahmadullah"},"geometry":{"type":"Point","coordinates":[80.95,26.85]}},{"type":"Feature","properties":{"id":"kanpur","name":"Kanpur — Nana Sahib, Tantia Tope, Azimullah Khan"},"geometry":{"type":"Point","coordinates":[80.33,26.45]}},{"type":"Feature","properties":{"id":"jhansi","name":"Jhansi — Rani Laxmibai"},"geometry":{"type":"Point","coordinates":[78.57,25.45]}},{"type":"Feature","properties":{"id":"bareilly","name":"Bareilly — Khan Bahadur"},"geometry":{"type":"Point","coordinates":[79.42,28.36]}},{"type":"Feature","properties":{"id":"allahabad-1857","name":"Allahabad — Liaqat Ali"},"geometry":{"type":"Point","coordinates":[81.85,25.44]}},{"type":"Feature","properties":{"id":"arrah","name":"Jagdishpur/Arrah (Bihar) — Kunwar Singh"},"geometry":{"type":"Point","coordinates":[84.42,25.47]}},{"type":"Feature","properties":{"id":"faizabad","name":"Faizabad — Maulvi Ahmadullah"},"geometry":{"type":"Point","coordinates":[82.15,26.77]}}]},"style":{"color":"#8a1c1c","weight":2,"fillColor":"#b3261e","fillOpacity":0.9,"shadow":true,"flow":true},"defaultOn":true,"labelKey":"name"},{"id":"gandhi-sites","name":"Gandhian movement sites","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"champaran","name":"Champaran 1917 — first Civil Disobedience (indigo tinkathia)"},"geometry":{"type":"Point","coordinates":[84.92,26.65]}},{"type":"Feature","properties":{"id":"kheda","name":"Kheda 1918 — first Non-Cooperation (revenue withheld)"},"geometry":{"type":"Point","coordinates":[72.68,22.75]}},{"type":"Feature","properties":{"id":"amritsar","name":"Jallianwala Bagh, Amritsar — 13 Apr 1919"},"geometry":{"type":"Point","coordinates":[74.88,31.62]}},{"type":"Feature","properties":{"id":"chauri-chaura","name":"Chauri Chaura — Feb 1922, NCM withdrawn"},"geometry":{"type":"Point","coordinates":[83.6,26.65]}},{"type":"Feature","properties":{"id":"sabarmati","name":"Sabarmati Ashram, Ahmedabad — march starts 12 Mar 1930"},"geometry":{"type":"Point","coordinates":[72.58,23.06]}},{"type":"Feature","properties":{"id":"dandi","name":"Dandi — salt law broken, 6 Apr 1930"},"geometry":{"type":"Point","coordinates":[72.79,20.88]}},{"type":"Feature","properties":{"id":"bombay-1942","name":"Bombay — Quit India resolution, 8 Aug 1942 (“Do or Die”)"},"geometry":{"type":"Point","coordinates":[72.81,18.96]}}]},"style":{"color":"#1a6b3c","weight":2,"fillColor":"#1a6b3c","fillOpacity":0.9,"shadow":true},"defaultOn":false,"labelKey":"name"},{"id":"dandi-march","name":"Dandi March route (1930)","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"dandi-march","name":"Dandi March — Gandhi + 78 followers, 12 Mar – 6 Apr 1930"},"geometry":{"type":"LineString","coordinates":[[72.58,23.06],[72.62,22.75],[72.9,22.3],[72.95,21.7],[72.85,21.2],[72.79,20.88]]}}]},"style":{"color":"#1a6b3c","weight":3,"dashArray":"2 6"},"defaultOn":false,"labelKey":"name"}],"facts":[{"id":"f1","text":"1857 causes: Awadh annexed (1856) for “maladministration”, Jhansi via Doctrine of Lapse (Dalhousie, 1848–56: no adopted heir allowed); sepoy grievances (low pay, ceiling at subedar, racial discrimination); social reforms + missionaries; economic drain. Immediate spark: the Enfield cartridge greased with cow and pig fat.","linkedLayerId":"revolt-1857"},{"id":"f2","text":"Sequence: 19th NI at Berhampur refuses the cartridge → Mangal Pandey (34th NI) fires at his sergeant-major at Barrackpore and is hanged → the revolt proper breaks out at MEERUT on 10 May 1857 → sepoys reach Delhi and declare Bahadur Shah Zafar Emperor of India.","linkedLayerId":"revolt-1857","linkedFeatureId":"meerut"},{"id":"f3","text":"Centre → leader pairs (learn as a table): Delhi – Bahadur Shah II + Gen. Bakht Khan; Lucknow – Begum Hazrat Mahal; Kanpur – Nana Sahib with Tantia Tope & Azimullah Khan; Jhansi – Rani Laxmibai; Bareilly – Khan Bahadur; Allahabad – Liaqat Ali; Jagdishpur/Arrah – Kunwar Singh; Faizabad – Maulvi Ahmadullah.","linkedLayerId":"revolt-1857"},{"id":"f4","text":"Consequence: Government of India Act 1858 abolished Company rule — the Crown ruled directly. (Also remember Wellesley’s Subsidiary Alliance and Dalhousie’s Doctrine of Lapse as the annexation machinery that fed the revolt.)"},{"id":"f5","text":"Gandhi’s laboratory: Champaran 1917 = FIRST civil disobedience (indigo planters’ tinkathia); Kheda 1918 = FIRST non-cooperation (crop failure → revenue withheld under the revenue code). Then Jallianwala Bagh (13 Apr 1919) and Khilafat fed into the Non-Cooperation Movement (1920–22), financed by the Tilak Swarajya Fund.","linkedLayerId":"gandhi-sites"},{"id":"f6","text":"Chauri Chaura, February 1922: a mob burnt a police station; Gandhi withdrew the Non-Cooperation Movement at its height — the most argued-about decision of the era, and the cause of the Swarajist split.","linkedLayerId":"gandhi-sites","linkedFeatureId":"chauri-chaura"},{"id":"f7","text":"Civil Disobedience began 12 March 1930: Gandhi + 78 chosen followers walked ~375 km from Sabarmati Ashram to Dandi on the Gujarat seacoast and broke the salt law on 6 April. Salt was genius: the one tax every villager paid.","linkedLayerId":"dandi-march"},{"id":"f8","text":"Quit India: the AICC met at Bombay on 8 August 1942 and passed the resolution — “Do or Die”. Leadership was jailed within hours; the movement went leaderless and underground. Gandhi fasted 21 days (Feb–Mar 1943) against the repression.","linkedLayerId":"gandhi-sites","linkedFeatureId":"bombay-1942"}],"events":[{"id":"e1","date":"1857-03-29","label":"Mangal Pandey","description":"Barrackpore: Mangal Pandey of the 34th NI fires on his sergeant-major; he is hanged. The 19th NI at Berhampur had already refused the cartridge.","showLayers":["revolt-1857"],"hideLayers":["gandhi-sites","dandi-march"],"view":{"center":[22.76,88.37],"zoom":8}},{"id":"e2","date":"1857-05-10","label":"Meerut rises","description":"The revolt breaks out at Meerut; sepoys march on Delhi and proclaim Bahadur Shah Zafar Emperor of India.","showLayers":["revolt-1857"],"hideLayers":["gandhi-sites","dandi-march"],"view":{"center":[28.8,77.4],"zoom":7}},{"id":"e3","date":"1858-08-02","label":"Crown rule","description":"Government of India Act 1858: Company rule abolished; the British Crown governs directly.","showLayers":["revolt-1857"],"view":{"center":[25.5,80],"zoom":5}},{"id":"e4","date":"1917-04-10","label":"Champaran","description":"Gandhi’s first civil disobedience in India — for indigo cultivators against the tinkathia system.","showLayers":["gandhi-sites"],"hideLayers":["revolt-1857"],"view":{"center":[26.65,84.92],"zoom":7}},{"id":"e5","date":"1919-04-13","label":"Jallianwala Bagh","description":"Dyer’s massacre at Amritsar. With the Khilafat issue and post-war distress, it lights the fuse of Non-Cooperation (1920–22).","showLayers":["gandhi-sites"],"view":{"center":[31.62,74.88],"zoom":8}},{"id":"e6","date":"1922-02-05","label":"Chauri Chaura","description":"Mob violence at a police station; Gandhi withdraws Non-Cooperation at its peak.","showLayers":["gandhi-sites"],"view":{"center":[26.65,83.6],"zoom":8}},{"id":"e7","date":"1930-03-12","label":"Dandi March","description":"Sabarmati → Dandi, ~375 km, 78 followers, 25 days. Salt law broken 6 April; Civil Disobedience begins.","showLayers":["gandhi-sites","dandi-march"],"view":{"center":[22,72.7],"zoom":7}},{"id":"e8","date":"1942-08-08","label":"Quit India","description":"AICC at Bombay passes the Quit India resolution. “Do or Die.” Leaders jailed within hours.","showLayers":["gandhi-sites"],"hideLayers":["dandi-march"],"view":{"center":[18.96,72.81],"zoom":8}}],"quiz":[{"id":"q1","type":"map_click","question":"Click Meerut — where the Revolt of 1857 broke out on 10 May.","answer":{"lat":28.98,"lng":77.71,"toleranceKm":70},"explanation":"Meerut’s sepoys rose on 10 May 1857 and marched overnight to Delhi to proclaim Bahadur Shah Zafar emperor. Barrackpore (Mangal Pandey) was the prologue, Meerut the outbreak."},{"id":"q2","type":"mcq","question":"Match the WRONG pair — 1857 centre : leader.","options":["Kanpur : Nana Sahib","Lucknow : Begum Hazrat Mahal","Bareilly : Kunwar Singh","Faizabad : Maulvi Ahmadullah"],"answerIndex":2,"explanation":"Bareilly was led by Khan Bahadur. Kunwar Singh led at Jagdishpur/Arrah in Bihar. The rest are correct pairs — and every one of them is a past exam question."},{"id":"q3","type":"mcq","question":"The immediate cause of the 1857 revolt was:","options":["The annexation of Awadh","The Enfield rifle cartridges greased with cow and pig fat (plus the bone-dust-in-atta rumour)","The Doctrine of Lapse","Low sepoy salaries"],"answerIndex":1,"explanation":"Awadh, Lapse, and pay were underlying causes; the greased cartridge was the spark. The 19th NI at Berhampur refused it first; Mangal Pandey (34th NI) fired the first shot at Barrackpore."},{"id":"q4","type":"mcq","question":"Champaran (1917) and Kheda (1918) are called, respectively, Gandhi’s first ______ and first ______ in India.","options":["Non-cooperation; civil disobedience","Civil disobedience; non-cooperation","Satyagraha; hartal","Fast; strike"],"answerIndex":1,"explanation":"Champaran = first CIVIL DISOBEDIENCE (defying the indigo tinkathia system); Kheda = first NON-COOPERATION (peasants withholding revenue after crop failure). The order trips people up — anchor each to its place on the map."},{"id":"q5","type":"map_click","question":"Click Dandi — where Gandhi broke the salt law on 6 April 1930.","answer":{"lat":20.88,"lng":72.79,"toleranceKm":90},"explanation":"Dandi, a village on the Gujarat seacoast, ~375 km from Sabarmati Ashram. Gandhi walked 25 days with 78 chosen followers to pick up a handful of salt."},{"id":"q6","type":"mcq","question":"Why did Gandhi withdraw the Non-Cooperation Movement in February 1922?","options":["The British granted dominion status","The Chauri Chaura incident, where a mob burnt policemen in a police station","The Khilafat issue was resolved","Congress ordered him to"],"answerIndex":1,"explanation":"Chauri Chaura convinced Gandhi the masses weren’t ready for non-violent struggle. The withdrawal split the movement — Swarajists (council entry) vs no-changers."},{"id":"q7","type":"mcq","question":"The Quit India resolution was passed on 8 August 1942 by the AICC meeting at:","options":["Calcutta","Lahore","Bombay","Karachi"],"answerIndex":2,"explanation":"Bombay (Gowalia Tank). “Do or Die.” The entire leadership was arrested within hours, and the movement went underground."},{"id":"q8","type":"map_click","question":"Click Jhansi — Rani Laxmibai’s centre, annexed earlier under the Doctrine of Lapse.","answer":{"lat":25.45,"lng":78.57,"toleranceKm":80},"explanation":"Jhansi, in Bundelkhand. Dalhousie’s Doctrine of Lapse (no adopted heirs) had annexed it — the policy grievance and the 1857 leader meet in one place."},{"id":"q9","type":"mcq","question":"Which Act followed directly from the 1857 revolt?","options":["Regulating Act 1773","Government of India Act 1858 — Crown rule replaces Company rule","Indian Councils Act 1909","Government of India Act 1935"],"answerIndex":1,"explanation":"The GoI Act 1858 abolished East India Company rule and began the British Raj — direct government through the Crown’s representatives."}]},"position":20,"hash":"60f4675c344ba7a4eafb10365cf4ceb93b80116181a7548154fee01c2b985afc"},{"body":{"id":"polity-making-of-constitution","subject":"polity","unit":"Constitution","tags":["calcutta","delhi","bengal","buxar","allahabad","constitution","british"],"title":"Making of the Constitution","summary":"From the Regulating Act 1773 to 26 January 1950 — the statutes, cities and committees that built the Constitution.","focus":"The Constitution accreted over 175 years along a Calcutta→Delhi axis — Regulating Act 1773 → GoI Act 1935 → Constituent Assembly 1946–49. Know the acts in order, and know what each introduced first.","view":{"center":[24.5,83],"zoom":5},"basemap":"natgeo","theme":{"accent":"#4a5fa5"},"layers":[{"id":"diwani","name":"Diwani grant 1765","description":"Revenue rights over Bengal, Bihar & Orissa — Company rule begins in substance.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"diwani-1765","name":"Diwani of Bengal, Bihar & Orissa (1765)"},"geometry":{"type":"Polygon","coordinates":[[[83.3,25.6],[86,27.2],[88.6,27.1],[92.3,26.1],[92.6,24.1],[91,22],[88.4,21.4],[86.8,19.9],[84.6,19.2],[83.6,21.6],[84,23.8],[83.3,25.6]]]}}]},"style":{"color":"#4a5fa5","fillColor":"#4a5fa5","fillOpacity":0.1,"weight":2,"pattern":"hatch"},"defaultOn":true,"labelKey":"name"},{"id":"dawn","name":"Buxar & Allahabad","description":"The battle and the treaty that made traders into rulers.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"buxar","name":"Buxar (1764) — Company defeats Mir Qasim, Shuja-ud-Daula & Shah Alam II"},"geometry":{"type":"Point","coordinates":[83.9787,25.5647]}},{"type":"Feature","properties":{"id":"allahabad","name":"Allahabad (1765) — Treaty: Shah Alam II grants Diwani of Bengal, Bihar & Orissa to Clive"},"geometry":{"type":"Point","coordinates":[81.8463,25.4358]}}]},"style":{"color":"#a5504a","markerRadius":8,"glow":true},"defaultOn":true,"labelKey":"name"},{"id":"seats","name":"Seats of power","description":"Calcutta, Delhi and the subordinated presidencies.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"calcutta-sc","name":"Calcutta — capital of British India till 1911; Supreme Court set up 1774 (Regulating Act 1773)"},"geometry":{"type":"Point","coordinates":[88.3639,22.5726]}},{"type":"Feature","properties":{"id":"delhi-ca","name":"Delhi — capital from 1911; Constituent Assembly met here (9 Dec 1946), Federal Court 1937"},"geometry":{"type":"Point","coordinates":[77.209,28.6139]}},{"type":"Feature","properties":{"id":"madras-presi","name":"Madras Presidency — made subordinate to Bengal by the Regulating Act 1773"},"geometry":{"type":"Point","coordinates":[80.2707,13.0827]}},{"type":"Feature","properties":{"id":"bombay-presi","name":"Bombay Presidency — made subordinate to Bengal by the Regulating Act 1773"},"geometry":{"type":"Point","coordinates":[72.8321,18.9582]}}]},"style":{"color":"#2e5d8a","markerRadius":7},"defaultOn":true,"labelKey":"name"},{"id":"capital-shift","name":"Capital shift 1911","description":"Calcutta → Delhi: the constitutional centre of gravity moves.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"shift-1911","name":"Capital shift: Calcutta → Delhi (announced 1911)"},"geometry":{"type":"LineString","coordinates":[[88.3639,22.5726],[86.4,23.9],[83.9,25.1],[81.8,25.6],[79.5,27.2],[77.209,28.6139]]}}]},"style":{"color":"#7a4a2a","weight":3,"flow":true,"dashArray":"6 8"},"defaultOn":false,"labelKey":"name"}],"facts":[{"id":"f1","text":"The East India Company arrived in 1600 as traders under a charter of Queen Elizabeth I. Company Rule ran 1773–1858, Crown Rule 1858–1947."},{"id":"f2","text":"Battle of Buxar (1764) → Treaty of Allahabad (1765, Shah Alam II & Robert Clive): the Company gained Diwani (revenue) rights over Bengal, Bihar and Orissa.","linkedLayerId":"dawn"},{"id":"f3","text":"Regulating Act 1773: Governor of Bengal became Governor-General of Bengal (first: Warren Hastings); Madras & Bombay made subordinate; Supreme Court at Calcutta (1774).","linkedLayerId":"seats"},{"id":"f4","text":"GoI Act 1919 (Montagu–Chelmsford): dyarchy in provinces (transferred + reserved subjects), bicameralism and direct elections for the first time; High Commissioner for India in London."},{"id":"f5","text":"GoI Act 1935 — the longest British act (321 Sections, 10 Schedules): All-India Federation (never realised), Federal/Provincial/Concurrent Lists (59/54/36), residuary powers with the Viceroy, RBI and Federal Court (1937), dyarchy abolished in provinces."},{"id":"f6","text":"Constituent Assembly: idea first proposed by M.N. Roy (1934); set up under the Cabinet Mission Plan 1946; members indirectly elected by Provincial Legislative Assemblies."},{"id":"f7","text":"Membership: originally 389 (292 provinces + 93 princely states + 4 chief commissioner’s provinces); 299 after Partition."},{"id":"f8","text":"First sitting 9 Dec 1946. Sachchidananda Sinha = temporary Chairman; Rajendra Prasad = President; H.C. Mookerjee = Vice-President; B.N. Rau = constitutional advisor."},{"id":"f9","text":"Drafting Committee (29 Aug 1947, 7 members) chaired by Dr B.R. Ambedkar — it sat only 141 days. Objectives Resolution moved by Nehru on 22 Jan 1947."},{"id":"f10","text":"Adopted 26 Nov 1949 (Preamble + 395 Articles + 8 Schedules); in force 26 Jan 1950. Constitution Day celebrated on 26 Nov since 2015."}],"events":[{"id":"e1","date":"1600","label":"1600 — EIC arrives","description":"East India Company comes to India as traders under a royal charter of Elizabeth I."},{"id":"e2","date":"1765","label":"1765 — Diwani","description":"After Buxar (1764), the Treaty of Allahabad gives the Company Diwani of Bengal, Bihar & Orissa.","showLayers":["dawn","diwani"],"view":{"center":[25.2,84.5],"zoom":6}},{"id":"e3","date":"1773","label":"1773 — Regulating Act","description":"Governor-General of Bengal created (Warren Hastings); Supreme Court at Calcutta 1774; Madras & Bombay subordinated.","showLayers":["seats"],"view":{"center":[22.6,88.36],"zoom":6}},{"id":"e4","date":"1858","label":"1858 — Crown Rule","description":"GoI Act 1858 after the Revolt of 1857: Company rule ends, Secretary of State for India + Viceroy (first: Canning)."},{"id":"e5","date":"1911","label":"1911 — Capital to Delhi","description":"The capital shifts from Calcutta to Delhi — the future constitutional centre.","showLayers":["capital-shift"],"view":{"center":[25.8,82.5],"zoom":5}},{"id":"e6","date":"1919","label":"1919 — Montford Reforms","description":"GoI Act 1919: dyarchy in the provinces, bicameralism, first direct elections."},{"id":"e7","date":"1935","label":"1935 — GoI Act","description":"The 1935 Act — the single biggest source of the 1950 Constitution: federation scheme, three lists, provincial autonomy, RBI, Federal Court."},{"id":"e8","date":"1946-12-09","label":"1946 — CA first sits","description":"Constituent Assembly first meets in Delhi under temporary Chairman Sachchidananda Sinha.","view":{"center":[28.61,77.21],"zoom":6}},{"id":"e9","date":"1949-11-26","label":"1949 — Adopted","description":"Constitution adopted: Preamble + 395 Articles + 8 Schedules."},{"id":"e10","date":"1950-01-26","label":"1950 — In force","description":"Constitution comes into force on 26 January 1950 — the date chosen to honour Purna Swaraj Day (26 Jan 1930)."}],"quiz":[{"id":"q1","type":"mcq","question":"The Regulating Act of 1773 designated whom as the first Governor-General of Bengal?","options":["Robert Clive","Warren Hastings","Lord Cornwallis","Lord Mountbatten"],"answerIndex":1,"explanation":"The Act renamed the Governor of Bengal as Governor-General of Bengal — first holder Warren Hastings. It also set up the Supreme Court at Calcutta (1774)."},{"id":"q2","type":"map_click","question":"Click the city where the Regulating Act 1773 established the Supreme Court (1774).","answer":{"lat":22.5726,"lng":88.3639,"toleranceKm":150},"explanation":"Calcutta — capital of British India until 1911 and seat of the 1774 Supreme Court."},{"id":"q3","type":"mcq","question":"Diwani rights over Bengal, Bihar and Orissa came to the Company after which event?","options":["Battle of Plassey","Battle of Buxar / Treaty of Allahabad","Revolt of 1857","Third Round Table Conference"],"answerIndex":1,"explanation":"After Buxar (1764), the Treaty of Allahabad (1765) between Shah Alam II and Clive granted the Diwani."},{"id":"q4","type":"mcq","question":"The Government of India Act 1935 contained:","options":["145 Sections, 5 Schedules","321 Sections, 10 Schedules","395 Articles, 8 Schedules","250 Sections, 12 Schedules"],"answerIndex":1,"explanation":"321 Sections and 10 Schedules — the longest act passed by the British Parliament for India. (395 Articles + 8 Schedules is the 1949 Constitution.)"},{"id":"q5","type":"mcq","question":"Who first proposed the idea of a Constituent Assembly for India?","options":["Jawaharlal Nehru","M.N. Roy","B.R. Ambedkar","Mahatma Gandhi"],"answerIndex":1,"explanation":"M.N. Roy proposed it in 1934; Congress made it an official demand in 1935; the British conceded it in the August Offer 1940; it was constituted under the Cabinet Mission Plan 1946."},{"id":"q6","type":"mcq","question":"The Drafting Committee of the Constitution was chaired by:","options":["Rajendra Prasad","B.N. Rau","Dr B.R. Ambedkar","H.C. Mookerjee"],"answerIndex":2,"explanation":"Formed 29 Aug 1947 with 7 members under Ambedkar. Rajendra Prasad presided over the Assembly; B.N. Rau was the constitutional advisor."},{"id":"q7","type":"map_click","question":"Click the site of the 1765 treaty that granted the Company the Diwani of Bengal, Bihar and Orissa.","answer":{"lat":25.4358,"lng":81.8463,"toleranceKm":130},"explanation":"Allahabad (Prayagraj) — Treaty of Allahabad, 1765, between Shah Alam II and Robert Clive."}]},"position":21,"hash":"1c9805c1a606029fc7eaa0ad9f54f71889885c5a2f5c18f596cb17eedc5aed00"},{"body":{"id":"polity-states-reorganisation","subject":"polity","unit":"Constitution","tags":["madras","hyderabad","bombay","nagaland","mizoram","sikkim","goa","states","northeast"],"title":"Union & States Reorganisation","summary":"Articles 1–4: how Parliament has redrawn India’s map — Andhra 1953, SRA 1956, NE wave 1963–87, three states in 2000, Telangana 2014.","focus":"Article 3 lets Parliament create/alter states by SIMPLE majority (with the President’s prior recommendation; the affected state’s opinion is not binding). Track the waves: 1953 → 1956 → 1960/66 → 1963–87 (NE) → 2000 → 2014.","view":{"center":[21.5,82],"zoom":4.5},"basemap":"natgeo","theme":{"accent":"#4a5fa5"},"layers":[{"id":"andhra-spark","name":"The linguistic spark","description":"Potti Sriramulu, Andhra 1953, and the 2014 Telangana echo.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"madras-1953","name":"Madras — Potti Sriramulu’s 56-day fast (1952) for a Telugu state"},"geometry":{"type":"Point","coordinates":[80.2707,13.0827]}},{"type":"Feature","properties":{"id":"kurnool","name":"Kurnool — first capital of Andhra State (1953)"},"geometry":{"type":"Point","coordinates":[78.0373,15.8281]}},{"type":"Feature","properties":{"id":"hyderabad-2014","name":"Hyderabad — shared capital when Telangana became the 29th state (2 June 2014)"},"geometry":{"type":"Point","coordinates":[78.4867,17.385]}}]},"style":{"color":"#a5504a","markerRadius":8,"glow":true},"defaultOn":true,"labelKey":"name"},{"id":"bifurcations","name":"Bifurcation waves","description":"1960 Bombay, 1966 Punjab, 2000 trio, 2014 Telangana.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"bombay-split","name":"Bombay → Maharashtra + Gujarat (1 May 1960)"},"geometry":{"type":"Point","coordinates":[72.8321,18.9582]}},{"type":"Feature","properties":{"id":"punjab-split","name":"Punjab → Punjab + Haryana (1966); Chandigarh = shared capital (UT)"},"geometry":{"type":"Point","coordinates":[76.7794,30.7333]}},{"type":"Feature","properties":{"id":"uttarakhand","name":"Uttaranchal/Uttarakhand out of UP (9 Nov 2000)"},"geometry":{"type":"Point","coordinates":[79.0193,30.0668]}},{"type":"Feature","properties":{"id":"jharkhand","name":"Jharkhand out of Bihar (15 Nov 2000)"},"geometry":{"type":"Point","coordinates":[85.3096,23.6102]}},{"type":"Feature","properties":{"id":"chhattisgarh","name":"Chhattisgarh out of MP (1 Nov 2000)"},"geometry":{"type":"Point","coordinates":[81.8661,21.2787]}},{"type":"Feature","properties":{"id":"telangana","name":"Telangana out of Andhra Pradesh (2 June 2014) — 29th state"},"geometry":{"type":"Point","coordinates":[79.0193,18.1124]}}]},"style":{"color":"#4a5fa5","markerRadius":7},"defaultOn":true,"labelKey":"name"},{"id":"ne-wave","name":"North-East statehood wave","description":"Nagaland 1963 → NEAR Act 1971 → Mizoram & Arunachal 1987; Sikkim 1975.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"meghalaya","name":"Meghalaya — state 1972 (carved from Assam)"},"geometry":{"type":"Point","coordinates":[91.3662,25.467]}},{"type":"Feature","properties":{"id":"manipur-st","name":"Manipur — UT 1956 → state 1972"},"geometry":{"type":"Point","coordinates":[93.9063,24.6637]}},{"type":"Feature","properties":{"id":"tripura-st","name":"Tripura — UT 1956 → state 1972"},"geometry":{"type":"Point","coordinates":[91.2868,23.8315]}},{"type":"Feature","properties":{"id":"nagaland-st","name":"Nagaland — 16th state, 1 Dec 1963 (13th Amendment, Art 371A)"},"geometry":{"type":"Point","coordinates":[94.1086,26.1584]}},{"type":"Feature","properties":{"id":"mizoram-st","name":"Mizoram — UT 1972 → 23rd state 1987 (53rd Amendment, Art 371G)"},"geometry":{"type":"Point","coordinates":[92.7173,23.7307]}},{"type":"Feature","properties":{"id":"arunachal-st","name":"Arunachal Pradesh (NEFA) — UT 1972 → state 1987"},"geometry":{"type":"Point","coordinates":[93.6053,27.5539]}},{"type":"Feature","properties":{"id":"sikkim-st","name":"Sikkim — associate state (35th Amdt 1974) → full state 1975 (36th Amdt)"},"geometry":{"type":"Point","coordinates":[88.5122,27.533]}}]},"style":{"color":"#2e7d5b","markerRadius":7},"defaultOn":true,"labelKey":"name"},{"id":"acquired","name":"Acquired territories","description":"Goa (1961) and Puducherry (1954) — cession, conquest, plebiscite.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"goa-acq","name":"Goa, Daman & Diu — liberated from Portugal 1961; Goa a state 1987"},"geometry":{"type":"Point","coordinates":[73.8278,15.4989]}},{"type":"Feature","properties":{"id":"pondi-acq","name":"Puducherry — ceded by France (de facto 1954)"},"geometry":{"type":"Point","coordinates":[79.8083,11.9416]}}]},"style":{"color":"#7a4a2a","markerRadius":7},"defaultOn":false,"labelKey":"name"}],"facts":[{"id":"f1","text":"Article 1: \"India, that is Bharat, shall be a Union of States\" — states have no right to secede. Territory of India = states + UTs + acquired territories (First Schedule lists names & extents)."},{"id":"f2","text":"Article 2: Parliament may admit or establish new states. Article 3: form new states, alter areas, boundaries or names — by SIMPLE majority, with the President’s prior recommendation; the concerned state legislature’s view is NOT binding."},{"id":"f3","text":"Dhar Commission (1948) and the JVP Committee (Nehru–Patel–Pattabhi Sitaramayya, 1948) both rejected language as the sole basis for states."},{"id":"f4","text":"Potti Sriramulu’s 56-day fast (died Dec 1952) forced the creation of Andhra State (1953, capital Kurnool) — the first linguistic state, carved out of Madras.","linkedLayerId":"andhra-spark"},{"id":"f5","text":"Fazl Ali Commission / SRC (1953; members K.M. Panikkar & H.N. Kunzru) rejected \"one language, one state\" → States Reorganisation Act 1956 + 7th Amendment: 14 states + 6 UTs."},{"id":"f6","text":"Bombay split into Maharashtra + Gujarat (1960); Punjab split into Punjab + Haryana (1966) with Chandigarh as a shared-capital UT.","linkedLayerId":"bifurcations"},{"id":"f7","text":"North-East: Nagaland state 1963 (Art 371A); North-Eastern Areas (Reorganisation) Act 1971 → Meghalaya, Manipur, Tripura states (1972), Mizoram & Arunachal UTs (1972) → states in 1987 (Mizoram under Art 371G).","linkedLayerId":"ne-wave"},{"id":"f8","text":"Sikkim: associate state via the 35th Amendment (1974), full state via the 36th (1975) after a plebiscite — Article 371F."},{"id":"f9","text":"India can acquire foreign territory by cession, occupation, conquest, purchase, gift, lease or plebiscite — e.g. Goa, Daman & Diu (1961), Puducherry, Sikkim.","linkedLayerId":"acquired"},{"id":"f10","text":"Year 2000: Chhattisgarh (from MP), Uttarakhand (from UP), Jharkhand (from Bihar). 2014: Telangana, the 29th state. After J&K Reorganisation (2019): 28 states + 8 UTs (as of Jan 2025)."}],"events":[{"id":"e1","date":"1953","label":"1953 — Andhra","description":"Andhra State created out of Madras after Potti Sriramulu’s death — the linguistic dam breaks.","showLayers":["andhra-spark"],"view":{"center":[15.5,79.5],"zoom":6}},{"id":"e2","date":"1956","label":"1956 — SRA","description":"Fazl Ali Commission → States Reorganisation Act 1956 (7th Amendment): 14 states + 6 UTs.","view":{"center":[21.5,82],"zoom":4.5}},{"id":"e3","date":"1960","label":"1960 — Bombay split","description":"Maharashtra and Gujarat created from bilingual Bombay State (1 May 1960).","showLayers":["bifurcations"],"view":{"center":[20.5,74.5],"zoom":5.5}},{"id":"e4","date":"1963","label":"1963 — Nagaland","description":"Nagaland becomes the 16th state (13th Amendment; special provisions under Art 371A).","showLayers":["ne-wave"],"view":{"center":[25.8,93.5],"zoom":6}},{"id":"e5","date":"1972","label":"1971–72 — NE reorganised","description":"NEAR Act 1971: Meghalaya, Manipur, Tripura become states; Mizoram & Arunachal become UTs.","showLayers":["ne-wave"],"view":{"center":[25,92.8],"zoom":6}},{"id":"e6","date":"1975","label":"1975 — Sikkim","description":"Sikkim becomes a full state (36th Amendment, Art 371F).","view":{"center":[27.53,88.51],"zoom":7}},{"id":"e7","date":"1987","label":"1987 — Mizoram, Arunachal, Goa","description":"Mizoram (53rd Amdt, Art 371G) and Arunachal become states; Goa separated from Daman & Diu as a state.","view":{"center":[23.7,92.7],"zoom":6}},{"id":"e8","date":"2000","label":"2000 — Three new states","description":"Chhattisgarh (1 Nov), Uttarakhand (9 Nov), Jharkhand (15 Nov).","showLayers":["bifurcations"],"view":{"center":[25,82],"zoom":5}},{"id":"e9","date":"2014-06-02","label":"2014 — Telangana","description":"Telangana becomes the 29th state; Hyderabad shared capital for 10 years.","view":{"center":[17.8,79],"zoom":6}}],"quiz":[{"id":"q1","type":"mcq","question":"Parliament can form a new state or alter the boundary/name of an existing state under Article 3 by:","options":["Two-thirds special majority","Simple majority","Special majority + state ratification","Unanimous resolution of both Houses"],"answerIndex":1,"explanation":"Article 3 needs only a simple majority (plus the President’s prior recommendation). The affected state’s opinion is sought but not binding — which is why India is called \"an indestructible Union of destructible states.\""},{"id":"q2","type":"mcq","question":"The States Reorganisation Commission (1953) was chaired by:","options":["S.K. Dhar","K.M. Panikkar","Fazl Ali","H.N. Kunzru"],"answerIndex":2,"explanation":"Fazl Ali chaired it; Panikkar and Kunzru were members. It led to the SRA 1956 — 14 states + 6 UTs."},{"id":"q3","type":"map_click","question":"Click the city where Potti Sriramulu’s fast (1952) forced the creation of the first linguistic state.","answer":{"lat":13.0827,"lng":80.2707,"toleranceKm":150},"explanation":"Madras — Sriramulu fasted for a Telugu state to be carved out of Madras State; Andhra was created in 1953 with Kurnool as capital."},{"id":"q4","type":"mcq","question":"Nagaland became a state in 1963 with special provisions under which Article?","options":["Art 370","Art 371A","Art 371F","Art 371G"],"answerIndex":1,"explanation":"371A = Nagaland (1963), 371F = Sikkim (1975), 371G = Mizoram (1987)."},{"id":"q5","type":"map_click","question":"Click the state that became the 23rd state of India in 1987 under Article 371G.","answer":{"lat":23.7307,"lng":92.7173,"toleranceKm":160},"explanation":"Mizoram — UT in 1972 (NEAR Act), full state on 20 Feb 1987 after the Mizo Accord (1986)."},{"id":"q6","type":"mcq","question":"As of January 2025, India has:","options":["29 states and 7 UTs","28 states and 8 UTs","28 states and 9 UTs","29 states and 6 UTs"],"answerIndex":1,"explanation":"28 states + 8 UTs after the J&K Reorganisation Act 2019 (J&K and Ladakh as UTs) and the DNH–Daman & Diu merger (2020)."},{"id":"q7","type":"mcq","question":"The names and territorial extents of the states are listed in which Schedule?","options":["First Schedule","Fourth Schedule","Seventh Schedule","Tenth Schedule"],"answerIndex":0,"explanation":"First Schedule = states & UTs and their extents. (Fourth = Rajya Sabha seats; Seventh = the three lists; Tenth = anti-defection.)"}]},"position":22,"hash":"7cc13efffb4b1fd3c0841820ce65b5647cfafdf027583c0bad359679ac3860b8"},{"body":{"id":"polity-sixth-schedule-local-govt","subject":"polity","unit":"Grassroots","tags":["mizoram","assam","meghalaya","tripura","nagaland","northeast","lawngtlai","siaha","panchayat"],"title":"Sixth Schedule & Local Government","summary":"Art 244(2) ADCs in Assam, Meghalaya, Tripura & Mizoram — plus the 73rd/74th Amendment panchayat and municipal system.","focus":"Two grassroots geographies: (1) Sixth Schedule ADCs (Parts I, II, IIA, III) in four NE states — max 30 members, 5-year term, Governor as executive head in Mizoram; (2) the 73rd/74th Amendments (1992) everywhere else. Nagaland, Meghalaya & Mizoram are exempt from Part IX.","view":{"center":[24.6,92.3],"zoom":6},"basemap":"natgeo","theme":{"accent":"#4a5fa5"},"layers":[{"id":"sixth-states","name":"Sixth Schedule states","description":"Assam (I), Meghalaya (II), Tripura (IIA), Mizoram (III) — parts fixed by the NEAR Act 1971.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"assam-6","name":"Assam (Part I)"},"geometry":{"type":"Polygon","coordinates":[[[89.7,26.2],[92,27.3],[94.5,27.6],[96,27.3],[95.2,26.6],[93.5,25.5],[92.5,24.8],[92.2,25],[90.6,25.4],[89.8,25.6],[89.7,26.2]]]}},{"type":"Feature","properties":{"id":"meghalaya-6","name":"Meghalaya (Part II)"},"geometry":{"type":"Polygon","coordinates":[[[89.85,25.55],[90.6,25.9],[91.8,26],[92.6,25.6],[92.3,25.1],[91,25.1],[89.85,25.55]]]}},{"type":"Feature","properties":{"id":"tripura-6","name":"Tripura (Part IIA)"},"geometry":{"type":"Polygon","coordinates":[[[91.15,23.9],[91.7,24.4],[92.3,24.2],[92.15,23.7],[91.6,22.95],[91.25,23.15],[91.15,23.9]]]}},{"type":"Feature","properties":{"id":"mizoram-6","name":"Mizoram (Part III)"},"geometry":{"type":"Polygon","coordinates":[[[92.25,24.2],[92.7,24.4],[93.15,24.05],[93.4,23.3],[93.1,22.3],[92.7,21.95],[92.35,22.7],[92.25,24.2]]]}}]},"style":{"color":"#4a5fa5","fillColor":"#4a5fa5","fillOpacity":0.1,"weight":2,"pattern":"dots"},"defaultOn":true,"labelKey":"name"},{"id":"adc-seats","name":"ADC headquarters","description":"Where each Autonomous District Council sits — Lai, Mara, Chakma; Khasi, Garo, Jaintia; Karbi Anglong, Dima Hasao, BTC; TTAADC.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"lai-adc","name":"Lai ADC — HQ Lawngtlai (Mizoram)"},"geometry":{"type":"Point","coordinates":[92.8977,22.5286]}},{"type":"Feature","properties":{"id":"mara-adc","name":"Mara ADC — HQ Siaha (Mizoram)"},"geometry":{"type":"Point","coordinates":[92.9793,22.4918]}},{"type":"Feature","properties":{"id":"chakma-adc","name":"Chakma ADC — HQ Chawngte/Kamalanagar (Mizoram)"},"geometry":{"type":"Point","coordinates":[92.6396,22.7412]}},{"type":"Feature","properties":{"id":"kaziranga-karbi","name":"Karbi Anglong AC — Diphu (Assam)"},"geometry":{"type":"Point","coordinates":[93.4306,25.8433]}},{"type":"Feature","properties":{"id":"dima-hasao","name":"Dima Hasao (N.C. Hills) AC — Haflong (Assam)"},"geometry":{"type":"Point","coordinates":[93.0169,25.1698]}},{"type":"Feature","properties":{"id":"btc","name":"Bodoland Territorial Council — Kokrajhar (Assam)"},"geometry":{"type":"Point","coordinates":[90.2661,26.4014]}},{"type":"Feature","properties":{"id":"khasi-adc","name":"Khasi Hills ADC — Shillong (Meghalaya)"},"geometry":{"type":"Point","coordinates":[91.8933,25.5788]}},{"type":"Feature","properties":{"id":"garo-adc","name":"Garo Hills ADC — Tura (Meghalaya)"},"geometry":{"type":"Point","coordinates":[90.2201,25.5143]}},{"type":"Feature","properties":{"id":"jaintia-adc","name":"Jaintia Hills ADC — Jowai (Meghalaya)"},"geometry":{"type":"Point","coordinates":[92.1931,25.4504]}},{"type":"Feature","properties":{"id":"ttaadc","name":"Tripura Tribal Areas ADC — Khumulwng (Tripura)"},"geometry":{"type":"Point","coordinates":[91.4074,23.9137]}}]},"style":{"color":"#a5504a","markerRadius":7,"glow":true},"defaultOn":true,"labelKey":"name"},{"id":"panchayat-launch","name":"Panchayati Raj origins","description":"Nagaur (2 Oct 1959) and Andhra Pradesh — the first adopters.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"nagaur","name":"Nagaur, Rajasthan — Nehru launches Panchayati Raj, 2 Oct 1959"},"geometry":{"type":"Point","coordinates":[73.7337,27.2]}},{"type":"Feature","properties":{"id":"andhra-pr","name":"Andhra Pradesh — second state to adopt Panchayati Raj (1959)"},"geometry":{"type":"Point","coordinates":[79.74,15.91]}}]},"style":{"color":"#2e7d5b","markerRadius":7},"defaultOn":false,"labelKey":"name"}],"facts":[{"id":"f1","text":"The Sixth Schedule (Art 244(2) & 275(1)) governs tribal areas in Assam, Meghalaya, Tripura and Mizoram through Autonomous District Councils. The Fifth Schedule covers scheduled areas in the other states.","linkedLayerId":"sixth-states"},{"id":"f2","text":"Origin: the Bordoloi Sub-Committee (Gopinath Bordoloi, CM of Assam) of the Constituent Assembly recommended District & Regional Councils; Saprawnga and Khawtinkhuma were co-opted to represent the Mizos."},{"id":"f3","text":"Each ADC: up to 30 members (up to 4 nominated by the Governor, rest elected by adult suffrage), 5-year term (extendable 1 year); members must be citizens, 25+, registered voters."},{"id":"f4","text":"Lushai Hills District Council formed 1952 → renamed Mizo Hills District Council 1954. The NEAR Act 1971 split the Schedule into Parts I (Assam), II (Meghalaya), IIA (Tripura), III (Mizoram)."},{"id":"f5","text":"Mizoram’s three ADCs: Lai (Lawngtlai), Mara (Siaha), Chakma (Chawngte) — under the Mizoram ADC Rules 1974. The Governor is the executive head; DC laws need the Governor’s assent.","linkedLayerId":"adc-seats"},{"id":"f6","text":"Each ADC has an Executive Committee: one elected Chief Executive Member + 2 Executive Members. ADCs hold legislative, executive, judicial (Village Courts) and financial powers."},{"id":"f7","text":"73rd Amendment (1992): Panchayati Raj constitutionalised — Part IX + Eleventh Schedule (29 subjects). 74th Amendment: municipalities — Part IXA + Twelfth Schedule (18 subjects)."},{"id":"f8","text":"Three-tier panchayats (village–intermediate–district); SC/ST reservation in proportion to population; one-third of seats for women; fixed 5-year term; State Election Commission conducts polls; State Finance Commission every 5 years."},{"id":"f9","text":"Balwant Rai Mehta Committee (1957) recommended democratic decentralisation; Rajasthan (Nagaur, 2 Oct 1959) launched Panchayati Raj first, Andhra Pradesh second.","linkedLayerId":"panchayat-launch"},{"id":"f10","text":"Part IX does NOT apply to Nagaland, Meghalaya and Mizoram, to Sixth Schedule areas, or (mostly) to J&K — their traditional/ADC institutions continue instead."},{"id":"f11","text":"Municipal types under the 74th: Nagar Panchayat (transitional), Municipal Council (smaller urban), Municipal Corporation (larger urban)."}],"events":[{"id":"e1","date":"1949","label":"1949 — Sixth Schedule adopted","description":"Bordoloi Sub-Committee’s scheme enters the Constitution as the Sixth Schedule."},{"id":"e2","date":"1952","label":"1952 — Lushai Hills DC","description":"The Lushai Hills District Council comes into being (renamed Mizo Hills DC, 1954).","view":{"center":[23.4,92.8],"zoom":7}},{"id":"e3","date":"1959-10-02","label":"1959 — Panchayati Raj","description":"Nehru inaugurates Panchayati Raj at Nagaur, Rajasthan, on Gandhi Jayanti; Andhra follows.","showLayers":["panchayat-launch"],"view":{"center":[25,76],"zoom":5}},{"id":"e4","date":"1971","label":"1971 — NEAR Act","description":"Sixth Schedule reorganised into Parts I, II, IIA and III as the North-East is redrawn.","showLayers":["sixth-states"],"view":{"center":[24.6,92.3],"zoom":6}},{"id":"e5","date":"1972","label":"1972 — Mizo District ADCs","description":"Pawi–Lakher Regional Council splits into Pawi (Lai), Lakher (Mara) and Chakma Regional Councils → ADCs under the 1974 Rules.","showLayers":["adc-seats"],"view":{"center":[22.6,92.8],"zoom":8}},{"id":"e6","date":"1992","label":"1992 — 73rd & 74th","description":"Panchayats (Part IX, 11th Schedule) and municipalities (Part IXA, 12th Schedule) get constitutional status."}],"quiz":[{"id":"q1","type":"mcq","question":"The Sixth Schedule provides for the administration of tribal areas in which states?","options":["All North-Eastern states","Assam, Meghalaya, Tripura, Mizoram","Assam, Nagaland, Manipur, Mizoram","Meghalaya, Nagaland, Sikkim, Tripura"],"answerIndex":1,"explanation":"A-M-T-M: Assam (Part I), Meghalaya (II), Tripura (IIA), Mizoram (III). Nagaland is protected by Art 371A, not the Sixth Schedule."},{"id":"q2","type":"mcq","question":"The sub-committee that recommended District & Regional Councils for NE tribal areas was headed by:","options":["B.N. Rau","Gopinath Bordoloi","Fazl Ali","Balwant Rai Mehta"],"answerIndex":1,"explanation":"Gopinath Bordoloi, then CM of Assam. Saprawnga and Khawtinkhuma represented the Mizos in its deliberations."},{"id":"q3","type":"map_click","question":"Click the headquarters of the Mara Autonomous District Council.","answer":{"lat":22.4918,"lng":92.9793,"toleranceKm":60},"explanation":"Siaha — Mara ADC. Lai sits at Lawngtlai and Chakma at Chawngte (Kamalanagar)."},{"id":"q4","type":"mcq","question":"An Autonomous District Council under the Sixth Schedule has a maximum of:","options":["20 members","26 members","30 members","40 members"],"answerIndex":2,"explanation":"Up to 30 members — a maximum of 4 nominated by the Governor, the rest directly elected; 5-year term."},{"id":"q5","type":"map_click","question":"Click the place where Panchayati Raj was first inaugurated on 2 October 1959.","answer":{"lat":27.2,"lng":73.7337,"toleranceKm":130},"explanation":"Nagaur, Rajasthan — inaugurated by Nehru; Andhra Pradesh adopted it next."},{"id":"q6","type":"mcq","question":"The Eleventh Schedule (73rd Amendment) lists how many subjects for panchayats?","options":["18","22","29","52"],"answerIndex":2,"explanation":"29 subjects for panchayats; the Twelfth Schedule lists 18 for municipalities."},{"id":"q7","type":"mcq","question":"Part IX (Panchayats) does NOT apply to which of these states?","options":["Assam, Tripura, Manipur","Nagaland, Meghalaya, Mizoram","Sikkim, Goa, Mizoram","Nagaland, Assam, Arunachal"],"answerIndex":1,"explanation":"Nagaland, Meghalaya and Mizoram are exempt — traditional institutions and ADCs operate there instead."}]},"position":23,"hash":"a839ca1f04fc7693a3153974490ca69841850507c6290f869dcb5bac1c37544c"},{"body":{"id":"polity-parliament","subject":"polity","unit":"Institutions","tags":["delhi","constitution","parliament","states"],"title":"Parliament (Art 79–108)","summary":"Structure, sessions, Speaker, devices of proceedings, Rajya Sabha vs Lok Sabha — and how Parliament reaches into the State List.","focus":"Art 79: Parliament = President + RS + LS. Track the numbers (250/238+12; 550 max, 543 filled; quorum 1/10) and the four routes into the State List: Emergency/356, Art 249 (RS ⅔ resolution), Art 252 (two+ states resolve), Art 253 (treaties).","view":{"center":[26.5,80],"zoom":5},"basemap":"natgeo","theme":{"accent":"#4a5fa5"},"layers":[{"id":"sansad","name":"Seat of Parliament","description":"Sansad Bhavan — where all three components of Parliament converge.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"sansad","name":"Sansad Bhavan, New Delhi — President + Rajya Sabha + Lok Sabha (Art 79)"},"geometry":{"type":"Point","coordinates":[77.2082,28.6172]}}]},"style":{"color":"#4a5fa5","markerRadius":9,"glow":true},"defaultOn":true,"labelKey":"name"}],"facts":[{"id":"f1","text":"Article 79: Parliament = President + Council of States (Rajya Sabha) + House of the People (Lok Sabha). The President is part of Parliament though not a member of either House — assent is mandatory for a Bill to become an Act.","linkedLayerId":"sansad"},{"id":"f2","text":"Article 80 — Rajya Sabha: max 250 = 238 representatives of states/UTs + 12 nominated by the President (literature, science, art, social service). State members are elected by elected MLAs via proportional representation by single transferable vote; seats allocated per the Fourth Schedule."},{"id":"f3","text":"Lok Sabha: constitutional max 550 (530 states + 20 UTs); currently 543 elected. UT members chosen by direct election under the UT (Direct Election to the House of the People) Act, 1965. Anglo-Indian nomination (2 members) removed by the 104th Amendment, effective Jan 2020."},{"id":"f4","text":"Article 83: Rajya Sabha is a continuing house — never dissolved; one-third retires every second year (6-year member term). Lok Sabha: 5 years from first meeting; extendable during Emergency one year at a time, not beyond 6 months after the proclamation ends."},{"id":"f5","text":"Four routes for Parliament into the State List: (1) National Emergency or President’s Rule (Art 356); (2) Art 249 — RS resolution by ⅔ present & voting, in the national interest; (3) Art 252 — two or more state legislatures resolve; (4) Art 253 — implementing international treaties."},{"id":"f6","text":"Speaker: final interpreter of the Constitution/Rules/conventions inside the LS; casting vote only on a tie; presides over joint sittings; decides Money Bill status (final); decides Tenth-Schedule defection disqualifications; ex-officio chairman of the Indian Parliamentary Group."},{"id":"f7","text":"Speaker Pro Tem: senior-most LS member, appointed and sworn in by the President; administers oath to new members and enables election of the new Speaker, then the office ceases. Panel of Chairpersons: up to 10 members nominated by the Speaker."},{"id":"f8","text":"Leader of the House = the PM (or a minister of the LS the PM appoints). Leader of the Opposition = leader of the largest opposition party with at least one-tenth of total seats; salary and facilities equal to a Cabinet minister."},{"id":"f9","text":"Sessions: max gap between two sessions is 6 months; usually Budget (Feb–May), Monsoon (Jul–Sep), Winter (Nov–Dec). Adjournment suspends a sitting; adjournment sine die = indefinite; prorogation ends the session; dissolution applies to LS only."},{"id":"f10","text":"Devices: Question Hour is the first hour (starred = oral + supplementaries; unstarred = written; short-notice). Zero Hour — not in the Rules — is the gap between Question Hour and the agenda. Adjournment and censure motions: Lok Sabha only; censure does not force resignation (no-confidence does)."},{"id":"f11","text":"Article 100: questions decided by majority of members present and voting; presiding officer votes only to break a tie. Quorum = one-tenth of the total membership of the House."},{"id":"f12","text":"Article 108 — joint sitting (summoned by the President; Speaker presides; LS’s numbers usually prevail) when a Bill is rejected by the other House, the Houses disagree on amendments, or 6 months pass without passage. Never for a Money Bill."},{"id":"f13","text":"RS equal to LS: ordinary bills, President’s election/impeachment, ordinances, all three emergencies, constitutional amendments. RS weaker: Money Bills (LS only; RS returns within 14 days), no vote on demands for grants, ministers collectively responsible to LS alone. RS special: Art 249 (State List) and Art 312 (new All-India Services); alone initiates VP’s removal."}],"events":[{"id":"e1","date":"1965","label":"1965 — UT Direct Election Act","description":"Parliament prescribes direct election for Lok Sabha members from Union Territories."},{"id":"e2","date":"2020-01","label":"2020 — Anglo-Indian seats end","description":"The 104th Amendment (2019) removes the President’s nomination of 2 Anglo-Indian members, effective January 2020."},{"id":"e3","date":"2026-02","label":"Budget Session (Feb–May)","description":"First and longest session of the parliamentary year — the Union Budget is presented and voted.","showLayers":["sansad"],"view":{"center":[28.617,77.208],"zoom":11}},{"id":"e4","date":"2026-07","label":"Monsoon Session (Jul–Sep)","description":"Second session — remember the rule: never more than 6 months between two sessions."},{"id":"e5","date":"2026-11","label":"Winter Session (Nov–Dec)","description":"Third session closes the year — three sessions is convention, not a constitutional requirement."}],"quiz":[{"id":"q1","type":"mcq","question":"Under Article 79, Parliament consists of:","options":["Lok Sabha and Rajya Sabha only","President, Rajya Sabha and Lok Sabha","President, PM and both Houses","Speaker, Rajya Sabha and Lok Sabha"],"answerIndex":1,"explanation":"The President is a component of Parliament without being a member of either House — assent is mandatory for every Act."},{"id":"q2","type":"mcq","question":"Maximum strength of the Rajya Sabha, and the nominated component?","options":["238, with 10 nominated","250, with 12 nominated","245, with 15 nominated","260, with 12 nominated"],"answerIndex":1,"explanation":"250 = up to 238 state/UT representatives + 12 nominated for literature, science, art, social service (Art 80). Seats per the Fourth Schedule."},{"id":"q3","type":"mcq","question":"Under Article 249, Parliament can legislate on a State List subject if:","options":["The President orders it","The Rajya Sabha passes a resolution by two-thirds of members present and voting","The Supreme Court permits it","A majority of state legislatures consent"],"answerIndex":1,"explanation":"Art 249: RS resolution by ⅔ present & voting in the national interest. Other routes: Emergency/356, Art 252 (two+ states), Art 253 (treaties)."},{"id":"q4","type":"mcq","question":"Who decides, finally, whether a bill is a Money Bill?","options":["The President","The Finance Minister","The Speaker of the Lok Sabha","The Chairman of the Rajya Sabha"],"answerIndex":2,"explanation":"The Speaker’s decision is final. The Speaker also presides over joint sittings and decides Tenth-Schedule defection cases in the LS."},{"id":"q5","type":"mcq","question":"A joint sitting under Article 108 can NEVER be summoned for:","options":["An ordinary bill","A financial bill","A Money Bill","A constitutional amendment bill rejected by one House"],"answerIndex":2,"explanation":"Money Bills are excluded from Art 108 — the RS can only return them within 14 days. (Amendment bills also bypass joint sittings since both Houses must pass them, but the Article’s express exclusion is the Money Bill.)"},{"id":"q6","type":"mcq","question":"The quorum to constitute a meeting of either House is:","options":["One-fourth of total members","One-tenth of total members","One-third of total members","Fifty members"],"answerIndex":1,"explanation":"One-tenth of the total membership (Art 100 context). The presiding officer adjourns or suspends the sitting without quorum."},{"id":"q7","type":"map_click","question":"Click the city where all three components of Parliament — President, Rajya Sabha, Lok Sabha — converge.","answer":{"lat":28.6172,"lng":77.2082,"toleranceKm":120},"explanation":"New Delhi — Sansad Bhavan."}]},"position":24,"hash":"84fbc50b3da87801d9317e25c20be8535ce98531b485998b0a5c7cc8a86da935"},{"body":{"id":"polity-judiciary","subject":"polity","unit":"Institutions","tags":["delhi","constitution","mizoram","nagaland","assam","northeast","bihar"],"title":"Judiciary, Writs & PIL","summary":"One integrated pyramid: Supreme Court (Art 124–147), Article 32 and the five writs, PIL from Hussainara Khatoon, and the joint High Court system.","focus":"Single integrated judiciary: SC → High Courts → subordinate courts. Master the 5 writs (Habeas Corpus, Mandamus, Prohibition, Certiorari, Quo Warranto), Art 32 vs Art 226, and PIL — locus standi does not apply.","view":{"center":[25.5,84.5],"zoom":5},"basemap":"natgeo","theme":{"accent":"#4a5fa5"},"layers":[{"id":"apex","name":"The apex","description":"Supreme Court of India — guardian and final interpreter of the Constitution.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"sc","name":"Supreme Court of India, New Delhi — Part V Ch IV, Articles 124–147"},"geometry":{"type":"Point","coordinates":[77.2384,28.6219]}}]},"style":{"color":"#4a5fa5","markerRadius":9,"glow":true},"defaultOn":true,"labelKey":"name"},{"id":"gauhati","name":"Joint HC: Gauhati system","description":"One High Court for four states — principal seat + Kohima, Aizawl, Itanagar benches.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"ghc","name":"Gauhati High Court (Guwahati) — principal seat; jurisdiction over Assam, Nagaland, Mizoram & Arunachal Pradesh"},"geometry":{"type":"Point","coordinates":[91.7362,26.1445]}},{"type":"Feature","properties":{"id":"ghc-kohima","name":"Kohima Bench (Nagaland)"},"geometry":{"type":"Point","coordinates":[94.1086,25.6751]}},{"type":"Feature","properties":{"id":"ghc-aizawl","name":"Aizawl Bench (Mizoram)"},"geometry":{"type":"Point","coordinates":[92.7173,23.7307]}},{"type":"Feature","properties":{"id":"ghc-itanagar","name":"Itanagar Bench (Arunachal Pradesh)"},"geometry":{"type":"Point","coordinates":[93.6053,27.0844]}}]},"style":{"color":"#2e7d5b","markerRadius":7},"defaultOn":true,"labelKey":"name"},{"id":"gauhati-spokes","name":"Bench spokes","description":"Jurisdiction radiating from the principal seat.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"sp-k","name":"Guwahati → Kohima"},"geometry":{"type":"LineString","coordinates":[[91.7362,26.1445],[94.1086,25.6751]]}},{"type":"Feature","properties":{"id":"sp-a","name":"Guwahati → Aizawl"},"geometry":{"type":"LineString","coordinates":[[91.7362,26.1445],[92.7173,23.7307]]}},{"type":"Feature","properties":{"id":"sp-i","name":"Guwahati → Itanagar"},"geometry":{"type":"LineString","coordinates":[[91.7362,26.1445],[93.6053,27.0844]]}}]},"style":{"color":"#2e7d5b","weight":2,"flow":true,"dashArray":"4 8"},"defaultOn":true,"labelKey":"name"},{"id":"pil","name":"Birth of PIL","description":"Hussainara Khatoon (1979) — Bihar’s undertrials and the right to a speedy trial.","kind":"vector","data":{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":"patna","name":"Bihar — Hussainara Khatoon v. State of Bihar (9 Mar 1979): the first great PIL, ~40,000 undertrials released"},"geometry":{"type":"Point","coordinates":[85.1376,25.5941]}}]},"style":{"color":"#a5504a","markerRadius":8,"glow":true},"defaultOn":true,"labelKey":"name"}],"facts":[{"id":"f1","text":"India has a single, integrated judicial system: the Supreme Court at the top, High Courts at state level, subordinate courts below — all links of one chain, with the SC running judicial administration.","linkedLayerId":"apex"},{"id":"f2","text":"The Supreme Court is established by Part V, Chapter IV; Articles 124–147 lay down its composition and jurisdiction. It is the guardian and final interpreter of the Constitution."},{"id":"f3","text":"Independence is secured by: appointment by the President, high qualifications, removal only by difficult impeachment, protected salaries and pensions, an independent establishment, and functional autonomy."},{"id":"f4","text":"A High Court exists for each state, but two or more states can by mutual consent have a Joint High Court — the Gauhati High Court serves Assam, Nagaland, Mizoram and Arunachal Pradesh, with benches at Kohima, Aizawl and Itanagar.","linkedLayerId":"gauhati"},{"id":"f5","text":"The SC is the arbiter of federal disputes: Centre vs state(s); Centre + state(s) vs other state(s); state vs state."},{"id":"f6","text":"Article 32 (Right to Constitutional Remedies) lets any individual move the SC directly for enforcement of Fundamental Rights; Art 32(2) confers writ jurisdiction. Ambedkar called it \"the heart and soul of the Constitution\"."},{"id":"f7","text":"Five writs — Habeas Corpus: produce a detained person, valid reasons or release (not against legislative/court contempt proceedings). Mandamus: command a public authority to perform a duty (never against a private individual). Prohibition: stop a lower court acting outside jurisdiction (judicial/quasi-judicial only). Certiorari: transfer/quash a lower court’s decision for excess or lack of jurisdiction. Quo Warranto: \"by what authority\" — tests a claim to public office."},{"id":"f8","text":"Writ jurisdiction differs: under Art 32 the SC acts only for Fundamental Rights; High Courts (Art 226) can issue writs for FRs and for other legal rights — wider in scope."},{"id":"f9","text":"PIL originated in the USA (there \"Social Action Litigation\"); rests on pro bono publico — for the common good. Only the SC and HCs can entertain it; it is judge-made law, regulated by neither executive nor legislature."},{"id":"f10","text":"In PIL, locus standi does not apply — any member of the public may petition on behalf of those who cannot; even a postcard to the court can be a petition, fees can be waived, and free legal aid directed.","linkedLayerId":"pil"},{"id":"f11","text":"Hussainara Khatoon v. State of Bihar (9 March 1979) — widely counted the first PIL: Bihar undertrials jailed beyond their maximum possible sentences; the Court made speedy trial the issue and ordered the release of nearly 40,000 undertrials.","linkedLayerId":"pil"},{"id":"f12","text":"Judicial activism: PIL and Lok Adalats expanded the reach of Fundamental Rights and forced the executive and legislature to discharge constitutional obligations — justice made accessible to the poor and marginalised."}],"events":[{"id":"e1","date":"1950-01-28","label":"1950 — SC inaugurated","description":"The Supreme Court comes into being under the new Constitution (Part V, Ch IV; Arts 124–147), replacing the Federal Court.","showLayers":["apex"],"view":{"center":[28.62,77.24],"zoom":10}},{"id":"e2","date":"1979-03-09","label":"1979 — Hussainara Khatoon","description":"The first great PIL: right to speedy trial; ~40,000 Bihar undertrials released.","showLayers":["pil"],"view":{"center":[25.6,85.1],"zoom":7}},{"id":"e3","date":"1990","label":"Joint HC in action","description":"The Gauhati High Court model: one principal seat, benches at Kohima, Aizawl and Itanagar serving four states.","showLayers":["gauhati","gauhati-spokes"],"view":{"center":[25.4,92.9],"zoom":6}}],"quiz":[{"id":"q1","type":"mcq","question":"Which Article did Dr Ambedkar call \"the heart and soul of the Constitution\"?","options":["Article 14","Article 21","Article 32","Article 226"],"answerIndex":2,"explanation":"Art 32 — the Right to Constitutional Remedies; the fundamental of all Fundamental Rights, without which the Constitution would be a nullity."},{"id":"q2","type":"mcq","question":"Which writ CANNOT be issued against a private individual?","options":["Habeas Corpus","Mandamus","Quo Warranto","Certiorari"],"answerIndex":1,"explanation":"Mandamus commands public authorities/officials to perform duties — never a private individual. (Habeas Corpus can run against private detention.)"},{"id":"q3","type":"mcq","question":"The writ asking \"by what authority do you hold this office?\" is:","options":["Prohibition","Certiorari","Quo Warranto","Mandamus"],"answerIndex":2,"explanation":"Quo Warranto tests the legality of a person’s claim to a public office and prevents illegal usurpation."},{"id":"q4","type":"mcq","question":"The writ jurisdiction of High Courts compared to the Supreme Court is:","options":["Narrower — FRs only","Wider — FRs plus other legal rights","Identical","Limited to criminal matters"],"answerIndex":1,"explanation":"Art 226 (HCs) covers Fundamental Rights AND other legal rights; Art 32 (SC) is confined to Fundamental Rights."},{"id":"q5","type":"mcq","question":"Hussainara Khatoon v. State of Bihar (1979) is celebrated as:","options":["The basic structure case","The first major Public Interest Litigation","The case that created Lok Adalats","The first habeas corpus case"],"answerIndex":1,"explanation":"It made the right to speedy trial central and led to the release of ~40,000 undertrials — PIL’s founding moment in India."},{"id":"q6","type":"map_click","question":"Click the Mizoram bench of the Gauhati High Court.","answer":{"lat":23.7307,"lng":92.7173,"toleranceKm":90},"explanation":"Aizawl — one of the three benches (Kohima, Aizawl, Itanagar) of the joint High Court serving four NE states."},{"id":"q7","type":"map_click","question":"Click the state whose undertrial prisoners gave India its first great PIL.","answer":{"lat":25.5941,"lng":85.1376,"toleranceKm":180},"explanation":"Bihar — Hussainara Khatoon, 9 March 1979."}]},"position":25,"hash":"7e473f3223c7250e4cfa74639b73a55c5562ffa5dac70c529c10e67da9348b29"}]$corpus$::jsonb) LOOP
